// The French of What's new, what each version changed (lib/whats-new.ts, app/whats-new.tsx) (i18n/fr/index.ts).
export const whatsNew: Record<string, string> = {
  "**The day stands out in every chat**: over the first message of each day, groups and Chat with myself too, the day shows in bold between two lines: **Today**, **Yesterday**, the weekday within the last week, and before that the weekday and date. See [Chat through a relay](#relay).":
    "**Le jour se voit dans chaque discussion** : au-dessus du premier message de chaque jour, groupes et Discussion avec moi-même compris, le jour s’affiche en gras entre deux traits : **Aujourd’hui**, **Hier**, le jour de la semaine dans la dernière semaine, et avant le jour avec sa date. Voir [Discuter par un relais](#relay).",
  "**The microphone writes, if you like**: tap the microphone beside the message field and choose **Speak to write**, and from then on holding it writes what you say into the field, until you choose **Voice message** again. The choice stays for every chat. See [Chat through a relay](#relay).": "**Le micro écrit, si tu veux**: touche le micro à côté du champ du message et choisis **Parler pour écrire**, et dès lors, maintenu, il écrit dans le champ ce que tu dis, jusqu’à ce que tu choisisses de nouveau **Message vocal**. Le choix vaut pour chaque discussion. Voir [Discuter par un relais](#relay).",
  "**Ways on home**: once a relay is set, the line under the top bar of home is **Ways**, with a dot for each way your messages go out by and how many of them wait; a tap opens **Ways**. See [How Erevos picks the path](#paths).": "**Voies sur l’accueil**: dès qu’un relais est réglé, la ligne sous la barre du haut de l’accueil est **Voies**, avec un point pour chaque voie par laquelle partent tes messages et combien d’entre eux attendent ; un toucher ouvre **Voies**. Voir [Comment Erevos choisit la voie](#paths).",
  "**LoRa makes up for lost pieces, and long texts go shorter**: a text sent by LoRa in several pieces now goes with spare pieces, one for each four, so it comes whole even when a piece or two are lost on the air; older Erevos reads it as before. And long texts are packed, with nothing lost, before they are encrypted, when that makes them go in fewer bytes, to contacts whose Erevos unpacks them. See [Over a LoRa radio](#lora).": "**LoRa remplace les morceaux perdus, et les longs textes partent plus courts** : un texte envoyé par LoRa en plusieurs morceaux part maintenant avec des morceaux de secours, un pour quatre, et arrive donc entier même si un ou deux morceaux se perdent dans l'air ; un Erevos plus ancien le lit comme avant. Et les longs textes sont compressés, sans rien perdre, avant d'être chiffrés, quand ils prennent ainsi moins d'octets, pour les contacts dont l'Erevos les décompresse. Voir [Par une radio LoRa](#lora).",
  "**Ways at a glance**: **Settings** → **Relay and networks** → **Ways** shows each way your messages go out by, the relay, Nostr, the phones nearby, LoRa, SMS and Tor, with how each is now and a line under it: full when it works, faint when it reaches no one now, dashed when it is off. Above them, how many of your messages wait to go, an orange dot for each. Only the space that is open shows, never hidden chats. See [How Erevos picks the path](#paths).": "**Les voies d’un coup d’œil** : **Réglages** → **Relais et réseaux** → **Voies** montre chaque voie par laquelle partent tes messages, le relais, Nostr, les téléphones à proximité, LoRa, les SMS et Tor, avec l’état de chacune et une ligne dessous : pleine quand elle fonctionne, pâle quand elle n’atteint personne pour l’instant, en tirets quand elle est désactivée. Au-dessus, combien de tes messages attendent de partir, un point orange pour chacun. Seul l’espace ouvert s’affiche, jamais les discussions cachées. Voir [Comment Erevos choisit le chemin](#paths).",
  "**Answer a hidden contact's call with no PIN**: where hidden chats receive while closed, **Answer** on the ringing screen takes their contact's call at once, on a call screen with no name and no face, and the hidden chats stay closed; the small sign and the PIN still open them. See [Hidden chats](#hidden).": "**Répondre sans code PIN à l’appel d’un contact masqué** : là où les discussions masquées reçoivent une fois fermées, **Répondre** sur l’écran de l’appel le prend aussitôt, sur un écran sans nom ni visage, et les discussions masquées restent fermées ; le petit signe et le code PIN les ouvrent toujours. Voir [Discussions masquées](#hidden).",
  "**See yourself in a video call**: once their picture comes, yours stays in a small window in the top corner, on both phones; before, it vanished, and each side saw only the other. See [Chat through a relay](#relay).": "**Vois-toi dans un appel vidéo** : dès que l’image de l’autre arrive, la tienne reste dans une petite fenêtre dans le coin du haut, sur les deux téléphones ; avant, elle disparaissait, et chacun ne voyait que l’autre. Voir [Discuter par un relais](#relay).",
  "**Phones nearby are off until you turn them on**: Erevos no longer looks for phones nearby by itself, with Bluetooth, Wi-Fi Aware or on the same Wi-Fi, as on the same Wi-Fi it held a call back for up to a minute before it rang. Turn on **Look for phones nearby** under **Nearby, with no internet**, on **New chat**, to chat and call with no internet. See [Chat with a nearby phone](#nearby).": "**Les téléphones à proximité sont désactivés jusqu’à ce que tu les actives** : Erevos ne cherche plus de lui-même les téléphones à proximité, par Bluetooth, Wi-Fi Aware ou sur le même Wi-Fi, car sur le même Wi-Fi il retenait un appel jusqu’à une minute avant qu’il sonne. Active **Chercher les téléphones à proximité** sous **À proximité, sans internet**, dans **Nouvelle discussion**, pour discuter et appeler sans internet. Voir [Discuter avec un téléphone à proximité](#nearby).",
  "**Open a file with another app**: a file in a chat, a PDF say, has **Open** too, not only **Save**: the phone's app for it reads it from Erevos's memory, with no copy left on the phone. Erevos asks first, and never opens web pages, drawings or app packages that way. See [Chat through a relay](#relay).": "**Ouvrir un fichier avec une autre app** : un fichier dans une discussion, un PDF par exemple, a aussi **Ouvrir**, pas seulement **Enregistrer** : l’app du téléphone le lit dans la mémoire d’Erevos, sans copie laissée sur le téléphone. Erevos demande d’abord, et n’ouvre jamais ainsi les pages web, les dessins ni les paquets d’app. Voir [Discuter par un relais](#relay).",
  "**Shared chats say how far they are, on both phones**: chats a contact shared from a relay your Erevos does not take from by itself show **Coming, 40%** once you tap them, and their phone says it is taking them; if they did not come, both phones say so and yours buzzes twice. See [Chat through a relay](#relay).": "**Les discussions partagées disent où elles en sont, sur les deux téléphones** : les discussions qu’un contact a partagées depuis un relais où ton Erevos ne prend pas de lui-même affichent **Réception, 40%** dès que tu appuies dessus, et son téléphone dit que tu les récupères ; si elles ne sont pas arrivées, les deux téléphones le disent et le tien vibre deux fois. Voir [Discuter par un relais](#relay).",
  "**Calls connect again**: a call that rang no longer stays at **Connecting** on both phones; each phone now waits for its own addresses before it calls or answers. See [Chat through a relay](#relay).": "**Les appels se connectent à nouveau** : un appel qui a sonné ne reste plus sur **Connexion** sur les deux téléphones ; chaque téléphone attend désormais ses propres adresses avant d’appeler ou de répondre. Voir [Discuter par un relais](#relay).",
  "**A phone beside you brings your messages**: with no internet, an Erevos phone beside yours that has it, and carries for others, takes what waits for you on your relay and hands it over nearby, once you say yes to that phone. It learns your queue there, never what your messages say, and your phone moves to a new queue once it has internet again. Yours does the same for others while **Carry messages for others** is on, as it now is from the start. Never through Tor, and from another relay only once you say yes, warned it sees your address. See [Chat with a nearby phone](#nearby).": "**Un téléphone à côté apporte tes messages** : sans internet, un téléphone Erevos à côté du tien qui en a, et transporte pour les autres, prend ce qui t’attend sur ton relais et te le donne à proximité, une fois que tu dis oui à ce téléphone. Il apprend ta file d’attente, jamais ce que disent tes messages, et ton téléphone passe à une nouvelle file dès qu’il a de nouveau internet. Le tien fait de même pour les autres tant que **Transporter des messages pour d’autres** est activé, comme c’est maintenant le cas dès le départ. Jamais par Tor, et depuis un autre relais seulement une fois que tu dis oui, averti qu’il voit ton adresse. Voir [Chat with a nearby phone](#nearby).",
  "**A Matrix chat read elsewhere is read here too**: an encrypted Matrix chat you read, or answered, in Element or on another device of yours no longer keeps its count of new messages here. See [Matrix](#matrix).": "**Une discussion Matrix lue ailleurs est lue ici aussi** : une discussion Matrix chiffrée que tu as lue, ou à laquelle tu as répondu, dans Element ou sur un autre de tes appareils ne garde plus ici son nombre de nouveaux messages. Voir [Matrix](#matrix).",
  "**Matrix rooms with very long messages open**: a message with a very long run of names, dots or dashes, as some public Matrix rooms have, no longer closes Erevos+ as its chat shows it.":
    "**Les salons Matrix aux messages très longs s'ouvrent**: un message avec une très longue suite de noms, de points ou de tirets, comme en ont certains salons Matrix publics, ne ferme plus Erevos+ quand sa discussion l'affiche.",
  "**Messenger chats you read stay read**: a Messenger chat you marked read, or wrote in, no longer comes back as unread when Messenger sends it again, after Erevos+ reconnects or starts.":
    "**Les discussions Messenger lues restent lues**: une discussion Messenger que tu as marquée comme lue, ou dans laquelle tu as écrit, ne redevient plus non lue quand Messenger la renvoie, après qu'Erevos+ se reconnecte ou démarre.",
  "**Chats stay where you read**: in Telegram, Matrix, XMPP and Nostr chats, the chat no longer moves by itself to other messages as older ones load above it; it stays at the last message, or where you were reading.":
    "**Les discussions restent là où tu lis**: dans les discussions Telegram, Matrix, XMPP et Nostr, la discussion ne se déplace plus d'elle-même vers d'autres messages pendant que les plus anciens se chargent au-dessus; elle reste sur le dernier message, ou là où tu lisais.",
  "**Erevos+ says its own name, with an icon of its own**: the app and its guide now say Erevos+ everywhere, and its icon is Erevos's mark on a purple tile. Where it speaks of the plain Erevos, it still says Erevos.":
    "**Erevos+ dit son propre nom, avec une icône à lui**: l'app et son guide disent désormais Erevos+ partout, et son icône est la marque d'Erevos sur une tuile violette. Là où il parle de l'Erevos simple, il dit toujours Erevos.",
  "**Signal: one chat for each person, with their name**: in Erevos+, a Signal chat shows the person's name, what you send from the phone Erevos+ is linked to shows in the chat of the one you sent it to, and someone who first wrote to your phone number keeps one chat with you on their phone too.":
    "**Signal : une discussion par personne, avec son nom**: dans Erevos+, une discussion Signal montre le nom de la personne, ce que tu envoies depuis le téléphone auquel Erevos+ est lié s'affiche dans la discussion de la personne à qui tu l'as envoyé, et celui qui t'a écrit d'abord à ton numéro garde lui aussi une seule discussion avec toi sur son téléphone.",
  "**A message's menu always opens**: holding a message, in a chat or a group, opens its menu every time; before, after you had been in another app, it could stop opening until Erevos was closed and opened again.": "**Le menu d'un message s'ouvre toujours** : en maintenant un message appuyé, dans une discussion ou un groupe, son menu s'ouvre à chaque fois ; avant, après un passage dans une autre app, il pouvait ne plus s'ouvrir jusqu'à ce qu'Erevos soit fermé puis rouvert.",
  "**New chat, made anew**: your QR code is on New chat as soon as it opens, with **Scan theirs** and **Share** under it; the field at the top finds a contact by name, or adds someone whose link you paste; and **No Erevos yet?** makes an invite, showing again one no one took yet instead of making another. On a new phone with no relay, New chat starts with **Start with an invite**. The small QR code is new each time and good once: the first to scan it is a contact at once, and anyone after, or with the link you share, writes a message request first. See [Chat through a relay](#relay).": "**Nouvelle discussion, refaite** : ton code QR est sur Nouvelle discussion dès qu’elle s’ouvre, avec **Scanner le sien** et **Partager** dessous ; le champ du haut trouve un contact par son nom, ou ajoute quelqu’un dont tu colles le lien ; et **Pas encore Erevos ?** fait une invitation, en remontrant une que personne n’a encore prise au lieu d’en faire une autre. Sur un nouveau téléphone sans relais, Nouvelle discussion commence par **Commence par une invitation**. Le petit code QR est nouveau à chaque fois et vaut une fois : le premier qui le scanne est un contact aussitôt, et les suivants, ou qui a le lien que tu partages, écrivent d’abord une demande de message. Voir [Chat through a relay](#relay).",
  "What's new": 'Nouveautés',
  'What each version changed': 'Ce que chaque version a changé',
  'What each version of Erevos changed, the newest first.': 'Ce que chaque version d’Erevos a changé, la plus récente en premier.',
  'Not out yet': 'Pas encore sortie',
  'This version': 'Cette version',
  'For you': 'Pour toi',
  'Under the hood': 'Sous le capot',
  "**Chats you have read stay read, on every network**: in Erevos+, Messenger, Signal, Session, Telegram, Matrix, XMPP and Nostr chats you have read no longer notify you again of messages already read, after a restart, a reconnect or when a chat opens. Signal's reads go both ways with the phone it is linked to, and a Nostr chat you answer from another app is read here too.": "**Les discussions lues restent lues, sur chaque réseau** : dans Erevos+, les discussions Messenger, Signal, Session, Telegram, Matrix, XMPP et Nostr que tu as lues ne te notifient plus de messages déjà lus, après un redémarrage, une reconnexion ou à l’ouverture d’une discussion. Les lectures de Signal vont dans les deux sens avec le téléphone auquel il est lié, et une discussion Nostr à laquelle tu réponds depuis une autre appli est lue ici aussi.",
  "**The guide tells of Messenger, Signal and Session**: in Erevos+, the user guide has a section for each, on signing in, chats, groups, calls, notifications, Tor and signing out. See [Messenger](#messenger), [Signal](#signal) and [Session](#session).": "**Le guide parle de Messenger, Signal et Session** : dans Erevos+, le guide d’utilisation a une section pour chacun, sur la connexion, les discussions, les groupes, les appels, les notifications, Tor et la déconnexion. Voir [Messenger](#messenger), [Signal](#signal) et [Session](#session).",
  // Not out yet.
  "**New chat asks whether they have Erevos**: over your QR code on **New chat**, choose **Has Erevos already** or **New to Erevos**. The first is your QR code as before, and says that it works only when both phones have a relay; the second shows an invite, which brings in someone new, or someone whose phone has no relay. New chat remembers your choice. See [Chat through a relay](#relay).":
    "**Nouvelle discussion demande s’il a Erevos** : au-dessus de ton code QR dans **Nouvelle discussion**, choisis **A déjà Erevos** ou **Nouveau sur Erevos**. Le premier est ton code QR comme avant, et dit qu’il ne marche que si les deux téléphones ont un relais ; le second montre une invitation, qui fait entrer quelqu’un de nouveau, ou quelqu’un dont le téléphone n’a pas de relais. Nouvelle discussion retient ton choix. Voir [Discuter par un relais](#relay).",
  "**The keypad lists the contacts it finds, and shows its letters**: on the Phone's **Keypad**, the contacts what you type finds are listed in the room over the number, all of them, not one at a time; and each key shows its letters in the app's language, ΑΒΓ in Greek, ABC in the others. See [Phone](#phone).":
    "**Le clavier liste les contacts qu’il trouve, et montre ses lettres** : sur le **Clavier** du Téléphone, les contacts que trouve ce que tu tapes s’affichent en liste dans la place au-dessus du numéro, tous à la fois et non un par un ; et chaque touche montre ses lettres dans la langue de l’app, ΑΒΓ en grec, ABC dans les autres. Vois [Téléphone](#phone).",
  "**A phone beside you no longer slows Erevos**: with another Erevos phone near you on the same Wi-Fi, Erevos no longer links to it over Wi-Fi Aware too, which took your phone's Wi-Fi away for moments and slowed your messages and the relay, as if the other phone were far away; and a link to a phone nearby that stopped carrying anything is let go at once, not used on. See [Chat with a nearby phone](#nearby).":
    "**Un téléphone à côté de vous ne ralentit plus Erevos** : avec un autre téléphone Erevos près de vous sur le même Wi-Fi, Erevos ne s'y relie plus aussi par Wi-Fi Aware, ce qui privait par moments votre téléphone de son Wi-Fi et ralentissait vos messages et le relais, comme si l'autre téléphone était loin ; et un lien avec un téléphone à proximité qui ne transmet plus rien est abandonné aussitôt, au lieu d'être encore utilisé. Voir [Discuter avec un téléphone à proximité](#nearby).",
  "**Calls start sooner and sound steadier**: a call through the call relay no longer waits up to 5 seconds on each phone for every way to the relay, only for the first that works; while it goes on, Erevos looks for phones nearby less often, which took the phone's Wi-Fi away for moments and made gaps in the sound; and in a video call, their picture is no longer put aside when their sound came apart from it. See [Chat through a relay](#relay).":
    "**Les appels démarrent plus vite et sonnent plus stables**: un appel par le relais d’appels n’attend plus jusqu’à 5 secondes sur chaque téléphone chaque chemin vers le relais, seulement le premier qui marche ; pendant l’appel, Erevos cherche moins souvent les téléphones à proximité, ce qui retirait un instant le Wi-Fi au téléphone et coupait le son ; et dans un appel vidéo, leur image n’est plus mise de côté quand leur son est arrivé à part. Voir [Chat through a relay](#relay).",
  "**Contacts as you dial**: on the Phone's **Keypad**, a contact whose number holds the digits you type, or whose name starts with them on the keys' letters (2 for ABC and ΑΒΓ), shows over the keys: tap it to call. See [Phone](#phone).":
    "**Des contacts en composant**: sur le **Clavier** du Téléphone, un contact dont le numéro contient les chiffres tapés, ou dont le nom commence par eux sur les lettres des touches (2 pour ABC et ΑΒΓ), s’affiche au-dessus des touches : touche-le pour appeler. Voir [Téléphone](#phone).",
  "**Chats open at once**: a chat no longer waits, showing your contact as encrypted, for Erevos to finish what it was doing with the relay in the background; it is ready to use as it opens, and holding a message opens its menu, at most a moment later while Erevos says it is still reading what came. See [Chat through a relay](#relay).":
    "**Les discussions s'ouvrent aussitôt** : une discussion n'attend plus, en montrant votre contact comme chiffré, qu'Erevos finisse ce qu'il faisait avec le relais en arrière-plan ; elle est prête dès l'ouverture, et un appui long sur un message ouvre son menu, au plus un instant après, pendant qu'Erevos indique qu'il lit encore ce qui est arrivé. Voir [Discuter par un relais](#relay).",
  "**Pair with a code with no relay yet**: on a phone with no relay yet, **New chat** now has **Pair with a code** too, under your QR code, and opens straight on **Start with an invite** without first showing the screen of a phone with a relay. See [Chat through a relay](#relay).":
    "**Associer avec un code sans relais encore**: sur un téléphone sans relais, **Nouvelle discussion** a maintenant aussi **Associer avec un code**, sous ton code QR, et s'ouvre directement sur **Commence par une invitation** sans montrer d'abord l'écran d'un téléphone avec relais. Voir [Chat through a relay](#relay).",
  "**The Public tab says why it shows no Nostr post**: whether the list of people you follow was not found, or they were found but no relay sent their posts, or their posts came but could not be shown, and how each relay answered. Before, it said only that no public posts were found. See [Chats with other Nostr apps](#nostr-chats).":
    "**L’onglet Public dit pourquoi il ne montre aucune publication Nostr** : si la liste des personnes que tu suis n’a pas été trouvée, si elles ont été trouvées mais qu’aucun relais n’a envoyé leurs publications, ou si leurs publications sont venues sans pouvoir s’afficher, et comment chaque relais a répondu. Avant, il disait seulement qu’aucune publication publique n’avait été trouvée. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**A new computer links to the end**: a computer with no relay before linking now takes the phone's answer at once, so linking with the small code finishes by itself, and with the full code **They match** shows. Before, the phone waited for **They match** while the computer showed nothing more until Erevos started again. See [Linked devices](#devices).":
    "**Un nouvel ordinateur s’associe jusqu’au bout** : un ordinateur sans relay avant l’association prend désormais aussitôt la réponse du téléphone ; l’association avec le petit code se termine donc d’elle-même, et avec le code complet **Ils correspondent** s’affiche. Avant, le téléphone attendait **Ils correspondent** tandis que l’ordinateur n’affichait plus rien jusqu’au redémarrage d’Erevos. Voir [Appareils associés](#devices).",
  "**Sharing into Erevos reaches every service**: **Send to** now lists the chats of your Matrix, XMPP and Nostr accounts too, beside Erevos chats, groups and SMS conversations. A photo or file shared from another app no longer goes missing when Erevos locks as it opens: after the password, **Send to** shows it again, where before it said that nothing came to send. See [Chat through a relay](#relay).":
    "**Partager vers Erevos atteint chaque service** : **Envoyer à** liste maintenant aussi les discussions de tes comptes Matrix, XMPP et Nostr, à côté des discussions Erevos, des groupes et des conversations SMS. Une photo ou un fichier partagé depuis une autre app ne se perd plus quand Erevos se verrouille en s’ouvrant : après le mot de passe, **Envoyer à** le montre à nouveau, là où avant il disait que rien n’était arrivé à envoyer. Voir [Discuter par un relais](#relay).",
  "**Search, media, days and export in Matrix, XMPP, Nostr and SMS**: these chats now have **Search in this chat**, **Media, links and files**, **Go to a day** and **Export chat**, as Erevos chats do, over what your phone keeps of them; an SMS conversation has them under **⋮**. Nothing you search for leaves your phone. See [Getting started](#start).":
    "**Recherche, médias, jours et export sur Matrix, XMPP, Nostr et en SMS** : ces discussions ont maintenant **Rechercher dans cette discussion**, **Médias, liens et fichiers**, **Aller à un jour** et **Exporter la discussion**, comme les discussions Erevos, sur ce que ton téléphone en garde ; une conversation SMS les a sous **⋮**. Rien de ce que tu cherches ne quitte ton téléphone. Voir [Premiers pas](#start).",
  "**Styles, cards and video in Matrix, XMPP and Nostr**: these chats now show bold, italic and the other marks for how words look, with tappable links, and send a contact card, a video without where it was filmed, or a photo from the camera at the quality you choose. In groups, @ offers the members; Nostr chats send your location, and a message you forward is marked as forwarded on your phone. See [Matrix](#matrix).":
    "**Styles, cartes et vidéo sur Matrix, XMPP et Nostr** : ces discussions affichent maintenant le gras, l’italique et les autres marques de l’aspect des mots, avec des liens à toucher, et envoient une carte de contact, une vidéo sans l’endroit où elle a été filmée, ou une photo de l’appareil photo à la qualité que tu choisis. Dans les groupes, @ propose les membres ; les discussions Nostr envoient ta position, et un message que tu transfères est marqué comme transféré sur ton téléphone. Voir [Matrix](#matrix).",
  "**Starred messages in every chat**: star a message in Matrix, XMPP, Nostr and SMS too, and find it again under **Starred messages**; save a photo, video, voice message or file that came there to the Collection, and keep a sticker or photo that came as one of your stickers. See [Chat through a relay](#relay).":
    "**Messages avec étoile dans chaque discussion** : ajoute une étoile à un message sur Matrix, XMPP, Nostr et en SMS aussi, et retrouve-le dans **Messages avec étoile** ; enregistre dans la Collection une photo, une vidéo, un message vocal ou un fichier reçu là, et garde un sticker ou une photo reçus comme l’un de tes stickers. Voir [Discuter par un relais](#relay).",
  "**Pin and archive any chat**: hold any chat down on the home screen (an Erevos contact or group, Matrix, XMPP or Nostr) to **Pin to the top**, **Archive** or, on Android, mute it, as SMS conversations already could. Archived chats wait under **Archived** until a new message comes from them. Matrix favourites show pinned, and low-priority rooms come last. A Matrix row shows ✓✓✓ once everyone has read yours. Matrix rooms, XMPP contacts and group MMS can take a name of your own. See [Getting started](#start).":
    "**Épingler et archiver n’importe quelle discussion** : garde le doigt sur n’importe quelle discussion de l’écran d’accueil (un contact ou groupe Erevos, Matrix, XMPP ou Nostr) pour **Épingler en haut**, **Archiver** ou, sur Android, la mettre en sourdine, comme le pouvaient déjà les conversations SMS. Les discussions archivées attendent sous **Archivées** jusqu’à ce qu’un nouveau message en vienne. Les favoris Matrix s’affichent épinglés, et les salons de faible priorité viennent en dernier. Une ligne Matrix montre ✓✓✓ dès que tout le monde a lu le tien. Les salons Matrix, les contacts XMPP et les MMS de groupe peuvent prendre un nom à toi. Voir [Premiers pas](#start).",
  "**Drafts, Send later and Remind me on Matrix, XMPP and Nostr**: what you type in a chat and do not send stays as its draft, also after Erevos closes, and shows on the chat's row. Hold **Send** down to send a message later from this phone. A Matrix or XMPP message that did not go has **Send again** in its menu, and **Remind me** on a message of any of these chats, SMS too, puts it in Chat with myself with a reminder. See [Matrix](#matrix).":
    "**Brouillons, Envoyer plus tard et Me rappeler sur Matrix, XMPP et Nostr** : ce que tu tapes dans une discussion et n’envoies pas reste comme son brouillon, même après la fermeture d’Erevos, et s’affiche sur la ligne de la discussion. Garde le doigt sur **Envoyer** pour envoyer un message plus tard depuis ce téléphone. Un message Matrix ou XMPP qui n’est pas parti a **Renvoyer** dans son menu, et **Me rappeler** sur un message de ces discussions, et des SMS, le met dans Discussion avec moi-même avec un rappel. Voir [Matrix](#matrix).",
  "**A PIN and screenshots for Matrix, XMPP, Nostr and SMS chats**: lock a chat on Matrix, XMPP or Nostr, or an SMS conversation, with a PIN of its own and block its screenshots, as an Erevos chat; an SMS conversation can also have its own look, be muted, or have a sound of its own. See [Hidden chats](#hidden).":
    "**Un code PIN et les captures pour les discussions Matrix, XMPP, Nostr et SMS** : verrouille une discussion Matrix, XMPP ou Nostr, ou une conversation SMS, par un code PIN à elle et bloque ses captures d’écran, comme une discussion Erevos ; une conversation SMS peut aussi avoir sa propre apparence, être en sourdine ou avoir un son à elle. Voir [Discussions masquées](#hidden).",
  "**Chat rules on Matrix, XMPP, Nostr and SMS**: disappearing messages, a timer for the chat or **Disappear** for one message, each chat saying what the other side keeps; **Block** on Matrix and Nostr, with a list of whom you blocked on each service's screen; **Delete** asks **This phone** or **Everyone**; on XMPP, **Appear offline** to one contact; and **Check in person** by QR code on XMPP and Nostr. See [Matrix](#matrix).":
    "**Règles de discussion sur Matrix, XMPP, Nostr et SMS** : messages éphémères, avec un délai pour la discussion ou **Éphémère** pour un message, chaque discussion disant ce que l’autre côté garde ; **Bloquer** sur Matrix et Nostr, avec la liste de qui tu as bloqué sur l’écran de chaque service ; **Supprimer** demande **Ce téléphone** ou **Pour tout le monde** ; sur XMPP, **Apparaître hors ligne** pour un contact ; et **Vérifier en personne** par code QR sur XMPP et Nostr. Voir [Matrix](#matrix).",
  "**Choose where a call's sound goes**: with a Bluetooth or wired headset connected, **Speaker** in a call becomes **Audio output**, to choose the phone, the speaker or the headset, a Bluetooth one by its own name. A headset connected as a call starts, or during it, takes the sound, as in a phone call. On Android. See [Chat through a relay](#relay).":
    "**Choisis où va le son d’un appel** : avec un casque Bluetooth ou filaire connecté, **Haut-parleur** dans un appel devient **Sortie audio**, pour choisir le téléphone, le haut-parleur ou le casque, un casque Bluetooth sous son propre nom. Un casque connecté au début d’un appel, ou pendant, prend le son, comme pour un appel téléphonique. Sur Android. Voir [Discuter par un relais](#relay).",
  "**Nothing goes through Tor unless you turn it on**: on Android, **Automatically from your relay** under **Home relay** is now off in a new space, so a space no longer takes its relay's paired relay as a home relay through Tor by itself; turn it on there if you want it. Turning it off now also lets go of the home relay it took, so Tor does not run for it. See [Home relay](#home-relay).":
    "**Rien ne passe par Tor sauf si tu l’actives** : sur Android, **Automatiquement depuis ton relais** sous **Relais d’attache** est désormais éteint dans un nouvel espace, donc un espace ne prend plus de lui-même le relais apparié à son relais comme relais d’attache par Tor ; active-le là si tu le veux. L’éteindre lâche désormais aussi le relais d’attache qu’il a pris, pour que Tor ne tourne pas pour lui. Voir [Relais d’attache](#home-relay).",
  "**Your relays first, Nostr only after them**: a text to a contact who reads on Nostr now goes through your relay, then their home relays, then your home relay, and through the public Nostr relays only when none of them took it. Before, it went to the Nostr relays first and through your relay only when they were slow or did not take it. See [Through Nostr](#nostr).":
    "**Tes relais d’abord, Nostr seulement après** : un texte à un contact qui lit sur Nostr passe désormais par ton relais, puis par les relais d’attache de ton contact, puis par ton relais d’attache, et par les relais Nostr publics seulement quand aucun ne l’a pris. Avant, il allait d’abord aux relais Nostr, et passait par ton relais seulement s’ils étaient lents ou ne le prenaient pas. Voir [Par Nostr](#nostr).",
  "**One chat only through Tor**: on Android, **Through Tor** in an Erevos chat's **Details** sends that chat's messages and files only through Tor, on circuits of its own, whatever the space's Tor setting. It is off unless you turn it on, and calls do not go through Tor. See [Through Tor](#tor).":
    "**Une seule discussion par Tor** : sur Android, **Par Tor** dans les **Détails** d’une discussion Erevos envoie les messages et fichiers de cette discussion uniquement par Tor, sur des circuits à elle, quel que soit le réglage Tor de l’espace. C’est désactivé tant que tu ne l’actives pas, et les appels ne passent pas par Tor. Voir [Par Tor](#tor).",
  "**One chat only through Tor reaches Nostr too**: a chat with **Through Tor** on in its **Details** now sends and reads its Nostr texts only through Tor, and its photos and files on Nostr file servers too, even when the space's Tor is **Nothing**; Tor is started for it, and what goes waits for it. Until your contact first writes to the chat's own queue, their first messages come to the space's own queue, which is read the space's way. Before, with the space's Tor off, such a chat's texts could reach the public Nostr relays straight, and they saw the phone's internet address. See [Through Tor](#tor).":
    "**Une seule discussion par Tor atteint aussi Nostr** : une discussion avec **Par Tor** activé dans ses **Détails** envoie et lit maintenant ses textes Nostr uniquement par Tor, et ses photos et fichiers sur des serveurs de fichiers Nostr aussi, même quand le Tor de l’espace est sur **Rien** ; Tor est démarré pour elle, et ce qui part l’attend. Tant que ton contact n’a pas écrit une première fois dans la file propre à la discussion, ses premiers messages arrivent dans la file de l’espace, qui est lue comme l’espace le dit. Avant, avec le Tor de l’espace désactivé, les textes d’une telle discussion pouvaient atteindre directement les relais Nostr publics, qui voyaient l’adresse internet du téléphone. Voir [Par Tor](#tor).",
  "**Through Tor on your linked devices too**: a chat's **Through Tor** switch, set in its **Details**, now reaches your linked devices (your computer, the web app and Jolla) and back: switched on or off on any of them, it is switched everywhere. On a linked device that chat's messages, files and send-later messages then go only through Tor too, on the chat's own circuits, never straight; so do the copies that go to your contact's other devices. The web app has no Tor: there a chat with the switch on sends nothing while it is on, and the switch is shown so it can be turned off. A device on an older version never turns it off anywhere; it learns a change made elsewhere at that contact's next change. Before, it was only on the phone where you set it. See [Through Tor](#tor).":
    "**Par Tor aussi sur tes appareils associés** : le réglage **Par Tor** d’une discussion, mis dans ses **Détails**, arrive désormais sur tes appareils associés (ton ordinateur, l’application web et Jolla) et revient : activé ou désactivé sur l’un d’eux, il l’est partout. Sur un appareil associé, les messages, fichiers et messages à envoyer plus tard de cette discussion passent alors aussi uniquement par Tor, sur les circuits propres de la discussion, jamais en direct ; de même pour les copies qui vont aux autres appareils de ton contact. L’application web n’a pas Tor : là, une discussion dont le réglage est activé n’envoie rien tant qu’il l’est, et le réglage s’affiche pour qu’on puisse le désactiver. Un appareil sur une version plus ancienne ne le désactive nulle part ; il apprend un changement fait ailleurs au prochain changement de ce contact. Avant, il ne valait que sur le téléphone où tu l’avais mis. Voir [Par Tor](#tor).",
  "**Nostr has its own Tor switch**: the **Nostr** screen now has **Nostr through Tor**, **On** or **Off**, off unless you turn it on. **On**, Erevos reaches the Nostr relays and the Nostr file servers only through Tor, and starts Tor for it even when the space's Tor is **Nothing**; a text that goes there waits while Tor starts. It only adds Tor: with the space's Tor on, or for a chat set to **Through Tor**, Nostr goes through Tor whatever it says. Before, Nostr only followed the space's Tor setting, and the screen only said whether it was on. See [Through Nostr](#nostr).":
    "**Nostr a son propre réglage Tor** : l’écran **Nostr** a maintenant **Nostr par Tor**, **Activé** ou **Désactivé**, désactivé tant que tu ne l’actives pas. **Activé**, Erevos joint les relais Nostr et les serveurs de fichiers Nostr uniquement par Tor et démarre Tor pour cela, même quand le Tor de l’espace est sur **Rien** ; un texte qui part là-bas attend pendant le démarrage de Tor. Cela ajoute seulement Tor : avec le Tor de l’espace activé, ou pour une discussion réglée sur **Par Tor**, Nostr passe par Tor quoi qu’il dise. Avant, Nostr suivait seulement le réglage Tor de l’espace, et l’écran disait seulement s’il était activé. Voir [Par Nostr](#nostr).",
  "**Erevos warns before your internet address can be seen**: once before the first message, voice message or file in an Erevos chat that can go without Tor, with **Through Tor for this chat** to fix it or **Go on**; before the first message in an Erevos group that can go without Tor; before a call, as calls never go through Tor, unless the contact is nearby on the same network; before fetching a file from a server your contact chose; and in every **Open this link?** question, where the site sees the address. Each has a **Guide** button. Before, Erevos did not say it. See [Who sees your internet address](#ip).":
    "**Erevos prévient avant que ton adresse internet puisse être vue** : une fois avant le premier message, message vocal ou fichier dans une discussion Erevos qui peut partir sans Tor, avec **Par Tor pour cette discussion** pour y remédier ou **Continuer** ; avant le premier message dans un groupe Erevos qui peut partir sans Tor ; avant un appel, puisque les appels ne passent jamais par Tor, sauf si le contact est proche sur le même réseau ; avant de récupérer un fichier sur un serveur que ton contact a choisi ; et dans chaque question **Ouvrir ce lien ?**, où le site voit l’adresse. Chacun a un bouton **Guide**. Avant, Erevos ne le disait pas. Voir [Qui voit ton adresse internet](#ip).",
  "**A Tor switch of their own**: backups to a server, the Collection's server copy, radio and TV lists, link previews and updates each have a **Through Tor** switch in their own screen, off unless you turn it on. On, that goes only through Tor, whatever the space's Tor setting, and waits while Tor starts; nothing goes straight. Off, it goes as before. It only adds Tor. For updates, the switch makes the daily new-version notice and **Check for updates** ask the web app's server instead of GitHub; a new version is told, but it does not download through Tor: to install it, turn the switch off for a moment. Playing a radio station or a TV channel always goes straight. Before, backups, the Collection and radio and TV followed only the space's Tor setting, and link previews and updates never went through Tor. See [Who sees your internet address](#ip).":
    "**Chacun son interrupteur Tor** : les sauvegardes vers un serveur, la copie de la Collection sur un serveur, les listes radio et TV, les aperçus des liens et les mises à jour ont chacun un interrupteur **Par Tor** dans leur propre écran, désactivé tant que tu ne l’actives pas. Activé, cela passe uniquement par Tor, quel que soit le réglage Tor de l’espace, et attend pendant le démarrage de Tor ; rien ne part en direct. Désactivé, cela passe comme avant. Il ne fait qu’ajouter Tor. Pour les mises à jour, l’interrupteur fait demander au serveur de l’appli web, et non à GitHub, la notification quotidienne d’une nouvelle version et **Rechercher des mises à jour** ; une nouvelle version est signalée, mais ne se télécharge pas par Tor : pour l’installer, désactive-le un instant. Lire une station de radio ou une chaîne de TV passe toujours en direct. Avant, les sauvegardes, la Collection, la radio et la TV ne suivaient que le réglage Tor de l’espace, et les aperçus des liens et les mises à jour ne passaient jamais par Tor. Voir [Qui voit ton adresse internet](#ip).",
  "**Bare web addresses open too**: t.me/name, example.org/page and the like are now tappable in every chat, as in Telegram and Signal, and show whole before they open; e-mail addresses and file names are not. See [Chat through a relay](#relay).":
    "**Les adresses web nues s’ouvrent aussi** : t.me/name, example.org/page et les semblables sont désormais touchables dans toutes les discussions, comme dans Telegram et Signal, et s’affichent en entier avant de s’ouvrir ; les adresses e-mail et les noms de fichier non. Voir [Discuter par un relais](#relay).",
  "**Read marks no longer go missing**: when you read a message and put the phone away at once, the other person still learns that you read it, at Erevos's next look, also after Erevos was closed. Before, it could stay at ✓✓ for them for good.": "**Les marques de lecture ne se perdent plus** : quand vous lisez un message et posez aussitôt le téléphone, l’autre personne apprend quand même que vous l’avez lu, au prochain coup d’œil d’Erevos, même après la fermeture d’Erevos. Avant, il pouvait rester à ✓✓ pour elle pour toujours.",
  "**Backups are checked**: after each automatic backup Erevos reads it back from the folder, opens it with its password, makes sure every part it names is there, of its size, and reads two of them through. On a server it looks at the listing only. **Check now** under Backups also downloads the server’s newest backup and ten of its parts; a part missing or damaged shows in red. **Full check of the folder** compares every part there with its SHA-256, on the phone. See [Backups](#backup).":
    "**Les sauvegardes sont vérifiées** : après chaque sauvegarde automatique, Erevos la relit depuis le dossier, l’ouvre avec son mot de passe, s’assure que chaque partie qu’elle nomme est là, à sa taille, et en lit deux en entier. Sur un serveur, il ne regarde que la liste. **Vérifier maintenant**, dans Sauvegardes, télécharge en plus la dernière sauvegarde du serveur et dix de ses parties ; une partie manquante ou endommagée s’affiche en rouge. **Vérification complète du dossier** compare chaque partie qui s’y trouve avec son SHA-256, sur le téléphone. Voir [Sauvegardes](#backup).",
  "**A new first start**: the first screen now says what you do not give, no phone number, email, user name or account, and asks for a name for your contacts, if you want one. After the modules comes a short screen for each, with how to begin with it and what Android should allow for it, **Allow all, one by one** among it; then the password lock and backups, then what is ready and what is missing. **I already have Erevos on another phone** goes straight to restoring a backup. See [Modules](#modules).":
    "**Un nouveau premier démarrage** : le premier écran dit maintenant ce que tu ne donnes pas, ni numéro de téléphone, ni e-mail, ni nom d’utilisateur, ni compte, et demande un nom pour tes contacts, si tu en veux un. Après les modules vient un court écran pour chacun, avec la façon de commencer et ce qu’Android doit autoriser pour lui, dont **Tout autoriser, un par un** ; puis le verrouillage par mot de passe et les sauvegardes, puis ce qui est prêt et ce qui manque. **J’ai déjà Erevos sur un autre téléphone** va droit à la restauration d’une sauvegarde. Voir [Modules](#modules).",
  "**Leftovers**: photos and files that nothing names any more, as those of an import that stopped in its middle, can now be found and deleted, under Backups → **Leftovers**. Type the PIN of each of your hidden chats and the password of any other space, tap **Find leftovers**, and Erevos shows how much none of them names; **Delete them** deletes it once you say so. See [Backups](#backup).":
    "**Restes** : les photos et fichiers que plus rien ne nomme, comme ceux d’une importation interrompue, peuvent maintenant être trouvés et supprimés, sous Sauvegardes → **Restes**. Tape le PIN de chacune de tes discussions cachées et le mot de passe de tout autre espace, touche **Chercher les restes**, et Erevos montre combien aucun d’eux ne nomme ; **Les supprimer** le supprime dès que tu confirmes. Voir [Sauvegardes](#backup).",
  "**An import that stops leaves nothing behind**: when Erevos stops while it brings in the photos and files of a Telegram, WhatsApp or Viber export, as when Android closes it or the battery runs out, what it had written of them is deleted the next time it starts. Before, it stayed on the phone, and in every backup, for good. See [Imported chats](#import).":
    "**Une importation interrompue ne laisse rien derrière elle** : quand Erevos s’arrête pendant qu’il apporte les photos et fichiers d’un export Telegram, WhatsApp ou Viber, par exemple quand Android le ferme ou que la batterie est vide, ce qu’il en avait déjà écrit est effacé au démarrage suivant. Avant, cela restait sur le téléphone, et dans chaque sauvegarde, pour toujours. Voir [Discussions importées](#import).",
  // 7.0.0-rc.7
  "**What takes room**: Backups now have **What takes room**, which shows on Android how much room Erevos takes on the phone, by kind: the Collection with the chats' photos and files, voice messages, chat history, Tor, and what writes that did not end left over. Each automatic backup holds it all, so it tells why one is large. See [Backups](#backup).":
    "**Ce qui prend de la place** : les sauvegardes ont maintenant **Ce qui prend de la place**, qui montre sur Android la place qu’Erevos prend sur le téléphone, par type : la Collection avec les photos et fichiers des discussions, les messages vocaux, l’historique, Tor et les restes d’écritures inachevées. Chaque sauvegarde automatique contient tout cela, on voit ainsi pourquoi elle est grosse. Voir [Sauvegardes](#backup).",
  "**Backups to a server get there again**: a backup to your own server, such as a Nextcloud, no longer stops when the server misses one of its pieces for a moment, as when it closes for a few minutes at night. That piece goes again a little later and the backup carries on; before, it started over the next time, and a large backup could fail day after day. See [Backups](#backup).":
    '**Les sauvegardes vers un serveur arrivent de nouveau** : une sauvegarde vers ton propre serveur, comme un Nextcloud, ne s’arrête plus quand le serveur refuse un moment l’une de ses parties, comme quand il ferme quelques minutes la nuit. Cette partie repart un peu plus tard et la sauvegarde continue ; avant, elle recommençait la fois suivante, et une grosse sauvegarde pouvait échouer jour après jour. Voir [Sauvegardes](#backup).',
  // 7.0.0-rc.6
  "**Photos and files from the Collection, straight from a chat**: **+** in a chat now has **Collection**, which opens the Collection of that chat's place, its photos and its other files. Tap what to send, then **Send**, and it goes in the chat. Before, **Photo** opened only the phone's own gallery. See [Collection](#collection).":
    "**Photos et fichiers de la Collection, directement depuis une discussion** : **+** dans une discussion a maintenant **Collection**, qui ouvre la Collection du lieu de cette discussion, avec ses photos et ses autres fichiers. Touche ce que tu veux envoyer, puis **Envoyer**, et ça part dans la discussion. Avant, **Photo** n’ouvrait que la galerie du téléphone. Voir [Collection](#collection).",
  "**A chat opens at its last message again**: opened from the home screen or a notification, a chat could stop above its newest messages, often above the unread ones. Now it goes to its end at once, and once more as its messages come into view.":
    "**Une discussion s’ouvre de nouveau sur son dernier message** : ouverte depuis l’écran d’accueil ou une notification, une discussion pouvait s’arrêter au-dessus de ses messages les plus récents, souvent au-dessus des non lus. Désormais elle va aussitôt à sa fin, et encore une fois dès que ses messages s’affichent.",
  "**A new sign-in to a relay is no longer undone**: after you signed in to your relay again, a chat screen open from before could later write back the token from before, which the relay no longer lets in, and the relay then refused this phone. Now the new token is kept at once, and every chat screen open takes it. See [Chat through a relay](#relay).":
    "**Une nouvelle connexion au relais n’est plus annulée** : après une nouvelle connexion à votre relais, un écran de discussion ouvert depuis avant pouvait plus tard réécrire l’ancien jeton, que le relais n’accepte plus, et le relais refusait alors ce téléphone. Désormais le nouveau jeton est gardé aussitôt, et chaque écran de discussion ouvert le prend. Voir [Discuter par un relais](#relay).",
  // 7.0.0-rc.5
  "**A message sent offline is no longer lost when you leave the chat**: what you sent while your chats were still opening, as they do for a while with no connection, was lost if you left the chat before it went. Now it waits, marked **Waiting**, and goes by itself once the relay or their phone nearby can take it, a voice message too. See [Chat through a relay](#relay).":
    "**Un message envoyé sans connexion n’est plus perdu quand tu quittes la discussion** : ce que tu envoyais pendant que tes discussions s’ouvraient encore, comme elles le font un moment sans connexion, était perdu si tu quittais la discussion avant son départ. Maintenant il attend, marqué **En attente**, et part tout seul dès que le relais ou son téléphone proche peut le prendre, un message vocal aussi. Voir [Discuter par un relais](#relay).",
  // 7.0.0-rc.4
  "**No more freezing after a space opens**: while an automatic backup was made, the screen could stop answering for minutes. Now the backup's files are written, listed and deleted in their folder away from the screen, and its parts are checked natively, many times faster.":
    '**Plus de blocage quand un espace s’ouvre** : pendant qu’une sauvegarde automatique se faisait, l’écran pouvait ne plus répondre pendant des minutes. Désormais les fichiers de la sauvegarde sont écrits, listés et supprimés dans leur dossier, à l’écart de l’écran, et ses parties sont vérifiées nativement, bien des fois plus vite.',
  // 7.0.0-rc.3
  "**Your SMS on your computer**: the phone's SMS can now show on this space's linked devices too, a computer, a browser or a tablet, end-to-end encrypted: read them there and answer, and the phone sends the answer. The latest 50 conversations go, each with its latest 50 messages; photos stay on the phone. Off until you turn it on, on the phone, under Settings → Phone and SMS → SMS → **On my linked devices too**. See [SMS](#sms).":
    "**Tes SMS sur ton ordinateur** : les SMS du téléphone peuvent désormais s’afficher aussi sur les appareils associés de cet espace, un ordinateur, un navigateur ou une tablette, chiffrés de bout en bout : lis-les là-bas et réponds, et le téléphone envoie la réponse. Les 50 dernières conversations partent, chacune avec ses 50 derniers messages ; les photos restent sur le téléphone. Désactivé tant que tu ne l’actives pas, sur le téléphone, sous Réglages → Téléphone et SMS → SMS → **Aussi sur mes appareils associés**. Voir [SMS](#sms).",
  "**TV in the Collection**: the Collection's new **TV** tab plays TV channels from IPTV lists (.m3u), by their link or from a file, or from iptv-org's public list of free channels, by country or whole, in their groups, with a search, on Android, on a computer and in a browser. There is no programme guide, logos show only if you turn them on, and a channel's name and link, or a radio station's, can be sent to a chat. See [Collection](#collection).":
    "**La télé dans la Collection** : le nouvel onglet **TV** de la Collection lit des chaînes de télé depuis des listes IPTV (.m3u), par leur lien ou depuis un fichier, ou depuis la liste publique de chaînes gratuites d’iptv-org, par pays ou entière, dans leurs groupes, avec une recherche, sur Android, sur ordinateur et dans un navigateur. Il n’y a pas de guide des programmes, les logos ne s’affichent que si vous les activez, et le nom et le lien d’une chaîne, ou d’une station de radio, peuvent être envoyés à une discussion. Voir [Collection](#collection).",
  "**Radio that keeps playing**: when a station's server, or a proxy on the way, drops the stream, or the network goes for a moment, Erevos asks the station again by itself, a few seconds later, instead of stopping.":
    "**Une radio qui continue de jouer** : quand le serveur d’une station, ou un proxy sur le chemin, coupe le flux, ou que le réseau disparaît un instant, Erevos se reconnecte tout seul quelques secondes plus tard, au lieu de s’arrêter.",
  "**Radio playlists with many stations**: in the Collection's Radio, **Add a station** takes a playlist link (.m3u, .pls) that names many stations and adds each of them, and **Import a playlist file** adds the stations of a .m3u or .pls file from your device. Only stations with an https link are added, and Erevos says how many were left out.":
    "**Playlists radio à plusieurs stations** : dans la Radio de la Collection, **Ajouter une station** accepte un lien de playlist (.m3u, .pls) qui nomme plusieurs stations et les ajoute toutes, et **Importer un fichier de playlist** ajoute les stations d’un fichier .m3u ou .pls de ton appareil. Seules les stations avec un lien https sont ajoutées, et Erevos dit combien ont été laissées de côté.",
  "**Block screenshots in a chat**: in a chat's details, **Block screenshots** keeps screenshots and screen recordings of it out on both phones, on Android, and either of you can turn it off again. Erevos on an iPhone, on a computer, in a browser or on Sailfish cannot block them, and says so. See [Chat through a relay](#relay).":
    "**Bloquer les captures d’écran dans une discussion** : dans les détails d’une discussion, **Bloquer les captures d’écran** empêche captures et enregistrements d’écran de celle-ci sur les deux téléphones, sous Android, et l’un ou l’autre de vous peut le désactiver. Erevos sur un iPhone, sur un ordinateur, dans un navigateur ou sous Sailfish ne peut pas les bloquer, et le dit. Voir [Discuter par un relais](#relay).",
  "**Every chat in its own look**: groups, Chat with myself and chats on Matrix, XMPP and Nostr now have **Chat look** too, as a contact's chat had, for that chat only. See [Chat through a relay](#relay).":
    "**Chaque discussion avec son propre aspect** : les groupes, la Discussion avec moi-même et les discussions sur Matrix, XMPP et Nostr ont maintenant eux aussi **Apparence de la discussion**, comme la discussion d’un contact, pour cette discussion seulement. Voir [Discuter par un relais](#relay).",
  "**Letters and text size**: Settings → Appearance has **Letters** (the style's own, the phone's, serif or monospace) and the messages' **Text size**, for the whole app or, from **Chat look**, for one chat. See [Appearance](#appearance).":
    "**Police et taille du texte** : Réglages → Apparence a **Police** (celle du style, celle du téléphone, avec empattements ou à chasse fixe) et la **Taille du texte** des messages, pour toute l’app ou, depuis **Apparence de la discussion**, pour une discussion. Voir [Apparence](#appearance).",
  "**Muting hidden Matrix, XMPP and Nostr chats**: a hidden place's own Matrix, XMPP and Nostr chats can now be muted, as hidden chats are, and then say nothing at all. See [Hidden chats](#hidden).":
    "**Mettre en sourdine les discussions masquées Matrix, XMPP et Nostr** : les discussions des comptes Matrix, XMPP et Nostr propres à un lieu caché peuvent maintenant être mises en sourdine, comme les discussions masquées, et ne disent alors plus rien. Voir [Discussions masquées](#hidden).",
  "**Say when I open Erevos**: with **Last seen** on, opening Erevos now tells your contacts at once, without waiting for a message: only those you talked with in the last 30 days who show their own time too, each after a random wait of up to a minute, at most every 15 minutes. The relay can then tell when you open Erevos: turn it off under Settings → Privacy and security → Last seen, or in a chat's details. See [Chat through a relay](#relay).":
    "**Dire quand j’ouvre Erevos** : avec **Vu pour la dernière fois** activé, ouvrir Erevos le dit maintenant aussitôt à tes contacts, sans attendre un message : seulement ceux avec qui tu as parlé ces 30 derniers jours qui montrent aussi leur propre heure, chacun après une attente aléatoire d’au plus une minute, au plus toutes les 15 minutes. Le relais peut alors savoir quand tu ouvres Erevos : éteins-le dans Réglages → Confidentialité et sécurité → Vu pour la dernière fois, ou dans les détails d’une discussion. Voir [Discuter par un relais](#relay).",
  "**Moving to a new phone**: a new chapter of the guide takes you step by step from the old phone to the new one with one backup: what to get ready, what comes over, what to set again, and wiping the old one at the end. See [Moving to a new phone](#new-phone).":
    "**Passer à un nouveau téléphone** : un nouveau chapitre du guide te mène pas à pas de l’ancien téléphone au nouveau avec une seule sauvegarde : quoi préparer, ce qui passe, ce qu’il faut remettre et comment effacer l’ancien à la fin. Voir [Passer à un nouveau téléphone](#new-phone).",
  '**A lost phone**: if the phone a backup came from was lost or stolen and may still be on, **The old phone was lost** under Settings → Data and devices → Backups moves every space and its hidden chats to new relay queues, so that phone reads nothing more of yours there, and tells your contacts quietly. The contact links and QR codes you gave before work for 14 more days. See [Backups](#backup).':
    '**Un téléphone perdu** : si le téléphone d’où vient une sauvegarde a été perdu ou volé et peut encore être allumé, **L’ancien téléphone est perdu**, sous Réglages → Données et appareils → Sauvegardes, fait passer chaque espace et ses discussions masquées à de nouvelles files d’attente sur le relais, si bien que ce téléphone n’y lit plus rien de toi, et prévient tes contacts sans bruit. Les liens de contact et codes QR que tu as donnés avant marchent encore 14 jours. Voir [Sauvegardes](#backup).',
  '**Restored chats go on by themselves**: after a backup is restored, a chat that went on after the backup was made starts a new conversation with the contact by itself, so you no longer give each other your links again, but with a contact on an older Erevos. See [Backups](#backup).':
    '**Les discussions restaurées continuent d’elles-mêmes** : après la restauration d’une sauvegarde, une discussion qui a continué après la sauvegarde ouvre d’elle-même une nouvelle conversation avec le contact, donc vous n’avez plus à vous redonner vos liens, sauf avec un contact dont l’Erevos est plus ancien. Voir [Sauvegardes](#backup).',
  '**Backups every 6 hours, and lighter**: automatic backups can now come every 6 hours too, made while Erevos is open and as it goes to the background. Each one writes and sends only the photos, files and voice messages that are new, and names again those of the backups before it: keep the whole backup folder together. See [Backups](#backup).':
    '**Sauvegardes toutes les 6 heures, et plus légères** : les sauvegardes automatiques peuvent maintenant aussi se faire toutes les 6 heures, tant qu’Erevos est ouvert et quand il passe en arrière-plan. Chacune n’écrit et n’envoie que les photos, fichiers et messages vocaux qui sont nouveaux, et nomme de nouveau ceux des sauvegardes d’avant : garde tout le dossier des sauvegardes ensemble. Voir [Sauvegardes](#backup).',
  '**Linked devices after a restore**: the phone a backup was restored on can ask the computers and browsers the old phone had linked to link again: tap **Ask to link again** under Settings → Data and devices → Linked devices, then **Link again** on the device. It keeps its chats, with no code to scan. See [Backups](#backup).':
    '**Appareils associés après une restauration** : le téléphone où une sauvegarde a été restaurée peut demander aux ordinateurs et navigateurs que l’ancien téléphone avait associés de s’associer de nouveau : appuie sur **Demander une nouvelle association** sous Réglages → Données et appareils → Appareils associés, puis sur **Associer de nouveau** sur l’appareil. Il garde ses discussions, sans code à scanner. Voir [Sauvegardes](#backup).',
  "**The phone's calls in backups**: on Android, **Put the calls in backups** under Backups adds the call history and Android's blocked numbers to your backups, and restoring adds back those the phone lacks. Off until you turn it on. See [Backups](#backup).":
    '**Les appels du téléphone dans les sauvegardes** : sur Android, **Inclure les appels dans les sauvegardes**, sous Sauvegardes, ajoute à tes sauvegardes l’historique des appels et les numéros bloqués d’Android, et la restauration remet ceux qui manquent au téléphone. Désactivé jusqu’à ce que tu l’actives. Voir [Sauvegardes](#backup).',
  "**Groups after a restore**: a member restored from a backup asks the group's admin to put it in again, which works while the group moved on only a little.":
    '**Groupes après une restauration** : un membre restauré depuis une sauvegarde demande à l’admin du groupe de le remettre dedans, ce qui marche tant que le groupe n’a avancé que de peu.',
  "**The time of a message that waited**: a message that waited on the relay, as for a computer or for hidden chats that were closed, now shows when it was sent, not when it came. From an Erevos before this version it still shows when it came.":
    "**L’heure d’un message qui a attendu** : un message qui a attendu sur le relais, comme pour un ordinateur ou pour des discussions cachées fermées, montre maintenant quand il a été envoyé, et non quand il est arrivé. Venant d’un Erevos antérieur à cette version, il montre toujours quand il est arrivé.",
  // 7.0.0-rc.2
  "**Find radio stations by name**: Add a station in the Collection's Radio tab searches Radio Browser, a free directory, sent only the words you type when you press Search. See [Collection](#collection).":
    "**Trouver des stations par leur nom** : Ajouter une station dans l’onglet Radio de la Collection cherche dans Radio Browser, un annuaire libre, qui ne reçoit que les mots que vous tapez quand vous appuyez sur Rechercher. Voir [Collection](#collection).",
  "**Internet radio in the Collection**: a Radio tab with stations you add by their https link, kept encrypted with the Collection, played like the music, with the notice on the phone. The station sees your device's IP address. See [Collection](#collection).":
    "**La radio par internet dans la Collection** : un onglet Radio avec les stations que vous ajoutez par leur lien https, chiffrées avec la Collection, lues comme la musique, avec la notification sur le téléphone. La station voit l’adresse IP de votre appareil. Voir [Collection](#collection).",
  "**Music and videos of any size in the desktop app's Collection**: they play and seek at once, read a piece at a time from their encrypted pieces, never held whole in memory. See [Collection](#collection).":
    "**Musique et vidéos de toute taille dans la Collection de l’application de bureau** : elles se lisent et s’avancent tout de suite, lues morceau par morceau depuis leurs morceaux chiffrés, jamais entières en mémoire. Voir [Collection](#collection).",
  "**Playlists in the Collection's Music**: songs in the order you choose, kept encrypted with the Collection, played in order or shuffled. Make one at the top of Music, and add songs from their menu or by holding them down. See [Collection](#collection).":
    "**Des playlists dans la Musique de la Collection** : des chansons dans l’ordre que vous choisissez, chiffrées avec la Collection, lues dans l’ordre ou en aléatoire. Créez-en une en haut de Musique, et ajoutez des chansons depuis leur menu ou en les maintenant appuyées. Voir [Collection](#collection).",
  "**Subtitles for the Collection's videos**: an .srt or .vtt file in the same folder with the video's name (film.srt, or film.en.srt) shows as its subtitles, and a tap at the top turns them off or on. See [Collection](#collection).":
    "**Des sous-titres pour les vidéos de la Collection** : un fichier .srt ou .vtt dans le même dossier, au nom de la vidéo (film.srt, ou film.en.srt), s’affiche comme ses sous-titres, et une touche en haut les masque ou les affiche. Voir [Collection](#collection).",
  "**A player's screen for the Collection**: tap the bar of the music playing, or **Now playing**, for its cover, title, artist and album, a bar to move in it, previous and next, **Shuffle**, **Repeat** (all or one), the speed from 0.5× to 2×, and the list, to tap another. A video, or music of 10 minutes or more, starts where you left it. The notification shows the title and cover only with **Show the title in the notification** on. See [Collection](#collection).":
    "**Un écran de lecture pour la Collection** : touchez la barre de la musique en cours, ou **En cours de lecture**, pour sa pochette, son titre, son artiste et son album, une barre pour s’y déplacer, précédent et suivant, **Aléatoire**, **Répéter** (tout ou un), la vitesse de 0.5× à 2×, et la liste, pour en toucher une autre. Une vidéo, ou une musique de 10 minutes ou plus, reprend là où vous l’avez laissée. La notification montre le titre et la pochette seulement avec **Afficher le titre dans la notification** activé. Voir [Collection](#collection).",
  "**Photos, Videos, Music and Files**: the Collection has a tab for each, each with the folders that hold any of its files above it. See [Collection](#collection).":
    "**Photos, Vidéos, Musique et Fichiers** : la Collection a un onglet pour chacun, avec au-dessus les dossiers qui en contiennent. Voir [Collection](#collection).",
  "**Music of the Collection goes on with the screen off**: on Android, music could stop a while after the screen went off. Now the player is kept in the foreground for as long as the list plays. See [Collection](#collection).":
    "**La musique de la Collection continue écran éteint** : sur Android, la musique pouvait s’arrêter un moment après l’extinction de l’écran. Désormais le lecteur reste au premier plan tant que la liste joue. Voir [Collection](#collection).",
  "**More music and video formats in the Collection**: on Android MP3, AAC, M4A, FLAC, Ogg, Opus, WAV, AMR, MP4, MKV, WebM and 3GP play, also a file that came with no type, known by its name's ending, and seeking works in an MP3 with no table of its seconds. See [Collection](#collection).":
    "**Plus de formats de musique et de vidéo dans la Collection** : sur Android, MP3, AAC, M4A, FLAC, Ogg, Opus, WAV, AMR, MP4, MKV, WebM et 3GP se lisent, même un fichier arrivé sans type, reconnu à la fin de son nom, et l’avance à un point marche aussi dans un MP3 sans table de ses secondes. Voir [Collection](#collection).",
  "**New modules on after an update**: where the modules were chosen before the Collection came, as on a phone or computer updated from 6, the Collection stayed off. Now it is on there, as is any module that comes later, until you turn it off in Settings → General → Modules. See [Modules](#modules).":
    "**Nouveaux modules activés après une mise à jour** : là où les modules ont été choisis avant l’arrivée de la Collection, comme sur un téléphone ou un ordinateur mis à jour depuis la 6, la Collection restait désactivée. Elle y est activée maintenant, comme tout module qui arrive plus tard, jusqu’à ce que tu la désactives dans Réglages → Général → Modules. Voir [Modules](#modules).",
  "**A home relay by itself**: on Android, when your relay names a relay paired with it, a space with no home relay takes that one, only through Tor, with its token from a coupon: nothing to type. **Automatically from your relay**, under Settings → Relay and networks → Home relay, turns it off. See [Home relay](#home-relay).":
    "**Un relais d’attache de lui-même** : sur Android, quand ton relais nomme un relais apparié avec lui, un espace sans relais d’attache prend celui-là, seulement par Tor, avec son jeton venu d’un coupon : rien à taper. **Automatiquement depuis ton relais**, dans Réglages → Relais et réseaux → Relais d’attache, le désactive. Voir [Relais d’attache](#home-relay).",
  "**A chip for every part that is on**: above the chats, **SMS**, **Erevos**, **Matrix**, **XMPP** and **Nostr** each have their chip whenever they are on in Modules, also with no chat yet. Before, in a space with only SMS so far, choosing **All messages** after Erevos's icon opened its chats hid the chips, with no way back.":
    "**Une puce pour chaque partie activée** : au-dessus des discussions, **SMS**, **Erevos**, **Matrix**, **XMPP** et **Nostr** ont chacun leur puce dès qu’ils sont activés dans Modules, même sans discussion encore. Avant, dans un espace avec seulement des SMS pour l’instant, choisir **Tous** après que l’icône d’Erevos a ouvert ses discussions cachait les puces, sans moyen d’y revenir.",
  "**Invite at one tap**: on the home screen, **Invite** beside the relay's line shows an invite's QR code at once, with nothing to type: who it is for and your name for them can be typed below it, or never. See [Chat through a relay](#relay).":
    "**Inviter d’un seul geste**: sur l’écran d’accueil, **Inviter** à côté de la ligne du relais montre tout de suite le code QR d’une invitation, sans rien taper: pour qui elle est et ton nom pour cette personne peuvent se taper dessous, ou jamais. Voir [Discuter par un relais](#relay).",
  "**Sign in with LPHL without typing a code**: on Android, once you sign in on the page the browser opened, tap **Open Erevos** there, and Erevos finishes signing in by itself. The code to type is still on the page, in case nothing opens. It needs the relay updated. See [Chat through a relay](#relay).":
    "**Se connecter avec LPHL sans taper de code** : sur Android, une fois connecté sur la page que le navigateur a ouverte, touche **Ouvrir Erevos** là-bas, et Erevos termine la connexion tout seul. Le code à taper reste sur la page, au cas où rien ne s’ouvre. Il faut que le relais soit mis à jour. Voir [Discuter par un relais](#relay).",
  "**Invites and contact links by touch**: on an Android phone with NFC, while **Invite someone** or **My QR code** shows the small QR code, hold the back of their phone to the back of yours: their phone opens it by itself, in Erevos where it is installed. See [Chat through a relay](#relay).":
    "**Invitations et liens de contact par simple contact** : sur un téléphone Android avec NFC, pendant que **Inviter quelqu’un** ou **Mon code QR** montre le petit QR code, colle le dos de son téléphone au dos du tien : son téléphone l’ouvre tout seul, dans Erevos s’il est installé. Voir [Discuter par un relais](#relay).",
  "**Smaller invite QR codes**: the QR code of **Invite someone** now holds about eight times less, so simpler and older cameras read it too, and its link is short enough for an SMS. It opens Erevos's page for invites, which offers Erevos and then opens the invite in it. Where your relay lets this phone make no invite, the long one is still made. See [Chat through a relay](#relay).":
    "**Des QR codes d’invitation plus petits** : le QR code de **Inviter quelqu’un** contient maintenant environ huit fois moins, donc les appareils photo plus simples et plus anciens le lisent aussi, et son lien est assez court pour un SMS. Il ouvre la page d’invitations d’Erevos, qui propose Erevos puis y ouvre l’invitation. Là où ton relay ne laisse ce téléphone faire aucune invitation, la longue est toujours faite. Voir [Discuter par un relais](#relay).",
  "**A small contact QR code**: **Show my QR code** now shows your contact link in short, so any camera reads it, and **Share my contact link** sends a link any app lets you tap. Whoever scans it while it shows is your contact at once; later, they write a message request first. **Large QR code, for no internet** shows the whole one, for near with no internet. See [Chat through a relay](#relay).":
    "**Un petit code QR de contact** : **Afficher mon code QR** montre maintenant ton lien de contact en court, donc n’importe quel appareil photo le lit, et **Partager mon lien de contact** envoie un lien que toute application laisse toucher. Qui le scanne pendant qu’il s’affiche devient aussitôt ton contact ; plus tard, il écrit d’abord une demande de message. **Grand code QR, sans internet** montre le code entier, pour la proximité sans internet. Voir [Discuter par un relais](#relay).",
  "**Links open Erevos**: on Android, an invite or contact link tapped in any app opens Erevos, which asks before it takes it, once the web server and a new Erevos are both out. See [Chat through a relay](#relay).":
    "**Les liens ouvrent Erevos** : sur Android, un lien d’invitation ou de contact touché dans n’importe quelle application ouvre Erevos, qui demande avant de le prendre, dès que le serveur web et un nouvel Erevos sont sortis. Voir [Discuter par un relais](#relay).",
  "**Home relay**: the screen no longer says that whoever runs a home relay sees this phone's address when it is set to **Only through Tor**.":
    "**Relais d’attache** : l’écran ne dit plus que qui gère un relais d’attache voit l’adresse de ce téléphone quand il est réglé sur **Seulement par Tor**.",
  "**An invite that opened Erevos for the first time** opens once the first start's setup is done, however long it took; before, after five minutes on the setup screens it was lost.":
    "**Une invitation qui a ouvert Erevos pour la première fois** s’ouvre une fois la configuration du premier démarrage terminée, quel que soit le temps pris; avant, après cinq minutes sur les écrans de configuration, elle était perdue.",
  // 7.0.0-rc.1
  "**Linked devices on the same Wi-Fi**: the phone and a computer on the same Wi-Fi or hotspot give each other what changes straight there, with no internet too. See [Linked devices](#devices).":
    "**Appareils associés sur le même Wi-Fi** : le téléphone et un ordinateur sur le même Wi-Fi ou point d’accès se donnent ce qui change directement là, sans internet aussi. Voir [Appareils associés](#devices).",
  "**Your Matrix, XMPP and Nostr accounts on every linked device**: each device linked gets them by itself, with no choice to make, and they follow as they change on the phone: one you sign out of there, or replace with another, goes from the devices too. See [Linked devices](#devices).":
    "**Tes comptes Matrix, XMPP et Nostr sur chaque appareil associé** : chaque appareil associé les reçoit de lui-même, sans rien à choisir, et ils suivent les changements du téléphone : celui dont tu te déconnectes là-bas, ou que tu remplaces par un autre, part aussi des appareils. Voir [Appareils associés](#devices).",
  "**Same settings on your linked devices**: the language, the look and Last seen changed on the phone or a computer change on the others too. A photo behind the screens, passwords, PINs and what is about one device alone stay on each. A device can keep its own: **Same settings on every device** in Linked devices. See [Linked devices](#devices).":
    "**Mêmes réglages sur tes appareils associés** : la langue, l’apparence et Vu pour la dernière fois changés sur le téléphone ou un ordinateur changent aussi sur les autres. Une photo derrière les écrans, les mots de passe, les codes PIN et ce qui ne concerne qu’un appareil restent sur chacun. Un appareil peut garder les siens : **Mêmes réglages sur tous les appareils** dans Appareils associés. Voir [Appareils associés](#devices).",
  "**Last seen**: when a contact is not online, their chat says when they last had Erevos open, to the minute. It goes end-to-end encrypted, never to the relay. It is on, and both ways: turn it off in Settings → Privacy and security → Last seen, and no one sees yours, nor you theirs. Hidden chats have their own time and their own switch, in a chat's details there. See [Chat through a relay](#relay).":
    "**Vu pour la dernière fois** : quand un contact n’est pas en ligne, sa discussion indique quand il a eu Erevos ouvert pour la dernière fois, à la minute près. Elle part chiffrée de bout en bout, jamais vers le relais. C’est activé, et dans les deux sens : désactive-le dans Réglages → Confidentialité et sécurité → Vu pour la dernière fois, et personne ne voit la tienne, ni toi la leur. Les discussions masquées ont leur propre heure et leur propre interrupteur, dans les détails d’une discussion de là-bas. Voir [Discuter par un relais](#relay).",
  "**One Public feed**: the new **Public** chip on the home screen shows the public posts of the Nostr people you follow and the public Matrix rooms you are in as one feed, as in Amethyst, with photos inside the posts and a card for a link. Answer, share again, like, share and write new posts with photos; for Matrix, answer, react and share. **Photos** chooses whether photos come at once, only through Tor or on a tap. The **Nostr** chip shows only the Nostr chats again. See [Chats with other Nostr apps](#nostr-chats).":
    "**Un seul fil public** : le nouveau bouton **Public** de l’écran d’accueil montre dans un seul fil, comme dans Amethyst, les publications publiques des personnes Nostr que tu suis et les salons Matrix publics où tu es, avec les photos dans les publications et une carte pour un lien. Réponds, partage à nouveau, aime, partage et écris de nouvelles publications avec des photos ; pour Matrix, réponds, réagis et partage. **Photos** choisit si les photos viennent tout de suite, seulement par Tor ou sur appui. Le bouton **Nostr** n’affiche de nouveau que les discussions Nostr. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Collection**: an encrypted place in every space and hidden place for photos, files and folders, with its icon next to the lock. Turn it on in Modules. See [Collection](#collection).":
    "**Collection** : un endroit chiffré dans chaque espace et chaque lieu caché pour les photos, les fichiers et les dossiers, avec son icône à côté du cadenas. Active-la dans Modules. Voir [Collection](#collection).",
  "**Music, videos and PDFs in the Collection**: music and videos play from their encrypted pieces, music on with the screen off and with play, pause, next and previous on the lock screen, and PDFs read page by page inside Erevos. **Open with another app** leaves no plain copy, and a photo or video picked from the gallery can be deleted there after importing. See [Collection](#collection).":
    "**Musique, vidéos et PDF dans la Collection** : la musique et les vidéos se lisent depuis leurs morceaux chiffrés, la musique aussi écran éteint, avec lecture, pause, suivant et précédent sur l’écran de verrouillage, et les PDF se lisent page par page dans Erevos. **Ouvrir avec une autre application** ne laisse aucune copie non chiffrée, et une photo ou une vidéo de la galerie peut y être supprimée après l’importation. Voir [Collection](#collection).",
  "**The Collection on a computer**: in the desktop app for Linux, macOS and Windows the Collection keeps your photos and files encrypted too. Photos, PDFs, music and videos open in memory only, never as a plain copy on the disk, and close when the space locks. **Save to the computer** asks first. See [Collection](#collection).":
    "**La Collection sur l’ordinateur** : dans l’application de bureau pour Linux, macOS et Windows, la Collection garde aussi tes photos et fichiers chiffrés. Photos, PDF, musique et vidéos s’ouvrent seulement en mémoire, jamais en copie non chiffrée sur le disque, et se ferment quand l’espace se verrouille. **Enregistrer sur l’ordinateur** demande d’abord. Voir [Collection](#collection).",
  "**Files up to 4 GB in the Collection**: on Android a file picked from the phone's files is encrypted as it is read, with no plain copy first, so it comes in faster and needs no room twice. In the desktop app music and videos up to 1 GB play. See [Collection](#collection).":
    "**Des fichiers jusqu’à 4 Go dans la Collection** : sur Android, un fichier choisi dans les fichiers du téléphone est chiffré à mesure qu’il est lu, sans copie en clair avant, il entre donc plus vite et ne prend pas deux fois la place. Dans l’application de bureau, la musique et les vidéos jusqu’à 1 Go se lisent. Voir [Collection](#collection).",
  "**The Collection on a WebDAV server**: each space and hidden place can copy its Collection, still encrypted, to a folder on a server you choose, Nextcloud, ownCloud or any that speaks WebDAV, so big files are not only on the phone. Only what is new goes, and a phone that lacks a file fetches it from there. See [Collection](#collection).":
    "**La Collection sur un serveur WebDAV** : chaque espace et chaque lieu caché peut copier sa Collection, toujours chiffrée, dans un dossier sur un serveur de ton choix, Nextcloud, ownCloud ou tout serveur qui parle WebDAV, pour que les gros fichiers ne soient pas que sur le téléphone. Seul ce qui est nouveau part, et un téléphone à qui il manque un fichier va le chercher là-bas. Voir [Collection](#collection).",
  "**The Collection on your linked devices**: turn on **On my linked devices too** in a Collection's settings and that Collection goes to the space's or hidden place's linked devices, changes and deletions with it. Small pictures come at once, a file itself on the same Wi-Fi or when you open it, a piece at a time, going on where it stopped after the network drops. See [Collection](#collection).":
    "**La Collection sur tes appareils associés** : active **Aussi sur mes appareils associés** dans les réglages d’une Collection et cette Collection va sur les appareils associés de l’espace ou du lieu caché, changements et suppressions compris. Les miniatures arrivent tout de suite, le fichier lui-même sur le même Wi-Fi ou quand tu l’ouvres, morceau par morceau, en reprenant où il s’était arrêté si le réseau coupe. Voir [Collection](#collection).",
  "**Groups stay on the device you choose**: on the phone, under Linked devices → Groups stay on, move the groups to a linked computer. Their keys go there, never copied, so the groups work there with the phone off and new ones can be made there; members see nothing new. See [Linked devices](#devices).":
    "**Les groupes restent sur l’appareil de ton choix** : sur le téléphone, sous Appareils associés → Les groupes restent sur, déplace les groupes sur un ordinateur associé. Leurs clés vont là, jamais copiées, si bien que les groupes y fonctionnent téléphone éteint et qu’on peut y en créer de nouveaux ; les membres ne voient rien de nouveau. Voir [Appareils associés](#devices).",
  "**Add someone new on a linked device without the phone**: a computer adds someone whose contact link is from this version by itself, with the phone off, and writes to them at once; they see your account as a request, with the same safety number, and the phone adds them too once it is on. See [Linked devices](#devices).":
    "**Ajoute quelqu’un de nouveau sur un appareil associé sans le téléphone** : un ordinateur ajoute lui-même quelqu’un dont le lien de contact vient de cette version, téléphone éteint, et lui écrit aussitôt ; la personne voit ton compte comme une demande, avec le même numéro de sécurité, et le téléphone l’ajoute aussi une fois allumé. Voir [Appareils associés](#devices).",
  "**Calls and Send later on your linked devices without the phone**: with a contact on this version, a computer calls and is called by itself and sends a message for later itself, with the phone off, and a copy goes to each of their devices too, held till its time. Every device of yours shows what is scheduled, and deleting it on any of them takes it back everywhere. See [Linked devices](#devices).":
    "**Appels et envoi pour plus tard sur tes appareils associés sans le téléphone** : avec un contact sur cette version, un ordinateur appelle et reçoit les appels lui-même et envoie lui-même un message pour plus tard, téléphone éteint, et une copie va aussi à chacun de ses appareils, gardée jusqu’à son heure. Chacun de tes appareils montre ce qui est programmé, et le supprimer sur l’un d’eux l’annule partout. Voir [Appareils associés](#devices).",
  '**Support Erevos**: every way has its QR code now, Liberapay and PayPal too, and PayPal opens in the browser.':
    '**Soutenir Erevos** : chaque moyen a maintenant son code QR, Liberapay et PayPal aussi, et PayPal s’ouvre dans le navigateur.',
  '**Chats open at their end**: a long chat, or one with imported messages, could open at a message read long ago, often a photo, as it drew earlier messages on its way to the end. Now it opens at the newest message, and the arrow to where you left off is there when new ones came.':
    '**Les discussions s’ouvrent à leur fin** : une longue discussion, ou une avec des messages importés, pouvait s’ouvrir sur un message lu il y a longtemps, souvent une photo, car elle chargeait des messages plus anciens en route vers la fin. Maintenant elle s’ouvre sur le message le plus récent, et la flèche vers là où tu en étais est là quand il en est arrivé de nouveaux.',
  "**Tor off unless you turn it on**: a new space sends nothing through Tor, so messages go fastest, and turning Tor on asks first, as it makes them slower. A space you already have keeps its choice, under Settings → Relay and networks → Tor. Texts through Nostr now go without Tor too: then the Nostr relays see your phone's internet address, never who wrote to whom. See [Through Tor](#tor).":
    "**Tor désactivé tant que tu ne l’actives pas** : un nouvel espace n’envoie rien par Tor, donc les messages vont le plus vite, et activer Tor demande d’abord, car cela les ralentit. Un espace que tu as déjà garde son choix, dans Réglages → Relais et réseaux → Tor. Les textes par Nostr passent maintenant aussi sans Tor : alors les relais Nostr voient l’adresse internet de ton téléphone, jamais qui a écrit à qui. Voir [Par Tor](#tor).",
  "**Moving a chat to a space with no relay**: **Move to another space** stopped there, as that space had no relay of its own. Now it offers this space's relay, which that space then keeps, and it makes that space's relay queue when it has a relay but no queue yet. See [Second password](#second).":
    "**Déplacer une discussion vers un espace sans relais** : **Déplacer dans un autre espace** s’arrêtait là, car cet espace n’avait pas de relais à lui. Maintenant il propose le relais de cet espace-ci, que l’autre espace garde ensuite, et il crée la file de cet espace sur le relais quand il a un relais mais pas encore de file. Voir [Second mot de passe](#second).",
  "**Fixes from a review of all the code**: a message you were typing stays with its chat when you open another, and never shows in a PIN-locked chat's place; a locked chat under a locked group stays out of screenshots when the group closes; the Collection's catalogue goes into backups, so a restored phone opens its files; calls in a public group reach their members; a Matrix or XMPP account no longer stops for good at one bad message or an unreachable server; a message sent for later stays listed while its details are still coming; the computer app's Wi-Fi link refuses an impossible port; and the panic button lets the apps it tells start before it closes.":
    "**Corrections issues d'une revue de tout le code** : un message que vous écriviez reste avec sa conversation quand vous en ouvrez une autre, et n'apparaît jamais à la place d'une conversation à PIN ; une conversation verrouillée sous un groupe verrouillé reste hors des captures d'écran quand le groupe se ferme ; le catalogue de la Collection entre dans les sauvegardes, pour qu'un téléphone restauré ouvre ses fichiers ; les appels dans un groupe public atteignent ses membres ; un compte Matrix ou XMPP ne s'arrête plus pour de bon sur un message abîmé ou un serveur injoignable ; un message pour plus tard reste listé pendant que ses détails arrivent encore ; le lien Wi-Fi de l'application d'ordinateur refuse un port impossible ; et le bouton panique laisse démarrer les applications qu'il prévient avant de se fermer.",
  "**Safer in twelve more ways, from the review before 7**: a message the relay hands you is deleted there only once your phone has kept it, so a connection cut at that moment loses nothing (an older relay works as before); a relay keeps a bound on what it holds in all and for each phone; in a public group no one can have another member taken out by claiming to be them; with SMS invites off, no one becomes a contact from your number alone; searches that find nothing are forgotten after a quarter of an hour; a Matrix message is shown as its sender's only when the key came from their device, else as **Not verified**, and an XMPP or Matrix device that changes its key gets nothing until you accept it, while a new device is said in the chat; a photo or file from a server its sender chose is fetched by itself only through Tor, else on a tap; an old first packet replayed to you never takes over a chat; and your linked devices' log takes each device's changes only from that device, and forgets devices that are gone.":
    "**Plus sûr de douze façons de plus, issues de la revue avant 7** : un message que le relais vous remet n'y est effacé qu'une fois votre téléphone l'a gardé, si bien qu'une connexion coupée à cet instant ne perd rien (un ancien relais fonctionne comme avant) ; un relais garde une limite à ce qu'il conserve en tout et pour chaque téléphone ; dans un groupe public, personne ne peut faire exclure un autre membre en se faisant passer pour lui ; avec les invitations SMS désactivées, personne ne devient contact par votre seul numéro ; les recherches qui ne trouvent rien sont oubliées après un quart d'heure ; un message Matrix n'est montré comme celui de son expéditeur que si la clé est venue de son appareil, sinon comme **Non vérifié**, et un appareil XMPP ou Matrix qui change de clé ne reçoit rien tant que vous ne l'acceptez pas, tandis qu'un nouvel appareil est annoncé dans la conversation ; une photo ou un fichier venant d'un serveur choisi par l'expéditeur n'est récupéré de lui-même que par Tor, sinon d'un appui ; un ancien premier paquet rejoué ne prend jamais une conversation ; et le journal de vos appareils liés ne prend les changements de chaque appareil que de celui-ci, et oublie les appareils partis.",
  "**A home relay only through Tor**: switch a home relay to **Only through Tor** and it never sees your phone's address, whatever Tor is set to for the rest. With no token typed, it gives one for a coupon that your relay signs blind, so neither relay can tell whose it is, and two spaces can use each other's relays as home relays with nothing tying them together. The token comes within the hour, lasts 90 days, and Erevos renews it by itself. Needs Tor, on Android. See [Home relay](#home-relay).":
    '**Un relais d’attache seulement par Tor** : mets un relais d’attache sur **Seulement par Tor** et il ne voit jamais l’adresse de ton téléphone, quel que soit le réglage de Tor pour le reste. Sans jeton tapé, il en donne un contre un coupon que ton relais signe en aveugle, si bien qu’aucun des deux relais ne peut savoir à qui il est, et deux espaces peuvent utiliser les relais l’un de l’autre comme relais d’attache sans que rien ne les relie. Le jeton vient dans l’heure, dure 90 jours, et Erevos le renouvelle de lui-même. Demande Tor, sur Android. Voir [Relais d’attache](#home-relay).',
  // 6.0.0-rc.2
  "**Home's buttons stay at the bottom**: after the password, home's **Remind me** and **New chat** could float halfway up the screen, over the chats, with the list ending above them, until Erevos went away and came back. Now the screen asks Android at once whether a keyboard is open. See [Password lock](#lock).":
    "**Les boutons de l’écran d’accueil restent en bas** : après le mot de passe, **Me rappeler** et **Nouvelle discussion** pouvaient flotter à mi-hauteur, sur les discussions, la liste s’arrêtant au-dessus d’eux, jusqu’à ce qu’on quitte Erevos et qu’on y revienne. Maintenant, l’écran demande tout de suite à Android si un clavier est ouvert. Voir [Verrou par mot de passe](#lock).",
  "**The Nostr tab's posts come**: **Posts** could stay on **Looking…** for good through Tor. Each wait through Tor took one of the threads the whole app shares, and once all were taken, every look-up of the posts waited behind the others; a relay that answered and then could not be reached kept them waiting with no end. Now Tor's waits have threads of their own, a relay that cannot be reached is let be after 20 seconds, and the posts come within about two minutes at most, with what was found by then. See [Chats with other Nostr apps](#nostr-chats).":
    "**Les publications de l’onglet Nostr arrivent** : **Publications** pouvait rester pour toujours sur **Recherche…** via Tor. Chaque attente via Tor prenait l’un des fils que toute l’appli partage, et une fois tous pris, chaque recherche des publications attendait derrière les autres ; un relais qui avait répondu puis ne pouvait plus être joint les faisait attendre sans fin. Désormais, les attentes de Tor ont leurs propres fils, un relais qui ne peut pas être joint est laissé après 20 secondes, et les publications arrivent en deux minutes environ au plus, avec ce qui a été trouvé d’ici là. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Linux, Windows and macOS again**: 6.0.0-rc.1 came out without them: the check that each build for computers opens did not know the setup of Erevos's very first start. Now it does.":
    "**De nouveau Linux, Windows et macOS** : 6.0.0-rc.1 est sortie sans eux : la vérification que chaque version pour ordinateur s’ouvre ne connaissait pas la configuration du tout premier démarrage d’Erevos. Maintenant, elle la connaît.",
  // 6.0.0-rc.1
  "**Links open on Sailfish OS**: **Sign in with LPHL**, a donation page or a link in a chat opened nothing there. Now Sailfish OS opens them: a web page in the browser, a number in the phone or the messages, an address in the mail.":
    "**Les liens s'ouvrent sous Sailfish OS** : **Se connecter avec LPHL**, une page de don ou un lien dans une discussion n'ouvraient rien. Désormais Sailfish OS les ouvre : une page web dans le navigateur, un numéro dans le téléphone ou les messages, une adresse dans le courriel.",
  "**Matrix, and photos and files in XMPP and Nostr chats, on Sailfish OS**: Erevos there could not reach their servers over HTTPS, so Matrix could not sign in, photos and files neither came nor went, and links showed no preview. Now they work as on a computer.":
    "**Matrix, et les photos et fichiers des discussions XMPP et Nostr, sous Sailfish OS** : Erevos n'y joignait pas leurs serveurs en HTTPS, donc Matrix ne pouvait pas se connecter, les photos et fichiers n'arrivaient ni ne partaient, et les liens n'avaient pas d'aperçu. Désormais ils fonctionnent comme sur un ordinateur.",
  "**A phone call shows its screen**: with Erevos as the phone app, a call that came could ring with the phone's screen black, so it could not be answered, when Android's full-screen notifications for Erevos, Erevos's notices or its notices of incoming calls were off. Now the call screen comes up by itself, over the lock screen too, and turns the screen on. A call that Do Not Disturb holds back still comes quietly, with the screen off. See [Phone](#phone).":
    "**Un appel téléphonique affiche son écran** : avec Erevos comme app Téléphone, un appel entrant pouvait sonner écran noir, sans qu’on puisse répondre, quand les notifications plein écran d’Android pour Erevos, les notifications d’Erevos ou ses notifications d’appels entrants étaient désactivées. Désormais, l’écran d’appel s’affiche tout seul, même sur l’écran de verrouillage, et allume l’écran. Un appel que « Ne pas déranger » retient arrive toujours en silence, écran éteint. Voir [Téléphone](#phone).",
  "**The calculator shows a long result from its start**: upright, a result with many decimals hid its first digits, which showed only with the phone turned sideways. Now a long number gets smaller to fit, its first digits always in sight.":
    "**La calculatrice affiche un long résultat depuis le début** : en portrait, un résultat avec beaucoup de décimales cachait ses premiers chiffres, visibles seulement téléphone tourné. Désormais, un long nombre rapetisse pour tenir, ses premiers chiffres toujours visibles.",
  "**Pick the recipient of a new SMS from your contacts**: **New SMS** has a **Contacts** button that opens your contacts with a search, and typing a name or number suggests the contacts that match. A contact with several numbers shows a line for each, and for a group MMS each one you pick is added. With only the SMS open, only the phone's contacts show. See [SMS](#sms).":
    "**Choisir le destinataire d'un nouveau SMS parmi les contacts** : **Nouveau SMS** a un bouton **Contacts** qui ouvre tes contacts avec une recherche, et en tapant un nom ou un numéro, les contacts qui correspondent sont proposés. Un contact avec plusieurs numéros montre une ligne pour chacun, et pour un MMS de groupe chaque contact choisi s'ajoute. Avec seulement les SMS ouverts, seuls les contacts du téléphone s'affichent. Voir [SMS](#sms).",
  "**More for a number in the Phone**: on the keypad, **⋯** beside a typed number offers **Add to contacts**, **Add to an existing contact**, **Send an SMS** and **Copy the number**. **Recents** and **Favourites** offer **Copy the number** and **Open the contact**; **Favourites** also **Send an SMS**, and **Recents** adds an unknown number to an existing contact. With Erevos locked, the Phone still only calls. See [Phone](#phone).":
    "**Plus pour un numéro dans le Téléphone** : sur le clavier, **⋯** à côté d’un numéro tapé propose **Ajouter aux contacts**, **Ajouter à un contact existant**, **Envoyer un SMS** et **Copier le numéro**. **Récents** et **Favoris** proposent **Copier le numéro** et **Ouvrir le contact** ; **Favoris** aussi **Envoyer un SMS**, et **Récents** ajoute un numéro inconnu à un contact existant. Avec Erevos verrouillé, le Téléphone ne fait toujours qu’appeler. Voir [Téléphone](#phone).",
  "**A short buzz on touch**: the keys of the keypad, **Call**, **End**, Send, the keyboard's Enter, switches and menus that open give a short buzz. **Settings** → **Appearance** → **Vibrate on touch** turns it off. See [Appearance](#appearance).":
    "**Une brève vibration au toucher** : les touches du clavier, **Appeler**, **Raccrocher**, Envoyer, la touche Entrée du clavier, les interrupteurs et les menus qui s’ouvrent font vibrer brièvement. **Réglages** → **Apparence** → **Vibrer au toucher** l’éteint. Voir [Apparence](#appearance).",
  "**A number on each icon, on Huawei and Honor**: their launchers now show a number on each of Erevos's icons apart, with **Number on the icon** on: on Erevos's own the messages, on SMS's the SMS not read, on Phone's the missed calls, on Contacts's a birthday today. Most other launchers, such as those of Pixel and GrapheneOS, Samsung's and Kvaesitso, give a notice's dot or number to all of an app's icons alike, and Erevos cannot change that there. See [Appearance](#appearance).":
    "**Un nombre sur chaque icône, sur Huawei et Honor** : leurs lanceurs montrent maintenant un nombre sur chaque icône d’Erevos à part, avec **Nombre sur l’icône** activé : sur celle d’Erevos les messages, sur celle des SMS les SMS non lus, sur celle du Téléphone les appels manqués, sur celle des Contacts un anniversaire du jour. La plupart des autres lanceurs, comme ceux des Pixel et de GrapheneOS, celui de Samsung et Kvaesitso, donnent le point ou le nombre d’une notification à toutes les icônes d’une appli à l’identique, et là Erevos n’y peut rien changer. Voir [Apparence](#appearance).",
  "**Choose the parts of Erevos you use**: Erevos's own chats, the Phone, the SMS, and the chats with Nostr, Matrix and XMPP apps are modules now, any of them on, Erevos's own too, at least one. One that is off does not start and shows nowhere, and the Phone's and the SMS's icons leave the phone's apps: Erevos is lighter, opens faster and uses less battery. Nothing of it is deleted: it is all there again when it is back on. Erevos's very first start sets it up as an installer does, its language, the modules and what Android should allow for them; a module turned on later asks for its permissions again. After this update every module stays on until you change them in **Settings** → **General** → **Modules**. See [Modules](#modules).":
    "**Choisis les parties d’Erevos que tu utilises** : les discussions propres à Erevos, le Téléphone, les SMS et les discussions avec des apps Nostr, Matrix et XMPP sont désormais des modules, n’importe lesquels peuvent être activés, ceux d’Erevos aussi, au moins un. Un module désactivé ne démarre pas et n’apparaît nulle part, et les icônes du Téléphone et des SMS quittent les apps du téléphone : Erevos est plus léger, s’ouvre plus vite et consomme moins de batterie. Rien n’en est supprimé : tout est de retour quand il est réactivé. Le tout premier démarrage d’Erevos le configure comme le fait un installateur, sa langue, les modules et ce qu’Android doit autoriser pour eux ; un module activé plus tard redemande ses autorisations. Après cette mise à jour, chaque module reste activé jusqu’à ce que tu les changes dans **Réglages** → **Général** → **Modules**. Voir [Modules](#modules).",
  "**Public posts in the Nostr tab**: on the home screen, the Nostr tab shows first **Posts**, the public posts of the people your Nostr key follows and what they shared again, newest first, as in Amethyst or a Telegram channel, with **Chats** one tap away. Older ones come as you scroll to the end, the newest when you pull the list down; tap who wrote a post for their posts or to write to them. Read only, looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Publications publiques dans l’onglet Nostr** : sur l’écran d’accueil, l’onglet Nostr montre d’abord **Publications**, les publications publiques des personnes que suit ta clé Nostr et ce qu’elles ont repartagé, les plus récentes d’abord, comme dans Amethyst ou une chaîne Telegram, avec **Discussions** à un appui. Les plus anciennes arrivent quand tu fais défiler jusqu’au bout, les plus récentes quand tu tires la liste vers le bas ; touche qui a écrit une publication pour ses publications ou pour lui écrire. En lecture seule, cherché par Tor comme le dit l’espace et pas gardé, et aucune image ni aucun lien n’est ouvert. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Hidden chats on your linked devices**: each place of hidden chats now links on its own, from inside it, to the same place on a computer or in a browser, with **Linked devices** under its list. Its chats, messages, groups, calls, Chat with myself and its own Matrix, XMPP and Nostr accounts go there, and its contacts write to it there directly. Nothing of it shows in the space or on the space's linked devices. The link runs while the place is open, and while it is closed too with **Receive while closed** on. See [Linked devices](#devices).":
    "**Les discussions masquées sur tes appareils associés** : chaque emplacement de discussions masquées s’associe désormais à part, depuis l’intérieur, au même emplacement sur un ordinateur ou dans un navigateur, avec **Appareils associés** sous sa liste. Ses discussions, messages, groupes, appels, sa Discussion avec moi-même et ses propres comptes Matrix, XMPP et Nostr y vont, et ses contacts lui écrivent là directement. Rien de cela ne se voit dans l’espace ni sur les appareils associés de l’espace. L’association fonctionne tant que l’emplacement est ouvert, et fermé aussi avec **Recevoir une fois fermées** activé. Voir [Appareils associés](#devices).",
  "**Move a chat to another space**: in a chat's **Details**, **Move to another space** takes it, with its messages, name, picture, look and imported chats, into the space whose password you type, as a move into hidden chats does: the safety number stays the same, and their phone is told at once to write there. That space stays closed, and the row shows in every space. A chat never takes the place of one that space, or hidden chats, already have with the same person. See [Second password](#second).":
    "**Déplacer une discussion dans un autre espace** : dans les **Détails** d’une discussion, **Déplacer dans un autre espace** l’emmène, avec ses messages, son nom, son image, son apparence et les discussions importées, dans l’espace dont tu tapes le mot de passe, comme un déplacement dans les discussions masquées : le numéro de sécurité reste le même, et le téléphone du contact est aussitôt informé qu’il doit y écrire. Cet espace reste fermé, et la ligne s’affiche dans chaque espace. Une discussion ne prend jamais la place d’une autre que cet espace, ou des discussions masquées, ont déjà avec la même personne. Voir [Second mot de passe](#second).",
  // 4.0.0-rc.10
  "**Erevos no longer stops when only the SMS or the Contacts are open**: from them, a contact's chat, an SMS, another icon or a screen that asks for the password again could make Erevos say it could not open (Maximum call stack size exceeded). Now the password opens all of Erevos, then that screen. And when Erevos cannot open, **Try again** starts it again. See [Password lock](#lock).":
    "**Erevos ne s’arrête plus quand seuls les SMS ou les contacts sont ouverts** : de là, le chat d’un contact, un SMS, une autre icône ou un écran qui redemande le mot de passe pouvaient faire dire à Erevos qu’il n’a pas pu s’ouvrir (Maximum call stack size exceeded). Désormais le mot de passe ouvre tout Erevos, puis cet écran. Et quand Erevos ne peut pas s’ouvrir, **Réessayer** le relance. Voir [Verrou par mot de passe](#lock).",
  "**Each icon opens what it names**: after Erevos was opened by the SMS icon, or from the recent apps, another icon, the widget or a notice could sometimes show the SMS instead. Now each opens what it names. With only the SMS or the Contacts open, another icon asks for the password as when Erevos is locked, then opens its own part: the Contacts icon only the contacts, Erevos's own icon all of it. And Back on Erevos's first screen now puts it behind, as Home does, whatever opened it. See [Password lock](#lock).":
    "**Chaque icône ouvre ce qu’elle désigne** : après l’ouverture d’Erevos par l’icône SMS ou depuis les applis récentes, une autre icône, le widget ou une notification pouvaient parfois afficher les SMS à la place. Désormais chacun ouvre ce qu’il désigne. Quand seuls les SMS ou les contacts sont ouverts, une autre icône demande le mot de passe comme quand Erevos est verrouillé, puis ouvre sa propre partie : l’icône Contacts seulement les contacts, l’icône d’Erevos elle-même tout Erevos. Et Retour sur le premier écran d’Erevos le met désormais en arrière-plan, comme Accueil, quelle que soit la façon dont il a été ouvert. Voir [Verrou par mot de passe](#lock).",
  // 4.0.0-rc.9
  "**Only the Contacts**: with Erevos locked, the Contacts icon, the widget's Contacts button and the notice of a birthday ask for the password, then open only the contacts. A chat, an SMS, Settings, and the orange padlock **Unlock everything**, ask for it again, then open all of Erevos. See [Password lock](#lock).":
    "**Seulement les contacts** : quand Erevos est verrouillé, l’icône Contacts, le bouton Contacts du widget et la notification d’un anniversaire demandent le mot de passe, puis n’ouvrent que les contacts. Une discussion, un SMS, les Réglages et le cadenas orange **Tout déverrouiller** le redemandent, puis ouvrent tout Erevos. Voir [Verrou par mot de passe](#lock).",
  "**Old private messages in Nostr chats**: Erevos also reads private messages sent the older way (NIP-04), which Damus, Primal and many apps still send and keep, past and new, in the same chats. The relays see who wrote such a message to whom; Erevos itself still sends only the NIP-17 way. See [Chats with other Nostr apps](#nostr-chats).":
    "**Anciens messages privés dans les discussions Nostr** : Erevos lit aussi les messages privés envoyés à l’ancienne manière (NIP-04), que Damus, Primal et beaucoup d’applis envoient et gardent encore : passés et nouveaux, dans les mêmes discussions. Les relais voient qui a écrit un tel message à qui ; Erevos lui-même continue de n’envoyer qu’à la manière de NIP-17. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Public posts in Nostr chats**: in a chat with one person, **Public posts** shows what they post for everyone, newest first, read only. It is looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Publications publiques dans les discussions Nostr** : dans une discussion avec une personne, **Publications publiques** montre ce que la personne publie pour tous, les plus récentes d’abord, en lecture seule. C’est cherché par Tor comme le dit l’espace et rien n’en est gardé, et aucune image ni aucun lien n’est ouvert. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  // 4.0.0-rc.8
  // 4.0.0-rc.7
  "**Licence**: Settings → General → Licence says under which licence Erevos is free software, AGPL-3.0-or-later, its three additional terms, that it comes with no warranty, and who made it. See [Licence](#licence).":
    "**Licence** : Réglages → Général → Licence dit sous quelle licence Erevos est un logiciel libre, AGPL-3.0-or-later, ses trois conditions supplémentaires, qu’il vient sans aucune garantie, et qui l’a fait. Voir [Licence](#licence).",
  "**Contact**: Settings → General → Contact adds the maker of Erevos as a contact, to write to in Erevos itself, end-to-end encrypted, with no phone number and no email. See [What Erevos is](#about).":
    "**Contact** : Réglages → Général → Contact ajoute l’auteur d’Erevos comme contact, pour lui écrire dans Erevos même, avec chiffrement de bout en bout, sans numéro de téléphone ni e-mail. Voir [Ce qu’est Erevos](#about).",
  "**A new sticker set, Angry Eyes**: 24 faces of big yellow eyes on a black disc, drawn by the maintainer, each with the moves he gave it.":
    "**Une nouvelle série d’autocollants, Angry Eyes** : 24 visages de grands yeux jaunes sur un disque noir, dessinés par l’auteur d’Erevos, chacun avec les mouvements qu’il lui a donnés.",
  "**The calculator opens again**: in 4.0.0-rc.6 it closed as soon as it was tapped.":
    "**La calculatrice s’ouvre de nouveau** : dans la 4.0.0-rc.6, elle se fermait dès que tu la touchais.",
  "**People you follow on Nostr are looked for on more relays**: **Show the people you follow** also asks relays that gather follow lists and more of the relays your key writes on, and waits longer for them; when it finds no one, it says why and how each relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Les personnes que tu suis sur Nostr sont cherchées sur davantage de relais** : **Afficher les personnes que tu suis** interroge aussi des relais qui rassemblent des listes de personnes suivies et davantage des relais où écrit ta clé, et les attend plus longtemps ; quand il ne trouve personne, il dit pourquoi et comment chaque relais a répondu. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  // 4.0.0-rc.6
  "**Panic password**: with the password lock on, **Set the panic password** under the Panic button sets a password of its own that, typed on the lock screen, wipes Erevos as **Wipe everything now** does, while the screen shows **Wrong password**. Nothing shows whether one is set. See [Panic button](#panic).":
    "**Mot de passe de panique** : avec le verrou par mot de passe activé, **Définir le mot de passe de panique** dans « Bouton de panique » définit un mot de passe à part qui, saisi sur l’écran de verrouillage, efface Erevos comme **Tout effacer maintenant**, tandis que l’écran affiche **Mot de passe incorrect**. Rien ne montre s’il y en a un de défini. Voir [Bouton de panique](#panic).",
  "**Calculator in place of Erevos**: on Android, under Launcher icons, a calculator that works can take the place of Erevos's icon; your code, then **=**, opens Erevos, which asks for its password as always. See [Appearance](#appearance).":
    "**Calculatrice à la place d’Erevos** : sur Android, dans « Icônes du lanceur », une calculatrice qui fonctionne peut prendre la place de l’icône d’Erevos ; ton code, puis **=**, ouvre Erevos, qui demande son mot de passe comme toujours. Voir [Apparence](#appearance).",
  "**Chat with myself on your linked devices too**: notes, photos, files, voice messages and reminders written on one device go to the others, as do a reminder changed or seen and a note deleted. Those from before go once, both ways. See [Linked devices](#devices).":
    "**Discussion avec moi-même aussi sur tes appareils associés** : les notes, photos, fichiers, messages vocaux et rappels écrits sur un appareil vont aux autres, de même qu’un rappel changé ou vu et une note supprimée. Ceux d’avant partent une fois, dans les deux sens. Voir [Appareils associés](#devices).",
  "**Start when the phone turns on**: on Android, under In the background, Erevos can start by itself after the phone turns on, so the spaces set to say a message came while closed already say \"New message\", never which space or what. Off unless you choose it. See [Chat through a relay](#relay).":
    "**Démarrer à l’allumage du téléphone** : sur Android, dans « En arrière-plan », Erevos peut démarrer tout seul après l’allumage du téléphone, si bien que les espaces réglés pour dire qu’un message est arrivé pendant qu’ils sont fermés disent déjà « New message », jamais quel espace ni quoi. Désactivé sauf si tu le choisis. Voir [Discuter par un relais](#relay).",
  "**Moving the clock no longer ends the wait after wrong passwords**: it goes by the phone's own time since it started, which no one can set; after a restart it starts again from its beginning. See [Password lock](#lock).":
    "**Avancer l’horloge ne met plus fin à l’attente après des mots de passe incorrects** : elle suit le temps propre du téléphone depuis son démarrage, que personne ne peut régler ; après un redémarrage, elle repart de son début. Voir [Verrou par mot de passe](#lock).",
  "**People you follow on Nostr, found where your other app keeps them**: with a key brought from another Nostr app, **Show the people you follow** also looks on the relays your key writes on, and says so when no relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Les personnes que tu suis sur Nostr, trouvées là où ton autre appli les garde** : avec une clé venue d’une autre appli Nostr, **Afficher les personnes que tu suis** cherche aussi sur les relais où écrit ta clé, et le dit quand aucun relais n’a répondu. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Your Nostr name keeps the rest of your profile**: saving **Your name** changes only the name in your profile; a picture or words that another app of your key put there stay. Before, they could be wiped. See [Chats with other Nostr apps](#nostr-chats).":
    "**Ton nom Nostr garde le reste de ton profil** : enregistrer **Ton nom** ne change que le nom dans ton profil ; une photo ou des mots qu’une autre appli de ta clé y a mis restent. Avant, ils pouvaient être effacés. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Screens come down when no keyboard is open, in every case**: the home screen's list and buttons, or a chat, could still stay up as if a keyboard were open after it had gone. Now Erevos asks Android itself whether a keyboard is shown, and with none they come down within a second.":
    "**Les écrans redescendent quand aucun clavier n’est ouvert, dans tous les cas** : la liste et les boutons de l’écran d’accueil, ou une discussion, pouvaient encore rester en haut comme si un clavier était ouvert, après son départ. Maintenant Erevos demande à Android lui-même si un clavier est affiché, et sans clavier ils redescendent en moins d’une seconde.",
  // 4.0.0-rc.5
  "**New chat opens hidden chats sooner**: hold **New chat** down for a moment, not a whole second, and the field for a PIN of hidden chats opens; on Android the phone buzzes once as it opens. See [Hidden chats](#hidden).":
    "**Nouvelle discussion ouvre plus vite les discussions masquées** : maintiens **Nouvelle discussion** un instant, plus une seconde entière, et le champ pour un code PIN de discussions masquées s’ouvre ; sur Android le téléphone vibre une fois à l’ouverture. Voir [Discussions masquées](#hidden).",
  "**People you follow on Nostr**: under New chat in Nostr chats, **Show the people you follow** lists the people your Nostr key follows, with their names; tap one to write to them. See [Chats with other Nostr apps](#nostr-chats).":
    "**Les personnes que tu suis sur Nostr** : dans les Discussions Nostr, sous Nouvelle discussion, **Afficher les personnes que tu suis** liste les personnes que suit ta clé Nostr, avec leurs noms ; touches-en une pour lui écrire. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Who makes Erevos, and its licence**: About Erevos now names its maker, and every file of Erevos's source code says whose it is and under which licence; the AGPL-3.0 licence has three added terms (keep the maker's name, mark a changed version, give it another name). See [What Erevos is](#about).":
    "**Qui fait Erevos, et sa licence** : À propos d’Erevos dit désormais qui le fait, et chaque fichier du code source dit à qui il appartient et sous quelle licence ; la licence AGPL-3.0 a trois conditions ajoutées (garder le nom de l’auteur, marquer une version modifiée comme modifiée, lui donner un autre nom). Vois [Ce qu’est Erevos](#about).",
  // 4.0.0-rc.4
  "**Numbers on the home chips**: each chip above the chats (All messages, SMS, Erevos, Matrix, XMPP, Nostr) shows how many messages are not read in it, as a small number after its name; muted chats and groups are not counted. See [Getting started](#start).":
    "**Des nombres sur les puces de l’écran d’accueil** : chaque puce au-dessus des discussions (Tous, SMS, Erevos, Matrix, XMPP, Nostr) montre combien de messages n’y sont pas lus, en un petit nombre après son nom ; les discussions et groupes en sourdine ne comptent pas. Voir [Premiers pas](#start).",
  "**Open a photo full screen in Matrix, XMPP and Nostr chats**: tap a photo shown in a Matrix, XMPP or Nostr chat to see it on the whole screen, with zoom, turning with the phone and Save, as in a chat with a contact. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Photo en plein écran dans les discussions Matrix, XMPP et Nostr** : touche une photo affichée dans une discussion Matrix, XMPP ou Nostr pour la voir sur tout l’écran, avec le zoom, la rotation avec le téléphone et Enregistrer, comme dans la discussion avec un contact. Voir [Matrix](#matrix), [XMPP](#xmpp) et [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Who got and who read your messages in groups**: in a group that is not public, your messages show ✓, then ✓✓ once they reached the phone of every member, and ✓✓✓ once every one read them. Hold one and choose **Who read it** to see who read it and when, whose phone it reached and when, and who has neither yet. A member whose Erevos is older says nothing. A linked computer shows the same marks. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Qui a reçu et qui a lu tes messages dans les groupes** : dans un groupe qui n’est pas public, tes messages montrent ✓, puis ✓✓ quand ils sont arrivés sur le téléphone de chaque membre, et ✓✓✓ quand tous les ont lus. Maintiens-en un et choisis **Qui l’a lu** pour voir qui l’a lu et quand, sur le téléphone de qui il est arrivé et quand, et qui n’a encore fait ni l’un ni l’autre. Un membre dont l’Erevos est plus ancien ne dit rien. Un ordinateur associé montre les mêmes marques. Voir [Discuter par un relais](#relay) et [Discussions de groupe](#groups).",
  "**Who read your messages in Matrix**: your messages in a Matrix chat show ✓ once the Matrix server took them and ✓✓✓ once every other member read them, as their Matrix apps tell their servers; **Who read it**, on a message held down, lists who read it and when, and who has not. Matrix has no mark for a message that reached a phone, so there is no ✓✓. See [Matrix](#matrix).":
    "**Qui a lu tes messages dans Matrix** : tes messages dans une discussion Matrix montrent ✓ quand le serveur Matrix les a pris et ✓✓✓ quand tous les autres membres les ont lus, comme leurs applis Matrix le disent à leurs serveurs ; **Qui l’a lu**, sur un message maintenu, liste qui l’a lu et quand, et qui ne l’a pas lu. Matrix n’a pas de marque pour un message arrivé sur un téléphone, donc il n’y a pas de ✓✓. Voir [Matrix](#matrix).",
  "**Quiet group messages for the marks**: the group message that says a message came or was read goes only to the senders concerned, and batched; after 300 such messages to some members only, the next goes to all, so no member falls behind in the phone's MLS keys (they accept a jump of 1000 at most). Groups let go of as their space closes send nothing more. See [Group chats](#groups).":
    "**Des messages de groupe discrets pour les marques** : le message de groupe qui dit qu’un message est arrivé ou a été lu ne va qu’aux expéditeurs concernés, et groupé ; après 300 de ces messages envoyés à certains membres seulement, le suivant va à tous, pour qu’aucun membre ne prenne de retard dans les clés MLS du téléphone (elles acceptent un saut de 1000 au plus). Les groupes lâchés quand leur espace se ferme n’envoient plus rien. Voir [Discussions de groupe](#groups).",
  // 4.0.0-rc.3
  "**Bold, italic, code and hidden words**: in chats and groups, words typed between * become bold, between _ italic, between ~ struck through, between ` code, and between || hidden behind a grey bar until tapped. See [Chat through a relay](#relay).":
    "**Gras, italique, code et mots cachés** : dans les discussions et les groupes, les mots entre * passent en gras, entre _ en italique, entre ~ barrés, entre ` en code, et entre || cachés derrière une barre grise jusqu’à ce que vous touchiez. Voir [Discuter par un relais](#relay).",
  "**Hidden photo**: under + in a chat or a group, a photo that shows blurred until it is tapped. See [Chat through a relay](#relay).":
    "**Photo cachée** : sous + dans une discussion ou un groupe, une photo qui apparaît floue jusqu’à ce que vous la touchiez. Voir [Discuter par un relais](#relay).",
  "**Safety message**: under + in a chat, words to a contact that the relay sends by itself if you do not open Erevos for 6 hours to a week; each time you open it, they move on again. See [Chat through a relay](#relay).":
    "**Message de sécurité** : sous + dans une discussion, des mots pour un contact que le relais envoie tout seul si vous n’ouvrez pas Erevos pendant 6 heures à une semaine ; chaque fois que vous l’ouvrez, ils sont repoussés. Voir [Discuter par un relais](#relay).",
  "**Name a member in a group with @**: type @ and pick a member; they are told of the message even if they muted the group. See [Group chats](#groups).":
    "**Nommer un membre dans un groupe avec @** : tapez @ et choisissez un membre ; il est averti du message même s’il a mis le groupe en sourdine. Voir [Discussions de groupe](#groups).",
  "**Reply, change, react and delete in XMPP chats**: hold a message in an XMPP chat or group to answer it, change your words, delete it for everyone or react with an emoji, as Conversations, Dino, Gajim, Monal and Kaidan do; and **typing…** shows while the other person writes. See [XMPP](#xmpp).":
    "**Répondre, modifier, réagir et supprimer dans les discussions XMPP** : un appui long sur un message d’une discussion ou d’un groupe XMPP permet d’y répondre, de changer tes mots, de le supprimer pour tout le monde ou d’y réagir avec un emoji, comme le font Conversations, Dino, Gajim, Monal et Kaidan ; et **écrit…** s’affiche pendant que l’autre personne écrit. Voir [XMPP](#xmpp).",
  "**See who is writing in a Matrix chat**: **typing…** shows under a Matrix chat while someone writes in it, as the Matrix server says. It shows of you too only if you turn on **Say when I am writing** on the Matrix or XMPP screen: off at first, as it goes through the server not encrypted. See [Matrix](#matrix).":
    "**Vois qui écrit dans une discussion Matrix** : **écrit…** s’affiche sous une discussion Matrix pendant que quelqu’un y écrit, comme le dit le serveur Matrix. Les autres ne le voient de toi que si tu actives **Dire quand j’écris** sur l’écran Matrix ou XMPP : désactivé au départ, car cela passe par le serveur sans chiffrement. Voir [Matrix](#matrix).",
  "**Block someone on XMPP**: Block, at the bottom of an XMPP chat, keeps that person's messages, calls and requests from every app of your XMPP account; Unblock lets them through again. See [XMPP](#xmpp).":
    "**Bloquer quelqu’un sur XMPP** : Bloquer, en bas d’une discussion XMPP, écarte les messages, appels et demandes de cette personne de toutes les applis de ton compte XMPP ; Débloquer la laisse passer à nouveau. Voir [XMPP](#xmpp).",
  "**Voice messages in XMPP chats**: hold the microphone under an XMPP chat's message box to record, and let go to send; it goes encrypted as the chat is, as Conversations sends one. See [XMPP](#xmpp).":
    "**Messages vocaux dans les discussions XMPP** : appuie longuement sur le micro sous la zone de message d’une discussion XMPP pour enregistrer, et relâche pour envoyer ; il part chiffré comme la discussion, comme Conversations l’envoie. Voir [XMPP](#xmpp).",
  "**Matrix groups from Erevos**: New group, on the Matrix screen, makes an encrypted group with a name and the people you invite; Join a group joins one by its address; Invite, in a group, asks someone else in; typing @ in a group names a member, who is told of it. See [Matrix](#matrix).":
    "**Des groupes Matrix depuis Erevos** : Nouveau groupe, sur l’écran Matrix, crée un groupe chiffré avec un nom et les personnes que tu invites ; Rejoindre un groupe en rejoint un par son adresse ; Inviter, dans un groupe, y fait venir quelqu’un d’autre ; taper @ dans un groupe nomme un membre, qui est prévenu. Voir [Matrix](#matrix).",
  "**The panic button on a computer and on Sailfish OS**: Settings → Privacy and security → Panic button now wipes Erevos there too, with its automatic backups if you choose; on a computer it then starts again as new. See [Panic button](#panic).":
    "**Le bouton de panique sur un ordinateur et sur Sailfish OS** : Réglages → Confidentialité et sécurité → Bouton de panique efface désormais Erevos là aussi, avec ses sauvegardes automatiques si vous le choisissez ; sur un ordinateur, il redémarre ensuite comme neuf. Voir [Bouton de panique](#panic).",
  "**Every chat opens at its latest message**: chats with contacts, groups and SMS, and the Matrix, XMPP and Nostr chats, all open at the last message with the message bar under it, and have round arrows to the start, to where you left off (the first message that was new when you opened it) and to the end. See [Getting started](#start).":
    "**Chaque discussion s’ouvre sur son dernier message** : les discussions avec des contacts, les groupes et les SMS, et les discussions Matrix, XMPP et Nostr s’ouvrent toutes sur le dernier message avec la barre de message en dessous, et ont des flèches rondes vers le début, vers là où tu en étais (le premier message qui était nouveau à l’ouverture) et vers la fin. Voir [Premiers pas](#start).",
  "**The panic button says when it refused**: when your panic app asked to wipe Erevos while the switch was off, or signed with another key, the panic screen now says so, with the time. An app that moves to a new key the way Android allows stays trusted; otherwise you can trust it again as it is now. See [Panic button](#panic).":
    "**Le bouton de panique dit quand il a refusé** : quand votre app de panique a demandé d’effacer Erevos alors que l’interrupteur était coupé, ou signée d’une autre clé, l’écran du bouton de panique le dit désormais, avec l’heure. Une app qui passe à une nouvelle clé comme Android le permet reste de confiance ; sinon vous pouvez lui refaire confiance telle qu’elle est maintenant. Voir [Bouton de panique](#panic).",
  "**The home screen's chips stay on one line**: with a Nostr, Matrix or XMPP chip as well, **Names** went to a line of its own and the chips moved. Now they stay on one line that slides to the side, and the chosen one is always in sight.":
    "**Les puces de l’écran d’accueil restent sur une seule ligne** : avec en plus une puce Nostr, Matrix ou XMPP, **Noms** passait sur une ligne à part et les puces bougeaient. Maintenant elles restent sur une seule ligne qui glisse sur le côté, et celle que tu as choisie reste toujours en vue.",
  "**Screens come down when the keyboard is gone**: back from another app that had its keyboard open, the home screen's buttons (or a chat's field) could stay up where the keyboard had been, until a keyboard opened again. Now they come down within a second.":
    "**Les écrans redescendent quand le clavier est parti** : en revenant d’une autre appli dont le clavier était ouvert, les boutons de l’écran d’accueil (ou le champ d’une discussion) pouvaient rester en haut, là où était le clavier, jusqu’à ce qu’un clavier s'ouvre de nouveau. Maintenant ils redescendent en moins d’une seconde.",
  // 4.0.0-rc.2
  "**See what you type in a password or a PIN**: every field for a password, a PIN or a token has an eye at its end: tap it to see what you type, and again to hide it. It is hidden again the next time. See [Password lock](#lock).":
    "**Vois ce que tu tapes dans un mot de passe ou un PIN** : chaque champ pour un mot de passe, un PIN ou un jeton a un œil au bout : touche-le pour voir ce que tu tapes, et encore pour le masquer. La fois suivante, il est de nouveau masqué. Voir [Verrou par mot de passe](#lock).",
  "**A chat read as it opens stays read**: messages read while their chat was still opening, as Erevos ended a look at the relay, showed as unread on the home screen once you went back. Now they are marked read as soon as they show.":
    "**Une discussion lue pendant qu’elle s’ouvre reste lue** : les messages lus alors que leur discussion s’ouvrait encore, le temps qu’Erevos finisse de regarder sur le relais, apparaissaient comme non lus sur l’écran d’accueil dès que tu revenais. Maintenant, ils sont marqués comme lus dès qu’ils s’affichent.",
  "**Link for a website**: under New chat → Your contact link, a link to put on a web page, such as your contact page. It opens a page that offers Erevos to whoever has none yet, then adds you; what they send comes as a message request. See [Chat through a relay](#relay).":
    "**Lien pour un site web** : dans Nouvelle discussion → Ton lien de contact, un lien à mettre sur une page web, comme ta page de contact. Il ouvre une page qui propose Erevos à qui ne l’a pas encore, puis t’ajoute ; ce qu’on envoie arrive comme demande de message. Voir [Discuter par un relais](#relay).",
  "**An update's download that stalls is tried again**: when the connection brings nothing for a while, Erevos starts the download again by itself, three times in all, and then says so in its own words. See [Updates](#updates).":
    "**Un téléchargement de mise à jour qui se bloque est réessayé** : quand la connexion n’apporte plus rien pendant un moment, Erevos reprend le téléchargement de lui-même, trois fois en tout, puis le dit avec ses propres mots. Voir [Mises à jour](#updates).",
  // 4.0.0-rc.1
  "**Pieces of photos through Nostr stay with their chats**: while a photo that comes through Nostr waits for the rest of its pieces, they are now kept encrypted with the space or the hidden chats they came for, no longer apart where they could be counted, so nothing outside a hidden chats' password says that a photo is on its way to them. Pieces kept before go to the first chats whose photo they are, or after four days. See [Through Nostr](#nostr).":
    "**Les morceaux de photos par Nostr restent avec leurs discussions** : tant qu’une photo qui arrive par Nostr attend le reste de ses morceaux, ceux-ci sont désormais gardés chiffrés avec l’espace ou les discussions masquées pour lesquels ils sont venus, et non plus à part, où l’on pouvait les compter : rien hors du mot de passe de discussions masquées ne dit qu’une photo est en route vers elles. Les morceaux gardés avant vont aux premières discussions dont ils sont la photo, ou partent après quatre jours. Voir [Par Nostr](#nostr).",
  "**Encrypted SMS when nothing else works, if you choose**: on Android, when the relay, Nostr, the phones nearby and LoRa all fail, a text to an Erevos contact whose number is linked can go by SMS, end-to-end encrypted, hidden from their SMS app. Off until you turn it on, for all such contacts under Settings → Phone and SMS → SMS, or for one in a chat's Details. It costs SMS (3 for a short text, up to 10 for a longer one), and the phone company sees who wrote to whom, and when. Both phones need Erevos as the SMS app. See [SMS](#sms).":
    "**SMS chiffrés quand rien d’autre ne marche, si tu le choisis**: sur Android, quand le relais, Nostr, les téléphones à proximité et LoRa échouent tous, un texte à un contact Erevos dont le numéro est lié peut partir par SMS, chiffré de bout en bout et caché de son app SMS. Désactivé jusqu’à ce que tu l’actives, pour tous ces contacts dans Réglages → Téléphone et SMS → SMS, ou pour un seul dans les Détails d’une discussion. Ça coûte des SMS (3 pour un texte court, jusqu’à 10 pour un plus long), et l’opérateur voit qui a écrit à qui, et quand. Les deux téléphones ont besoin d’Erevos comme app SMS. Voir [SMS](#sms).",
  "**Answer a hidden call with Answer**: on the \"Incoming call\" screen with no name that a call to your hidden chats brings, **Answer** now asks for the PIN, as the small sign does, and the right PIN answers the call; before, it could not connect, and only the small sign could. See [Hidden chats](#hidden).":
    "**Répondre à un appel masqué avec Répondre** : sur l’écran « Appel entrant » sans nom qu’apporte un appel vers tes discussions masquées, **Répondre** demande maintenant le code PIN, comme le petit signe, et le bon code PIN répond à l’appel ; avant, il ne pouvait pas connecter, et seul le petit signe le pouvait. Voir [Discussions masquées](#hidden).",
  "**Spam SMS come quietly**: on Android, an SMS that the spam filter's own words catch, a link with words that try to fool from a number that is no contact and that you never answered, still goes to Spam but no longer shows a notice or makes a sound. Spam by your own words and rules still shows one, as they stay encrypted in the space; with the Spam filter off, every SMS does. See [SMS](#sms).":
    "**Les SMS de spam arrivent en silence** : sur Android, un SMS que les mots propres du filtre anti-spam attrapent, un lien avec des mots qui cherchent à tromper d’un numéro qui n’est pas un contact et auquel tu n’as jamais répondu, va toujours dans Spam mais n’affiche plus de notification ni ne sonne. Le spam par tes propres mots et règles en affiche toujours une, car ils restent chiffrés dans l’espace ; avec le Filtre anti-spam désactivé, chaque SMS en affiche une. Voir [SMS](#sms).",
  '**What\'s new in two parts**: each version says first what changes for you, then what changed under the hood: fixes, speed, battery and security inside. See [Updates](#updates).':
    '**Les nouveautés en deux parties** : chaque version dit d’abord ce qui change pour toi, puis ce qui a changé sous le capot : corrections, vitesse, batterie et sécurité à l’intérieur. Voir [Mises à jour](#updates).',
  '**A contact\'s SMS no longer stay counted as new**: opening their chat reads all of them, the earlier ones too, not only those that show.':
    '**Les SMS d’un contact ne restent plus comptés comme nouveaux** : ouvrir son chat les lit tous, les plus anciens aussi, pas seulement ceux qui s’affichent.',
  '**A message no longer waits when Tor cannot reach the relay**: with Tor for messages, it goes straight at once, as the Tor settings say. See [Through Tor](#tor).':
    '**Un message n’attend plus quand Tor n’atteint pas le relais** : avec Tor pour les messages, il part aussitôt en direct, comme le disent les réglages de Tor. Voir [Par Tor](#tor).',
  '**Background notices no longer stop after a network change**: when the connection of a wait at the relay died on the way (Wi-Fi to mobile data, the relay restarting), Erevos took the relay for one from before, which cannot wait, for the whole run: contacts\' messages then came up to ten minutes late, and hidden chats, closed spaces and hidden rings said nothing until Erevos was restarted. See [Chat through a relay](#relay).':
    '**Les avis en arrière-plan ne s’arrêtent plus après un changement de réseau** : quand la connexion d’une attente au relais mourait en route (du Wi-Fi aux données mobiles, redémarrage du relais), Erevos prenait le relais pour un ancien, qui ne sait pas attendre, pour toute la session : les messages des contacts arrivaient jusqu’à dix minutes en retard, et les discussions masquées, les espaces fermés et les sonneries masquées ne disaient rien jusqu’au redémarrage d’Erevos. Voir [Discuter par un relais](#relay).',
  '**A call hung up at once no longer rings**: when the hang-up came in the same look as the call, the phone rang 45 seconds for a call nobody was on; the same for a group call its starter left at once. See [Chat through a relay](#relay).':
    '**Un appel raccroché aussitôt ne sonne plus** : quand le raccrochage arrivait dans le même regard que l’appel, le téléphone sonnait 45 secondes pour un appel où personne n’était ; de même pour un appel de groupe que celui qui l’a lancé a quitté aussitôt. Voir [Discuter par un relais](#relay).',
  '**A hidden call rings once**: a place with Receive while closed and a ring queue rang twice for one call, and a call taken while hidden chats were open rang again as they closed. See [Hidden chats](#hidden).':
    '**Un appel masqué sonne une fois** : un lieu avec Recevoir une fois fermées et une file de sonnerie sonnait deux fois pour un appel, et un appel pris pendant que les discussions masquées étaient ouvertes sonnait de nouveau à leur fermeture. Voir [Discussions masquées](#hidden).',
  '**A member\'s contact link no longer says New message**: the answer to an ask from a group only adds the contact, with no notice. See [Group chats](#groups).':
    '**Le lien de contact d’un membre ne dit plus Nouveau message** : la réponse à une demande depuis un groupe ajoute seulement le contact, sans avis. Voir [Discussions de groupe](#groups).',
  '**The birthday notice and the phone\'s incoming call no longer replace each other**: they had the same notice number. See [Contacts](#contacts).':
    '**L’avis d’anniversaire et l’appel entrant du téléphone ne se remplacent plus** : ils avaient le même numéro d’avis. Voir [Contacts](#contacts).',
  '**A closed space tells of its contacts\' messages too**: since each contact writes to a queue of their own, a space that says a message came while another is open told only of group messages and first messages from new contacts. It now asks about its contacts\' queues too, up to 64. See [Chat through a relay](#relay).':
    '**Un espace fermé signale aussi les messages de ses contacts** : comme chaque contact écrit dans sa propre file d’attente, un espace qui signale qu’un message est arrivé pendant qu’un autre est ouvert ne signalait que les messages de groupes et les premiers messages de nouveaux contacts. Il interroge maintenant aussi les files d’attente de ses contacts, jusqu’à 64. Voir [Discuter par un relais](#relay).',
  '**The user guide is in every language of the app**: it shows in the one you chose, and names the buttons as the app shows them. See [Language](#start).':
    '**Le guide d’utilisation est dans toutes les langues de l’app** : il s’affiche dans celle que tu as choisie et nomme les boutons comme l’app les affiche. Voir [Langue](#start).',
  '**Location finds where you are, indoors too**: the phone looks by satellite and by its network at once, a sheet says it is looking, and when nothing is found it says why, with Try again. See [Chat through a relay](#relay).':
    '**Position trouve où tu es, à l’intérieur aussi** : le téléphone cherche par satellite et par son réseau à la fois, une feuille dit qu’il cherche, et si rien n’est trouvé elle dit pourquoi, avec Réessayer. Voir [Discuter par un relais](#relay).',
  '**The web app\'s icon counts what is not read**: on an iPhone, with notifications on for the space, Erevos\'s icon on the home screen shows how many messages are not read, never a hidden chat\'s, unless turned off under Settings → Notifications → Number on the icon. See [On an iPhone](#iphone).':
    '**L’icône de l’app web compte les non-lus** : sur un iPhone, avec les notifications activées pour l’espace, l’icône d’Erevos sur l’écran d’accueil montre combien de messages ne sont pas lus, jamais ceux d’une discussion masquée, sauf si tu l’enlèves dans Réglages → Notifications → Nombre sur l’icône. Voir [Sur un iPhone](#iphone).',
  "**Notifications for each chat**: on Android, mute a chat or a group for 8 hours, a week or always, and give its messages and its calls a sound of their own, or none. See [Chat through a relay](#relay).":
    "**Des notifications pour chaque discussion** : sur Android, mets une discussion ou un groupe en sourdine pendant 8 heures, une semaine ou toujours, et donne à ses messages et à ses appels un son à eux, ou aucun. Voir [Discuter par un relais](#relay).",
  "**A chat locked with its own PIN stays locked**: when its contact's Erevos started a new conversation, as it does about once a month, the chat lost its PIN, and a public group joined again lost its own. See [Hidden chats](#hidden).":
    "**Une discussion verrouillée par son propre code PIN reste verrouillée** : quand l’Erevos du contact commençait une nouvelle conversation, comme il le fait environ une fois par mois, la discussion perdait son code PIN, et un groupe public rejoint à nouveau perdait le sien. Voir [Discussions masquées](#hidden).",
  "**Erevos's icon keeps the number of messages not read, on Android**: leaving Erevos with messages not read, a notice without sound keeps how many until you read them, and the launcher shows it on the icon, as a number or a dot. Settings → Notifications → Number on the icon turns it off. See [Chat through a relay](#relay).":
    "**L’icône d’Erevos garde le nombre de messages non lus, sur Android** : quand tu quittes Erevos avec des messages non lus, une notification sans son garde combien jusqu’à ce que tu les lises, et le launcher l’affiche sur l’icône, comme nombre ou point. Réglages → Notifications → Nombre sur l’icône le désactive. Voir [Discuter par un relais](#relay).",
  "**The web app's notifications, more dependable**: no New message over Erevos while it is open, and a push held back while the phone was offline no longer counts messages you already read (both with your relay updated), every notice sounds in Chrome, Firefox and Edge, they come back by themselves when the browser changes its push address, and Notifications while closed says when the browser blocks them or your relay was not told yet that they are off. See [On an iPhone](#iphone).":
    '**Les notifications de l’app web, plus fiables** : plus de « Nouveau message » par-dessus Erevos quand il est ouvert, et un push retenu pendant que le téléphone était hors ligne ne compte plus les messages que tu as déjà lus (les deux avec ton relais à jour), chaque avis sonne dans Chrome, Firefox et Edge, elles reviennent d’elles-mêmes quand le navigateur change son adresse push, et « Notifications quand l’app est fermée » dit quand le navigateur les bloque ou que ton relais n’a pas encore été prévenu qu’elles sont désactivées. Voir [Sur un iPhone](#iphone).',
  "**Calls ring in the web app, on the computer and on Sailfish OS**: a call that comes while Erevos is open now rings, where only its screen showed, and vibrates where the phone can. On an iPhone it rings once you have touched Erevos, and not on silent. See [On an iPhone](#iphone).":
    "**Les appels sonnent dans l’app web, sur l’ordinateur et sur Sailfish OS** : un appel qui arrive pendant qu’Erevos est ouvert sonne désormais, là où seul son écran s’affichait, et vibre là où le téléphone le peut. Sur un iPhone, il sonne une fois que tu as touché Erevos, et pas en mode silencieux. Voir [Sur un iPhone](#iphone).",
  '**Erevos on a computer keeps running with its window closed**: in the system tray (on a Mac, in the Dock) it goes on receiving, a call rings and brings the window back, and a notification says how many messages are not read, never who or what. Turn it off under Settings → Notifications → In the background. See [On a computer](#desktop).':
    '**Erevos sur un ordinateur continue de tourner fenêtre fermée** : dans la zone de notification (sur un Mac, dans le Dock), il continue de recevoir, un appel sonne et fait revenir la fenêtre, et une notification dit combien de messages ne sont pas lus, jamais de qui ni quoi. À désactiver dans Réglages → Notifications → En arrière-plan. Voir [Sur un ordinateur](#desktop).',
  "**Erevos on Sailfish OS tells of messages and calls while it is closed**: while it is out of sight or closed, a small helper waits at the relay for the open space, a notification says how many messages came, never who or what, and a call rings with the phone's ringtone. See [On Sailfish OS](#sailfish).":
    "**Erevos sur Sailfish OS signale messages et appels pendant qu’il est fermé** : tant qu’il n’est pas à l’écran ou est fermé, un petit assistant attend sur le relais pour l’espace ouvert, une notification dit combien de messages sont arrivés, jamais de qui ni quoi, et un appel sonne avec la sonnerie du téléphone. Voir [Sur Sailfish OS](#sailfish).",
  "**The relay's pushes to the web app, sturdier**: a push the push service could not take just then is sent again, a call goes before the messages waiting their turn, and whoever runs the relay can allow another push service. Your relay needs an update for it.":
    '**Les push du relais vers l’app web, plus robustes** : un push que le service push n’a pas pu accepter à ce moment-là est renvoyé, un appel passe avant les messages qui attendent leur tour, et la personne qui gère le relais peut autoriser un autre service push. Ton relais doit être mis à jour pour cela.',
  "**Permissions checks every notice Erevos uses**: on Android, the message notice without sound or with a chat's own sound, and the reminders', turned off, now show there, with a button to each. See [Chat through a relay](#relay).":
    '**Autorisations vérifie chaque notification qu’Erevos utilise** : sur Android, la notification des messages sans son ou avec le son propre d’une discussion, et celle des rappels, quand elles sont désactivées, s’affichent maintenant là, avec un bouton pour chacune. Voir [Discuter par un relais](#relay).',
  '**Hidden chats say what their switches need**: Say when a message comes and Ring calls when closed say so when Settings → Notifications → In the background lets them do nothing. See [Hidden chats](#hidden).':
    '**Les discussions masquées disent ce dont leurs interrupteurs ont besoin** : Prévenir quand un message arrive et Faire sonner les appels quand elles sont fermées le disent quand Réglages → Notifications → En arrière-plan ne les laisse rien faire. Voir [Discussions masquées](#hidden).',
  "**Truer words about notices**: Settings and the guide give the notices' own words and say what each one needs. See [Chat through a relay](#relay).":
    '**Des mots plus justes sur les notifications** : les Réglages et le guide donnent les mots mêmes des notifications et disent ce dont chacune a besoin. Voir [Discuter par un relais](#relay).',
  "**Calls ring as they should**: with Do Not Disturb only when their notice may break through, with a phone's clock off too once the relay is updated, and to the end on Android 7 and 8; a second call is told busy, and a ring stops only for its own call. See [Chat through a relay](#relay).":
    '**Les appels sonnent comme il faut** : avec Ne pas déranger seulement quand leur notification a le droit de passer, avec l’horloge d’un téléphone décalée aussi une fois le relais mis à jour, et jusqu’au bout sur Android 7 et 8 ; un second appel reçoit la réponse occupé, et une sonnerie ne s’arrête que pour son propre appel. Voir [Discuter par un relais](#relay).',
  '**Hidden calls**: one turned down no longer leaves Erevos over the lock screen, one that comes while the password screen shows comes over it, and none rings twice. See [Hidden chats](#hidden).':
    '**Appels masqués** : un appel refusé ne laisse plus Erevos par-dessus l’écran de verrouillage, un appel qui arrive pendant que l’écran du mot de passe s’affiche passe par-dessus, et aucun ne sonne deux fois. Voir [Discussions masquées](#hidden).',
  '**Notices come again at once after a change of network**, and receiving starts again as Erevos shows when Android refused it. See [Chat through a relay](#relay).':
    '**Les notifications reviennent aussitôt après un changement de réseau**, et la réception reprend dès qu’Erevos s’affiche quand Android l’avait refusée. Voir [Discuter par un relais](#relay).',
  "**Hidden chats' notices tell each message once**: what came since a place last looked is told as it closes, a call that rang is not told again as a message, and a place whose queue the relay lost keeps its switch on. See [Hidden chats](#hidden).":
    '**Les notifications des discussions masquées signalent chaque message une fois** : ce qui est arrivé depuis le dernier regard d’un emplacement est signalé à sa fermeture, un appel qui a sonné n’est plus signalé de nouveau comme message, et un emplacement dont le relais a perdu la file garde son interrupteur activé. Voir [Discussions masquées](#hidden).',
  '**Hidden chats close while Erevos is away**, after 30 seconds, so a call to them meanwhile rings with their PIN to answer. See [Hidden chats](#hidden).':
    '**Les discussions masquées se ferment quand Erevos n’est plus affiché**, au bout de 30 secondes, si bien qu’un appel pour elles entre-temps sonne avec leur code PIN pour répondre. Voir [Discussions masquées](#hidden).',
  '**A voice message counts once**, on its last part, also when it goes again whole.':
    '**Un message vocal compte une fois**, sur sa dernière partie, même quand il est renvoyé en entier.',
  '**The number on the icon counts only what is still there**: a message deleted for everyone, or read on a linked computer, no longer counts. See [Chat through a relay](#relay).':
    '**Le nombre sur l’icône ne compte que ce qui est encore là** : un message supprimé pour tous, ou lu sur un ordinateur associé, ne compte plus. Voir [Discuter par un relais](#relay).',
  '**Messages sent for later** tell of themselves only while their space is open, without sound if sent so.':
    '**Les messages envoyés pour plus tard** ne se signalent que tant que leur espace est ouvert, sans son s’ils ont été envoyés ainsi.',
  '**SMS**: one to the chat on screen only sounds there, they are marked read only while their screen shows, and Android names their notices SMS. See [SMS](#sms).':
    '**SMS** : un SMS pour la discussion à l’écran ne sonne que là, ils ne sont marqués lus que tant que leur écran s’affiche, et Android nomme leurs notifications SMS. Voir [SMS](#sms).',
  "**Reminders**: one seen in Chat with myself goes from the notice, a hidden place's go with a new PIN, and birthdays come at 9:00. See [Getting started](#start).":
    '**Rappels** : un rappel vu dans Discussion avec moi-même quitte la notification, ceux d’un emplacement masqué partent avec un nouveau code PIN, et les anniversaires arrivent à 9:00. Voir [Premiers pas](#start).',
  '**Nostr reads as soon as Tor is ready.** See [Through Nostr](#nostr).':
    '**Nostr lit dès que Tor est prêt.** Voir [Par Nostr](#nostr).',
  "**Erevos's notices show its mark** in the status bar.":
    '**Les notifications d’Erevos montrent son logo** dans la barre d’état.',
  '**Notices are asked for with receiving off too**, when Say a message came is on.':
    '**Les notifications sont demandées même avec la réception désactivée**, quand Signaler les nouveaux messages est activé.',
  "**Photos open on the whole screen**: tap one to see it edge to edge, zoom in with two fingers or a double tap, and tap again to hide or show what is around it; big photos open as small ones do. Erevos also turns with the phone while the phone's Auto-rotate is on, and a photo shown on its own even when it is off. See [Chat through a relay](#relay).":
    '**Les photos s’ouvrent sur tout l’écran** : appuie sur une photo pour la voir bord à bord, zoome avec deux doigts ou un double appui, et appuie de nouveau pour cacher ou montrer ce qu’il y a autour ; les grandes photos s’ouvrent comme les petites. Erevos tourne aussi avec le téléphone tant que sa Rotation automatique est activée, et une photo montrée seule même quand elle est désactivée. Voir [Discuter par un relais](#relay).',
  "**Matrix accounts in Erevos**: sign a space in to Matrix and chat with people who use Element or another Matrix app, end-to-end encrypted, under Settings → Relay and networks → Matrix. These chats are not anonymous, and say so: the Matrix server sees who talks with whom. Text, photos and files. See [Matrix](#matrix).":
    "**Comptes Matrix dans Erevos** : connecte un espace à Matrix et discute avec des personnes qui utilisent Element ou une autre app Matrix, chiffré de bout en bout, dans Réglages → Relais et réseaux → Matrix. Ces discussions ne sont pas anonymes, et le disent : le serveur Matrix voit qui parle avec qui. Texte, photos et fichiers. Voir [Matrix](#matrix).",
  "**Every network's chats on the home screen**: once you sign in to Matrix, its chats are in the list with the Erevos chats and the SMS, newest first, each marked Matrix, and the Matrix chip shows them alone, as SMS and Erevos do. See [Matrix](#matrix).":
    "**Les discussions de tous les réseaux sur l’écran d’accueil** : une fois que tu t’es connecté à Matrix, ses discussions sont dans la liste avec les discussions Erevos et les SMS, les plus récentes d’abord, chacune marquée Matrix, et la puce Matrix ne montre qu’elles, comme SMS et Erevos. Voir [Matrix](#matrix).",
  '**Test versions before a release**: Erevos reads a version such as 4.0.0-rc.1, a test version that comes before 4.0.0, when it looks for updates, tells of a new version and shows what is new. See [Updates](#updates).':
    '**Des versions de test avant une version** : Erevos lit une version comme 4.0.0-rc.1, une version de test qui vient avant la 4.0.0, quand il cherche des mises à jour, annonce une nouvelle version et montre les nouveautés. Voir [Mises à jour](#updates).',
  "**Check Matrix devices by emoji**: in a chat with one person on Matrix, Check by emoji shows you both seven pictures; if they match, nobody sits in between, and Element sees the check too. Check this device with another of yours makes your own Element trust Erevos. See [Matrix](#matrix).":
    "**Vérifier les appareils Matrix par emoji** : dans une discussion avec une personne sur Matrix, Vérifier par emoji vous montre à tous les deux sept images ; si elles correspondent, personne n’est au milieu, et Element voit aussi la vérification. Vérifier cet appareil avec un autre des vôtres fait que votre propre Element fait confiance à Erevos. Voir [Matrix](#matrix).",
  "**Automatic backups to your own server too**: on Android, each automatic backup can also go to a folder on a server you choose, such as your Nextcloud, over WebDAV. Off until you add one. The server gets random bytes under a random name and cannot open them; it still sees your account, your address and when. See [Backups](#backup).":
    "**Les sauvegardes automatiques aussi vers ton propre serveur** : sur Android, chaque sauvegarde automatique peut aussi aller dans un dossier sur un serveur de ton choix, comme ton Nextcloud, par WebDAV. Désactivé tant que tu n’en ajoutes pas un. Le serveur reçoit des octets aléatoires sous un nom aléatoire et ne peut pas les ouvrir ; il voit quand même ton compte, ton adresse et quand. Voir [Sauvegardes](#backup).",
  "**Matrix Security Key and key backup**: enter the Security Key Element made, under Settings → Relay and networks → Matrix, and earlier messages open, new keys are backed up, and your other devices trust Erevos. An account with none can set one up there. See [Matrix](#matrix).":
    "**Clé de sécurité et sauvegarde des clés Matrix** : saisissez la clé de sécurité créée par Element, sous Réglages → Relais et réseaux → Matrix, et les messages précédents s’ouvrent, les nouvelles clés sont sauvegardées, et vos autres appareils font confiance à Erevos. Un compte sans clé peut en créer une là. Voir [Matrix](#matrix).",
  "**Matrix through Tor**: on Android, a space's Matrix account follows its choice under Settings → Relay and networks → Tor, so the Matrix server no longer sees where you are; the Matrix screen says when it goes through Tor. See [Matrix](#matrix).":
    "**Matrix par Tor** : sur Android, le compte Matrix d’un espace suit son choix sous Réglages → Relais et réseaux → Tor, donc le serveur Matrix ne voit plus où tu es ; l’écran Matrix dit quand il passe par Tor. Voir [Matrix](#matrix).",
  "**XMPP accounts in Erevos**: sign a space in to XMPP, under Settings → Relay and networks → XMPP, and chat with people who use Conversations, Monal, Gajim, Dino or another XMPP app, encrypted with OMEMO. These chats are not anonymous, and say so: the XMPP server sees who talks with whom. Text with delivery and read marks, photos and files, in the home list under an XMPP chip of its own, and through Tor on Android as you chose. See [XMPP](#xmpp).":
    "**Comptes XMPP dans Erevos** : connecte un espace à XMPP, sous Réglages → Relais et réseaux → XMPP, et discute avec des personnes qui utilisent Conversations, Monal, Gajim, Dino ou une autre app XMPP, chiffré avec OMEMO. Ces discussions ne sont pas anonymes, et le disent : le serveur XMPP voit qui parle avec qui. Du texte avec des marques de remise et de lecture, des photos et des fichiers, dans la liste de l’accueil sous une puce XMPP à part, et par Tor sur Android comme tu l’as choisi. Voir [XMPP](#xmpp).",
  "**Voice and video calls with people on XMPP**: the two tiles at the top of an XMPP chat call the person, and their calls ring on the same screen as Erevos's own, with apps that call as Conversations does. The call goes through your call relay or the XMPP server's, so they do not learn your address; the key that proves it passes through the XMPP servers, which could put themselves in between. See [XMPP](#xmpp).":
    "**Appels vocaux et vidéo avec des personnes sur XMPP** : les deux tuiles en haut d’une discussion XMPP appellent la personne, et ses appels sonnent sur le même écran que ceux d’Erevos, avec les apps qui appellent comme Conversations. L’appel passe par ton relais d’appel ou celui du serveur XMPP, donc elle n’apprend pas ton adresse ; la clé qui le prouve passe par les serveurs XMPP, qui pourraient se mettre entre les deux. Voir [XMPP](#xmpp).",
  "**Voice and video calls with people on Matrix**: on Android, the two tiles at the top of a Matrix chat call with Element Call, the call app of Element and Element X, which opens inside Erevos in a window of its own, and their calls ring here as Erevos's own do. Sound and picture are end-to-end encrypted and go through the media server your Matrix server names, never through Tor. See [Matrix](#matrix).":
    "**Appels vocaux et vidéo avec des gens sur Matrix** : sur Android, les deux tuiles en haut d’une discussion Matrix appellent avec Element Call, l’app d’appel d’Element et d’Element X, qui s’ouvre dans Erevos dans une fenêtre à elle, et leurs appels sonnent ici comme ceux d’Erevos. Le son et l’image sont chiffrés de bout en bout et passent par le serveur média que ton serveur Matrix indique, jamais par Tor. Voir [Matrix](#matrix).",
  "**Voice and video calls with people on Matrix, in the web app and on a computer**: the two tiles at the top of a Matrix chat call with Element Call there too, as on Android, over the app; its back arrow makes it small in a corner, so you can keep using Erevos during the call. Element Call runs apart from Erevos and can read nothing of it. See [Matrix](#matrix).":
    "**Appels vocaux et vidéo avec des gens sur Matrix, dans l’app web et sur un ordinateur** : les deux tuiles en haut d’une discussion Matrix appellent là aussi avec Element Call, comme sur Android, par-dessus l’app ; la flèche de retour de sa fenêtre la rend petite dans un coin, pour que tu puisses continuer à utiliser Erevos pendant l’appel. Element Call tourne à part d’Erevos et ne peut rien en lire. Voir [Matrix](#matrix).",
  "**Chats with people on other Nostr apps**: give a space a Nostr key of its own, under Settings → Relay and networks → Nostr chats, and chat with people who use Damus, Amethyst, Primal, 0xchat or another Nostr app, one to one or in groups, encrypted as NIP-17 asks: the relays see whom a message is for, not who wrote it. These chats are not anonymous, and say so: your key is the same to everyone you write to. Text, photos, files and reactions, in the home list under a Nostr chip of its own, and through Tor on Android as you chose. See [Chats with other Nostr apps](#nostr-chats).":
    "**Discussions avec des personnes sur d’autres applis Nostr** : donne à un espace sa propre clé Nostr, dans Réglages → Relais et réseaux → Discussions Nostr, et discute avec des personnes qui utilisent Damus, Amethyst, Primal, 0xchat ou une autre appli Nostr, en tête-à-tête ou en groupe, chiffré comme le demande NIP-17 : les relais voient à qui un message est destiné, pas qui l’a écrit. Ces discussions ne sont pas anonymes, et le disent : ta clé est la même pour tous ceux à qui tu écris. Du texte, des photos, des fichiers et des réactions, dans la liste de l’accueil sous un bouton Nostr à elles, et par Tor sur Android comme tu l’as choisi. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Notices for Matrix, XMPP and Nostr messages**: a message in a chat on Matrix, XMPP or Nostr shows a notice and counts in the number on Erevos's icon, as in Erevos's own chats. On Android, Notifications at the bottom of such a chat mutes it or gives it a sound of its own, and an XMPP or Matrix call rings with its chat's ringtone. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Notifications pour les messages Matrix, XMPP et Nostr** : un message dans une discussion Matrix, XMPP ou Nostr affiche une notification et compte dans le nombre sur l’icône d’Erevos, comme dans les discussions d’Erevos lui-même. Sur Android, Notifications, en bas d’une telle discussion, la met en sourdine ou lui donne un son à elle, et un appel XMPP ou Matrix sonne avec la sonnerie de sa discussion. Voir [Matrix](#matrix), [XMPP](#xmpp) et [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**A closed space tells of Matrix messages**: on Android, Say a message came under While this space is closed, on the Matrix screen, has a closed space say \"New message\" when something comes on Matrix while another space is open, never what, from whom or in which chat. Off until you choose it. The Matrix server then tells the space's relay of each message, with no words in it: it learns the relay's address, and the relay when messages come. See [Matrix](#matrix).":
    "**Un espace fermé signale les messages Matrix** : sur Android, « Signaler les nouveaux messages » sous « Tant que cet espace est fermé », sur l’écran Matrix, fait dire « Nouveau message » à un espace fermé quand quelque chose arrive sur Matrix pendant qu’un autre espace est ouvert, jamais quoi, de qui ni dans quelle discussion. Désactivé tant que vous ne le choisissez pas. Le serveur Matrix signale alors chaque message au relais de l’espace, sans aucun de ses mots : il apprend l’adresse du relais, et le relais quand des messages arrivent. Voir [Matrix](#matrix).",
  "**Made with others' open source**: About Erevos, and the guide, now name the open-source projects Erevos is built on, with their makers and their licences. See [What Erevos is](#about).":
    "**Fait avec l’open source des autres** : Dans À propos d’Erevos et dans le guide, les projets open source sur lesquels Erevos est construit sont désormais nommés, avec leurs auteurs et leurs licences. Voir [Ce qu’est Erevos](#about).",
  "**Groups on XMPP**: under Settings → Relay and networks → XMPP, make a private group with your contacts, encrypted with OMEMO for every member as Conversations' private groups are, or join a group by its address, and answer invitations to groups. A group that is not private, a channel, is not encrypted, and says so. Your groups follow your account's other XMPP apps, and a channel tells only of messages that name you. See [XMPP](#xmpp).":
    "**Groupes sur XMPP** : sous Réglages → Relais et réseaux → XMPP, crée un groupe privé avec tes contacts, chiffré avec OMEMO pour chaque membre comme les groupes privés de Conversations, ou rejoins un groupe par son adresse, et réponds aux invitations à des groupes. Un groupe qui n’est pas privé, un canal, n’est pas chiffré, et le dit. Tes groupes suivent les autres apps XMPP de ton compte, et un canal ne signale que les messages qui te nomment. Voir [XMPP](#xmpp).",
  "**More in Matrix chats**: hold a message to react to it, reply to it, copy it and, if it is yours, edit it or delete it for everyone. Load earlier messages brings in older ones, and the microphone under the message box sends voice messages that Element plays too. Reactions are not encrypted, as Element sends them. See [Matrix](#matrix).":
    "**Davantage dans les discussions Matrix** : appuyez longuement sur un message pour y réagir, lui répondre, le copier et, s’il est de vous, le modifier ou le supprimer pour tout le monde. « Charger les messages précédents » ramène les plus anciens, et le micro sous le champ du message envoie des messages vocaux qu’Element lit aussi. Les réactions ne sont pas chiffrées, comme Element les envoie. Voir [Matrix](#matrix).",
  "**Video added to an XMPP call**: in a voice call with someone on XMPP, either of you can turn on video with Add video; the other is asked first and can say Not now. It works with apps that add video to a call as Conversations does. See [XMPP](#xmpp).":
    "**La vidéo ajoutée à un appel XMPP** : dans un appel vocal avec quelqu’un sur XMPP, chacun de vous peut activer la vidéo avec « Ajouter la vidéo » ; l’autre personne est d’abord interrogée et peut répondre « Pas maintenant ». Cela marche avec les applis qui ajoutent la vidéo à un appel comme Conversations. Voir [XMPP](#xmpp).",
  "**Voice messages and replies in Nostr chats**: hold the microphone under the message box to send a voice message, which plays with Play; hold a message to reply to it, and the answer shows the message it is to, here and in other Nostr apps. See [Chats with other Nostr apps](#nostr-chats).":
    "**Messages vocaux et réponses dans les discussions Nostr** : maintenez le micro sous le champ du message pour envoyer un message vocal, qui se lit avec « Lire » ; appuyez longuement sur un message pour lui répondre, et la réponse montre le message auquel elle répond, ici et dans les autres applis Nostr. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**OMEMO 2 in XMPP chats**: a message to someone whose app speaks OMEMO 2, as Kaidan does, now goes with OMEMO 2 to that app and with OMEMO 0.3 to their others, as before. The XMPP screen shows this device's key both ways, to compare with what each app shows. See [XMPP](#xmpp).":
    "**OMEMO 2 dans les discussions XMPP** : un message à quelqu’un dont l’appli parle OMEMO 2, comme Kaidan, part maintenant avec OMEMO 2 vers cette appli et avec OMEMO 0.3 vers ses autres applis, comme avant. L’écran XMPP montre la clé de cet appareil des deux façons, pour la comparer avec ce que montre chaque appli. Voir [XMPP](#xmpp).",
  "**Hidden chats can have their own Matrix, XMPP and Nostr accounts**: under the list of a place of hidden chats, Matrix, XMPP and Nostr open an account of that place alone, apart from the space's, kept encrypted with the hidden chats' key. Its chats show among the hidden chats only. It connects while they are open, and while they are closed too if Receive while closed is on, as the hidden chats do: then a message says only \"New message\", and a call rings with no name and is answered with the PIN. See [Hidden chats](#hidden).":
    "**Les discussions masquées peuvent avoir leurs propres comptes Matrix, XMPP et Nostr** : sous la liste d’un emplacement de discussions masquées, Matrix, XMPP et Nostr ouvrent un compte de cet emplacement seul, à part de celui de l’espace et gardé chiffré avec la clé des discussions masquées. Ses discussions ne s’affichent que parmi les discussions masquées. Il se connecte tant qu’elles sont ouvertes, et aussi quand elles sont fermées si Recevoir une fois fermées est activé, comme le font les discussions masquées elles-mêmes : alors un message dit seulement « Nouveau message », et un appel sonne sans nom et se prend avec le code PIN. Voir [Discussions masquées](#hidden).",
  "**Matrix, XMPP and Nostr in backups**: a backup now holds the Matrix, XMPP and Nostr accounts of every space and of its hidden chats. After a restore, a Nostr key comes back with its chats as they were; an XMPP account goes on as a new device of the account, with its contacts and chats; a Matrix account is let go of on this phone, and the space signs in again as a new device; its Security Key opens the messages from before. See [Backups](#backup).":
    "**Matrix, XMPP et Nostr dans les sauvegardes** : une sauvegarde contient désormais les comptes Matrix, XMPP et Nostr de chaque espace et de ses discussions masquées. Après une restauration, une clé Nostr revient avec ses discussions telles qu’elles étaient ; un compte XMPP continue comme un nouvel appareil du compte, avec ses contacts et ses discussions ; un compte Matrix est lâché sur ce téléphone, et l’espace se reconnecte comme un nouvel appareil ; sa clé de sécurité ouvre les messages d’avant. Voir [Sauvegardes](#backup).",
  "**Matrix voice messages show their waveform, and Nostr answers can be photos**: a voice message sent in a Matrix chat carries its waveform, which Element draws, and one that comes with a waveform shows it under Play; in a Nostr chat, a photo, file or voice message sent while a message shows over the message box answers it. See [Matrix](#matrix) and [Chats with other Nostr apps](#nostr-chats).":
    "**Les messages vocaux Matrix montrent leur forme d’onde, et les réponses Nostr peuvent être des photos** : un message vocal envoyé dans une discussion Matrix porte sa forme d’onde, qu’Element dessine, et un message vocal qui arrive avec une forme d’onde la montre sous Lire ; dans une discussion Nostr, une photo, un fichier ou un message vocal envoyé pendant qu’un message s’affiche au-dessus du champ lui répond. Voir [Matrix](#matrix) et [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Group calls in XMPP groups**: in a private XMPP group, start a voice or video call, answer one that rings, or join one going on, together with people who use Dino. See [XMPP](#xmpp).":
    "**Appels de groupe dans les groupes XMPP** : dans un groupe privé XMPP, lance un appel vocal ou vidéo, réponds à un appel qui sonne ou rejoins un appel en cours, avec des personnes qui utilisent Dino. Voir [XMPP](#xmpp).",
  '**A call to a slow phone rings in full**: the caller now waits up to a minute and a quarter for the other phone to say it rings, and then 45 seconds from then, so a call that reached it late no longer rings there only to stop at once; and the phone called reads a call before anything it has to send, and waits for calls again at once after its network changes. See [Chat through a relay](#relay).':
    '**Un appel vers un téléphone lent sonne en entier** : celui qui appelle attend maintenant jusqu\'à une minute et quart que l\'autre téléphone dise qu\'il sonne, puis 45 secondes à partir de là, si bien qu\'un appel arrivé en retard ne sonne plus pour s\'arrêter aussitôt ; et le téléphone appelé lit un appel avant tout ce qu\'il a à envoyer, et attend de nouveau les appels tout de suite après un changement de réseau. Voir [Discuter par un relais](#relay).',
  "**The web app and the computer reach Matrix, XMPP and Nostr servers over HTTPS**: their page policy allowed only WebSocket connections, so Matrix sign-in, XMPP server discovery and file sharing, and Nostr files and name lookups failed there. They work now. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**L’app web et l’ordinateur joignent les serveurs Matrix, XMPP et Nostr en HTTPS** : la politique de leur page n’autorisait que les connexions WebSocket, si bien que la connexion à Matrix, la découverte du serveur XMPP et l’envoi de fichiers, ainsi que les fichiers et les recherches de noms sur Nostr, échouaient là. Tout marche maintenant. Voir [Matrix](#matrix), [XMPP](#xmpp) et [Discussions avec d’autres applis Nostr](#nostr-chats).",
  // 3.4.2
  '**A message sent as a chat opens waits for it**, marked Sending…, and goes as soon as the chat is open, never saying that Erevos cannot encrypt.':
    '**Un message envoyé pendant qu’une discussion s’ouvre l’attend**, marqué Envoi…, et part dès qu’elle est ouverte, sans dire qu’Erevos ne peut pas chiffrer.',
  '**What you read as a chat opens stays read**: the home screen no longer counts it as new.':
    '**Ce que tu lis pendant qu’une discussion s’ouvre reste lu** : l’écran d’accueil ne le compte plus comme nouveau.',
  '**No question from Samsung about its sharing**: on a Samsung phone, Wi-Fi Aware and the Wi-Fi with phones nearby stay off until you turn them on. See [Chat with a nearby phone](#nearby).':
    '**Plus de question de Samsung sur son partage** : sur un téléphone Samsung, Wi-Fi Aware et le Wi-Fi avec les téléphones à proximité restent désactivés tant que tu ne les actives pas. Voir [Discuter avec un téléphone à proximité](#nearby).',
  '**The SMS field keeps its width on a small screen**: Photo and Send beside it are round buttons, as in a chat.':
    '**Le champ du SMS garde sa largeur sur un petit écran** : Photo et Envoyer à côté sont des boutons ronds, comme dans une discussion.',
  // 3.4.1
  '**Send answers at once**: a short buzz as you press it, the field empties and the message shows, marked Sending…, so it never goes twice.':
    '**Envoyer réagit aussitôt** : une courte vibration à l’appui, le champ se vide et le message apparaît, marqué Envoi…, si bien qu’il ne part jamais deux fois.',
  '**The screen no longer stays pushed up** after the keyboard closed behind a sheet, a dialog or another app.':
    '**L’écran ne reste plus remonté** après que le clavier s’est fermé derrière un panneau, une boîte de dialogue ou une autre app.',
  '**Importing a chat with its photos no longer freezes Erevos**: the screen moves while the files come in, says what share of them is in, and **Cancel** stops it. A chat moved into hidden chats takes the chats imported into it along. See [Imported chats](#import).':
    '**Importer une discussion avec ses photos ne fige plus Erevos** : l’écran reste vivant pendant l’arrivée des fichiers, dit quelle part en est arrivée, et **Annuler** l’arrête. Une discussion déplacée dans les discussions cachées emporte les discussions importées dedans. Voir [Discussions importées](#import).',
  // 3.4.0
  '**Your relay proves its own key**: every connection to it starts with a check only the relay holding that key can pass, so no one in between can pass for it. Once it has, Erevos never reaches it without the check. Your relay needs an update for it.':
    '**Ton relais prouve sa propre clé** : chaque connexion commence par une vérification que seul le relais qui détient cette clé peut réussir, donc personne entre les deux ne peut se faire passer pour lui. Une fois qu’il l’a prouvée, Erevos ne le joint plus jamais sans cette vérification. Ton relais doit être mis à jour pour cela.',
  '[Transparency](#transparency), a new part of the guide: what the server behind Erevos keeps and for how long, what it does not keep, and who else sees something.':
    '[Transparence](#transparency), une nouvelle partie du guide : ce que le serveur derrière Erevos garde et combien de temps, ce qu’il ne garde pas, et qui d’autre voit quelque chose.',
  "**What's new**: this list, in Settings → General, by version.": '**Nouveautés** : cette liste, dans Réglages → Général, par version.',
  "**Nothing shows behind a chat's PIN**: none of the messages of a chat locked with a PIN is drawn until its PIN is typed, and with glass, a wallpaper or a style's own scene, the PIN screen is a dense frost that lets nothing through.":
    "**Rien ne se voit derrière le code PIN d’une discussion** : aucun message d’une discussion verrouillée par un code PIN n’est affiché avant que son code PIN soit saisi, et avec le verre, un fond d’écran ou un style qui dessine sa propre scène, l’écran du code PIN est un givre dense qui ne laisse rien voir.",
  "**A group video call from the top of the group**: a blue camera beside the green handset, as in a contact's chat.":
    "**Un appel vidéo de groupe en haut du groupe** : une caméra bleue à côté du combiné vert, comme dans la discussion avec un contact.",
  "**A relay queue for each contact**: each contact writes to a queue only they know, so the relay cannot tell that two contacts write to the same phone, and deleting or blocking someone deletes only theirs. Your relay needs an update for it.":
    "**Une file du relais pour chaque contact** : chaque contact écrit dans une file que lui seul connaît, si bien que le relais ne peut pas savoir que deux contacts écrivent au même téléphone, et supprimer ou bloquer quelqu’un n’efface que la sienne. Votre relais doit être mis à jour pour cela.",
  "**Hidden chats, more like the others**: they close after 30 seconds in the background, not at once, and never during a call or while you pick a photo or a file; while open, a message plays its sound, and link previews have a switch of their own there. See [Hidden chats](#hidden).":
    "**Les discussions masquées, plus comme les autres** : elles se ferment après 30 secondes en arrière-plan, pas tout de suite, et jamais pendant un appel ni pendant que vous choisissez une photo ou un fichier ; ouvertes, un message joue son son, et les aperçus de liens y ont leur propre interrupteur. Voir [Discussions masquées](#hidden).",
  "**Hidden chats that receive while closed**: a switch at the top of each place, on for new places, has them receive as your other chats do: their contacts see at once that a message came, a notice says only \"New message\", and a call rings with no name. See [Hidden chats](#hidden).":
    "**Des discussions masquées qui reçoivent une fois fermées** : un interrupteur en haut de chaque emplacement, activé pour les nouveaux, les fait recevoir comme vos autres discussions : leurs contacts voient aussitôt qu’un message est arrivé, une notification dit seulement « Nouveau message », et un appel sonne sans nom. Voir [Discussions masquées](#hidden).",
  "**Hidden chats wait and import too**: what cannot go now waits, marked Waiting, and goes by itself through their relay; Send later works there as in your other chats; and a chat from Telegram, WhatsApp or Viber can be imported into a hidden chat, kept only there. See [Hidden chats](#hidden).":
    "**Les discussions masquées attendent et importent aussi** : ce qui ne peut pas partir maintenant attend, marqué « En attente », et part tout seul par leur relais ; « Envoyer plus tard » y fonctionne comme dans vos autres discussions ; et une discussion de Telegram, WhatsApp ou Viber peut être importée dans une discussion masquée, gardée là seulement. Voir [Discussions masquées](#hidden).",
  "**Hidden chats listed like your chats**: they open on a list as the home screen's, with what was said last and how many are not read, and each place has a Chat with myself of its own at its top. See [Hidden chats](#hidden).":
    "**Les discussions masquées en liste comme vos discussions** : elles s'ouvrent sur une liste comme celle de l'écran d'accueil, avec ce qui a été dit en dernier et combien ne sont pas lus, et chaque emplacement a en haut sa propre Discussion avec moi-même. Voir [Discussions masquées](#hidden).",
  "**More in hidden chats**: with Receive while closed on, what comes to them through Nostr is read while they are closed too; and there a contact can be added from a photo of their QR code, and a hidden contact given a photo. See [Hidden chats](#hidden).":
    "**Plus dans les discussions masquées** : avec Recevoir une fois fermées, ce qui leur arrive par Nostr est lu aussi pendant qu'elles sont fermées ; et on peut y ajouter un contact depuis une photo de son code QR, et donner une photo à un contact masqué. Voir [Discussions masquées](#hidden).",
  "**Hidden chats with no relay**: as your other chats, they can begin through Nostr only: their contact link and QR code say where they read there, and texts and reactions go there. See [Hidden chats](#hidden).":
    "**Discussions masquées sans relais** : comme vos autres discussions, elles peuvent commencer par Nostr seul : leur lien de contact et leur code QR disent où elles lisent là-bas, et les textes et réactions y vont. Voir [Discussions masquées](#hidden).",
  "**Groups in hidden chats**: under their list, New group makes a group with their contacts; it lists among their chats, goes through their relay only, and is read while they are closed if Receive while closed is on. See [Hidden chats](#hidden).":
    "**Groupes dans les discussions masquées** : sous leur liste, Nouveau groupe crée un groupe avec leurs contacts ; il figure parmi leurs discussions, passe par leur relais seul, et est lu pendant qu'elles sont fermées si Recevoir une fois fermées est activé. Voir [Discussions masquées](#hidden).",
  "**No test version line**: the home screen no longer ends saying this is a test version. The guide still says exactly what is protected, and that nothing has been audited yet. See [What is protected today](#privacy).":
    "**Plus de ligne « version de test »** : l'écran d'accueil ne se termine plus en disant que c'est une version de test. Le guide dit toujours exactement ce qui est protégé, et que rien n'a encore été audité. Voir [Ce qui est protégé aujourd'hui](#privacy).",
  "**The contacts menu in hidden chats**: their Contacts has a menu again, with what is theirs only: a .vcf file imported into them, their contacts saved as a .vcf file, and a contact's QR code read from a photo. An Erevos ID typed there adds them to the hidden chats. See [Contacts](#contacts).":
    "**Le menu des contacts dans les discussions masquées** : leurs Contacts ont de nouveau un menu, avec seulement ce qui est à elles : un fichier .vcf importé chez elles, leurs contacts enregistrés en fichier .vcf, et le code QR d’un contact lu sur une photo. Un identifiant Erevos saisi là ajoute la personne aux discussions masquées. Voir [Contacts](#contacts).",
  // 3.3.2
  '**The plain call button for more contacts**: the orange keypad at the top of a contact’s chat also takes the number of a contact you connected them to (**Connect to one of my contacts**), the mobile number first.':
    '**Le bouton d’appel mobile pour plus de contacts** : le clavier orange en haut de la discussion d’un contact prend aussi le numéro du contact auquel tu l’as associé (**Associer à un de mes contacts**), le mobile en premier.',
  // 3.3.1
  '**Viber chats can be imported**: from the HTML file of the Android app Backup Text for Viber, words only.':
    '**Les discussions Viber s’importent** : depuis le fichier HTML de l’app Android Backup Text for Viber, le texte seulement.',
  // 3.3.0
  '**Start without a relay, through Nostr**: **Start without a relay** on New chat. Texts, stickers, reactions, edits and the delivered and read marks go through Nostr over Tor. Photos, voice messages, files and calls still need a relay or a phone nearby.':
    '**Commencer sans relais, par Nostr** : **Commencer sans relais** dans Nouvelle discussion. Les textes, stickers, réactions, modifications et les marques « arrivé » et « lu » passent par Nostr via Tor. Les photos, messages vocaux, fichiers et appels ont encore besoin d’un relais ou d’un téléphone à proximité.',
  '**The relay comes by itself**: whoever has a relay that invites sends a contact with no relay an invite once, inside the chat, and the other phone takes it by itself.':
    '**Le relais vient tout seul** : qui a un relais qui invite envoie une fois une invitation à un contact sans relais, dans la discussion, et l’autre téléphone l’accepte tout seul.',
  '**Told when a new version is out** (Android): once a day Erevos asks LPHL’s server, then shows a pinned Erevos row and a notice, only for a version the release computer signed. It turns off in Settings → General → Updates.':
    '**Prévenu quand une nouvelle version sort** (Android) : une fois par jour, Erevos demande au serveur de LPHL, puis affiche une ligne Erevos épinglée et une notification, seulement pour une version signée par l’ordinateur des versions. Cela se désactive dans Réglages → Général → Mises à jour.',
  '**Lock a chat with a PIN**: Details → Lock with a PIN, for chats and groups. Nothing of it shows in search, starred messages or imports. In hidden chats it asks for no PIN.':
    '**Verrouiller une discussion par un code PIN** : Détails → Verrouiller par un code PIN, pour les discussions et les groupes. Rien n’en apparaît dans la recherche, les messages avec étoile ni les importations. Dans les discussions masquées, aucun code PIN n’est demandé.',
  '**A new handset** on the green tiles: Phone, and the call in a chat.': '**Un nouveau combiné** sur les tuiles vertes : Téléphone, et l’appel dans une discussion.',
  '**A new New chat screen**: How you connect now at the top, three large cards for a phone without a relay (I have an invite, Sign in with LPHL, Start without a relay), and the technical part under For advanced users.':
    '**Un nouvel écran Nouvelle discussion** : « Comment tu te connectes maintenant » en haut, trois grandes cartes pour un téléphone sans relais (J’ai une invitation, Se connecter avec LPHL, Commencer sans relais), et la partie technique sous « Pour les utilisateurs avancés ».',
  '**Nostr steadier through Tor**: each Nostr relay has its own way through Tor, and after a failure it tries a new exit. A clearer error on the Nostr screen.':
    '**Nostr plus stable via Tor** : chaque relais Nostr a son propre chemin dans Tor, et après un échec il essaie une nouvelle sortie. Une erreur plus claire sur l’écran Nostr.',
  '**When the connection to the relay drops** while Erevos waits on it, Erevos notices and connects again, where it stayed stuck before.':
    '**Quand la connexion au relais tombe** pendant qu’Erevos l’attend, Erevos s’en rend compte et se reconnecte, là où il restait bloqué avant.',
  '**Invite by SMS** (Android): on a phone contact’s card, for one person, for 2 days. The link opens a page that offers Erevos (the APK for Android, the web app for an iPhone or a computer), then opens the invite. The QR code and Share the invite stay as they were.':
    '**Inviter par SMS** (Android) : sur la fiche d’un contact du téléphone, pour une personne, pendant 2 jours. Le lien ouvre une page qui propose Erevos (l’APK pour Android, l’app web pour un iPhone ou un ordinateur), puis ouvre l’invitation. Le code QR et « Partager l’invitation » restent comme avant.',
  '**Fixes to the SMS invite**: a link copied as /i/#… works too, an older web app opens the invite as well, and on iOS 26 it says Share is under •••.':
    '**Corrections de l’invitation par SMS** : un lien copié sous la forme /i/#… marche aussi, une app web plus ancienne ouvre elle aussi l’invitation, et sous iOS 26 elle indique que Partager est dans •••.',
  '**A phone call button** in Erevos chats and SMS chats.': '**Un bouton d’appel téléphonique** dans les discussions Erevos et les discussions SMS.',
  // 3.2.1
  '**Edit a message** you sent, up to a day after: to contacts, groups and linked devices, with Edited beside the time.':
    '**Modifier un message** envoyé, jusqu’à un jour après : pour les contacts, les groupes et les appareils associés, avec « Modifié » à côté de l’heure.',
  '**Nostr says what it did**: Sent through Nostr, and on the Nostr screen what each relay did last.':
    '**Nostr dit ce qu’il a fait** : « Envoyé par Nostr », et sur l’écran Nostr ce que chaque relais a fait en dernier.',
  '**Coloured call buttons** at the top of a chat: video blue, voice green.': '**Des boutons d’appel en couleur** en haut d’une discussion : vidéo en bleu, voix en vert.',
  // 3.2.0
  'Arrows to the start and the end of a chat; earlier messages come by themselves as you scroll.':
    'Des flèches vers le début et la fin d’une discussion ; les messages plus anciens arrivent tout seuls quand tu fais défiler.',
  'Chats imported from Telegram and WhatsApp look like Erevos messages: bubbles, days, photos, voice messages, search.':
    'Les discussions importées de Telegram et WhatsApp ressemblent aux messages Erevos : bulles, jours, photos, messages vocaux, recherche.',
  'Dogs instead of cats in the stickers.': 'Des chiens au lieu des chats dans les stickers.',
  'Screenshots: a switch in Settings → Privacy and security.': 'Captures d’écran : un interrupteur dans Réglages → Confidentialité et sécurité.',
  'Hidden chats from New chat: hold it for a second.': 'Les discussions masquées depuis Nouvelle discussion : reste appuyé une seconde dessus.',
  'Coloured tiles on the home screen: Phone green, Contacts violet, the lock orange.': 'Des tuiles en couleur sur l’écran d’accueil : Téléphone en vert, Contacts en violet, le cadenas en orange.',
  '**Chat with myself**, always first, and **Remind me**, the orange bell.': '**Discussion avec moi-même**, toujours en premier, et **Me rappeler**, la cloche orange.',
  '**Media, links and files** in a chat’s Details, with a calendar and Go to a day.':
    '**Médias, liens et fichiers** dans les Détails d’une discussion, avec un calendrier et « Aller à un jour ».',
  'Import a chat from inside the chat: Details → Imported chats.': 'Importer une discussion depuis la discussion elle-même : Détails → Discussions importées.',
  'A closed space can say that a message came while another space is open.': 'Un espace fermé peut signaler qu’un message est arrivé pendant qu’un autre espace est ouvert.',
  'The message menu says when a message went or came through Nostr.': 'Le menu d’un message indique s’il est parti ou arrivé par Nostr.',
  '**Support Erevos**: Liberapay, PayPal, Monero, Bitcoin.': '**Soutenir Erevos** : Liberapay, PayPal, Monero, Bitcoin.',
  'Who makes Erevos and why, in About Erevos; the guide says why everywhere.': 'Qui fait Erevos et pourquoi, dans À propos d’Erevos ; le guide dit partout pourquoi.',
  // 3.1.2
  '**Settings in 8 groups**, with a search: General, Appearance, Notifications, Privacy and security, Relay and networks, Phone and SMS, Data and devices, For testing. The home screen’s ⋯ keeps only the places, and Settings last.':
    '**Les réglages en 8 groupes**, avec une recherche : Général, Apparence, Notifications, Confidentialité et sécurité, Relais et réseaux, Téléphone et SMS, Données et appareils, Pour les tests. Le ⋯ de l’écran d’accueil ne garde que les écrans, et Réglages en dernier.',
  // 3.1.1
  'Check for updates says what stopped an update.': 'Rechercher des mises à jour dit ce qui a bloqué une mise à jour.',
  'Invite someone is not made from a token for all; it asks you to sign in to the relay first.':
    '« Inviter quelqu’un » ne passe plus par un jeton commun ; il te demande d’abord de te connecter au relais.',
  'The relay’s token for all becomes a token of the phone’s own, by itself (needs the relay updated).':
    'Le jeton commun du relais devient tout seul un jeton propre au téléphone (le relais doit être à jour).',
  'A relay that refuses through Tor says why.': 'Un relais qui refuse par Tor dit pourquoi.',
  // 3.1.0
  'Less battery in the background: the relay, Tor and the nearby radios.': 'Moins de batterie en arrière-plan : le relais, Tor et les radios de proximité.',
  'Erevos no longer closes when you make a sticker from a photo.': 'Erevos ne se ferme plus quand tu fais un sticker à partir d’une photo.',
  'Hidden chats’ notices are right.': 'Les notifications des discussions masquées sont justes.',
  'Hidden chats by holding New chat.': 'Les discussions masquées en restant appuyé sur Nouvelle discussion.',
  'A search for contacts on the Phone.': 'Une recherche de contacts dans Téléphone.',
  'New chat shows first how to add a contact.': 'Nouvelle discussion montre d’abord comment ajouter un contact.',
  'A call shows over the screen saver, and the screen wakes.': 'Un appel s’affiche par-dessus l’économiseur d’écran, et l’écran se réveille.',
  'Erevos in other apps’ Share.': 'Erevos dans le menu Partager des autres apps.',
  'A sound for every new message, also while Erevos shows.': 'Un son pour chaque nouveau message, même quand Erevos est à l’écran.',
  'The SMS settings say right what holding does.': 'Les réglages SMS disent correctement ce que fait un appui long.',
  // 3.0.0
  'Each icon opens what it names: Erevos, SMS, Phone, Contacts, the widget.': 'Chaque icône ouvre ce qu’elle indique : Erevos, SMS, Téléphone, Contacts, le widget.',
  '**Messages through Tor by default**: Messages, Everything or Nothing.': '**Les messages par Tor par défaut** : Messages, Tout ou Rien.',
  '**Texts through Nostr**: three public relays, through Tor, with your own relay as backup after 5 minutes.':
    '**Les textes par Nostr** : trois relais publics, par Tor, avec ton propre relais en secours après 5 minutes.',
  // 2.0.3
  'One invite for everything: the relay and the contact together.': 'Une seule invitation pour tout : le relais et le contact ensemble.',
  'Spam rules for senders and numbers abroad, with the reason.': 'Des règles anti-spam pour les expéditeurs et les numéros de l’étranger, avec la raison.',
  '480 stickers in 20 sets.': '480 stickers en 20 séries.',
  'Lighter chats on older phones; QR codes at once.': 'Des discussions plus légères sur les anciens téléphones ; les codes QR tout de suite.',
  'Copy code for one-time codes in SMS.': '« Copier le code » pour les codes à usage unique dans les SMS.',
  'Locked, Erevos keeps receiving.': 'Verrouillé, Erevos continue de recevoir.',
  'Faster contacts; the hidden chats’ notice counts only messages.': 'Des contacts plus rapides ; la notification des discussions masquées ne compte que les messages.',
  'The relay tries every address: push, other relays, the LPHL sign-in.': 'Le relais essaie chaque adresse : push, autres relais, la connexion LPHL.',
  // 2.0.2
  'Swiping on the tabs only changes the tab.': 'Glisser sur les onglets ne fait que changer d’onglet.',
  'The icons fill the launcher’s shape.': 'Les icônes remplissent la forme du lanceur.',
  // 2.0.1
  'Coloured icons (Erevos red, Phone green, SMS blue, Contacts violet) and a new SMS icon.':
    'Des icônes en couleur (Erevos en rouge, Téléphone en vert, SMS en bleu, Contacts en violet) et une nouvelle icône SMS.',
  'A colour for each icon, and the order of the widget’s buttons.': 'Une couleur pour chaque icône, et l’ordre des boutons du widget.',
  'Swipe to go back, and between tabs.': 'Glisser pour revenir en arrière, et entre les onglets.',
  // 2.0.0
  'An update of the WebView no longer closes Erevos.': 'Une mise à jour de la WebView ne ferme plus Erevos.',
  'Deleting or blocking a contact gives you a new queue on the relay.': 'Supprimer ou bloquer un contact te donne une nouvelle file d’attente sur le relais.',
  'A new contact can take the name of a contact on the phone.': 'Un nouveau contact peut prendre le nom d’un contact du téléphone.',
  '**Sign in to the relay with LPHL**, and **invites to the relay**.': '**Se connecter au relais avec LPHL**, et **les invitations au relais**.',
  'Permissions in the web app, and more on Android; the web app’s notice says how many came.':
    'Des autorisations dans l’app web, et davantage sur Android ; la notification de l’app web dit combien de messages sont arrivés.',
  'Hidden chats can ring calls while they are closed.': 'Les discussions masquées peuvent faire sonner les appels quand elles sont fermées.',
  'New keys every month in chats, every week in groups.': 'De nouvelles clés chaque mois dans les discussions, chaque semaine dans les groupes.',
  'Linked devices work with the phone off.': 'Les appareils associés fonctionnent téléphone éteint.',
  'A new chat screen; QR codes from a photo; the Phone for small screens.': 'Un nouvel écran de discussion ; les codes QR depuis une photo ; Téléphone pour les petits écrans.',
  'Add as contact inside a group.': '« Ajouter comme contact » dans un groupe.',
  'Stickers in sets, moving, and your own.': 'Des stickers en séries, animés, et les tiens.',
  'SMS inside the Erevos chat.': 'Les SMS dans la discussion Erevos.',
  'Android updates need the release computer’s signature.': 'Les mises à jour Android exigent la signature de l’ordinateur des versions.',
  'An F-Droid build; Serbo-Croatian; new version numbers.': 'Une version F-Droid ; le serbo-croate ; de nouveaux numéros de version.',
  'Much for security: Argon2id, messages encrypted for the relay too, a token for each phone, no link starts a call.':
    'Beaucoup pour la sécurité : Argon2id, des messages chiffrés aussi pour le relais, un jeton pour chaque téléphone, aucun lien ne lance d’appel.',
  // 0.1.16
  'Imports from Telegram and WhatsApp bring photos, videos, voice messages and files.': 'Les importations depuis Telegram et WhatsApp apportent photos, vidéos, messages vocaux et fichiers.',
  'A phone without a relay talks through a place on a contact’s relay.': 'Un téléphone sans relais communique par une place sur le relais d’un contact.',
  // 0.1.14
  'Back to my chats, for hidden chats.': '« Retour à mes discussions », pour les discussions masquées.',
  'Erevos receives and rings even after you swipe it away from the recent apps.': 'Erevos reçoit et sonne même une fois balayé hors des applis récentes.',
  // 0.1.12
  'Hidden chats can say a message came.': 'Les discussions masquées peuvent signaler qu’un message est arrivé.',
  'Fixes: menus, QR codes from a photo, Bluetooth on Android 17, long lists.': 'Corrections : menus, codes QR depuis une photo, Bluetooth sous Android 17, longues listes.',
  // 0.1.11
  'The Phone without the password, if you allow it; a home screen widget; an SMS and Erevos filter.':
    'Téléphone sans le mot de passe, si tu l’autorises ; un widget pour l’écran d’accueil ; un filtre SMS et Erevos.',
  // 0.1.10
  'Links wait for the password; Phone and Contacts icons; the Erevos ID on a contact.': 'Les liens attendent le mot de passe ; les icônes Téléphone et Contacts ; l’ID Erevos sur un contact.',
  // 0.1.8
  '61 new features: 5 new languages, linked devices, public groups, replies, reactions, polls, send later, Erevos as the phone and contacts app, Tor bridges, the fingerprint, Windows and more.':
    '61 nouvelles fonctions : 5 nouvelles langues, appareils associés, groupes publics, réponses, réactions, sondages, envoi différé, Erevos comme app de téléphone et de contacts, ponts Tor, l’empreinte digitale, Windows et plus encore.',
  // 0.1.7 to 0.1.2
  'SMS notices in the background.': 'Les notifications SMS en arrière-plan.',
  'The web app comes out with every release.': 'L’app web sort avec chaque version.',
  'Greek in the whole app.': 'Le grec dans toute l’app.',
  'Web Push in the web app.': 'Web Push dans l’app web.',
  'The first signed Android release: encrypted chats, calls, groups, hidden chats, backups, imports, and phones nearby without the internet.':
    'La première version Android signée : discussions chiffrées, appels, groupes, discussions masquées, sauvegardes, importations, et téléphones à proximité sans internet.',
  "**Two new sticker sets of 24 moods**: **Tux**, the Linux penguin as he is drawn, and **Aikido**, an aikidoka in keikogi and a wide hakama, who also bows, sits in seiza and rolls.":
    "**Deux nouvelles séries d'autocollants de 24 humeurs** : **Tux**, le manchot de Linux tel qu'il est dessiné, et **Aïkido**, un aïkidoka en keikogi et large hakama, qui salue aussi, s'assoit en seiza et fait une roulade.",
  "**A new sticker set, Takis**: a caricature in a dark suit and a purple tie with dots, in 24 moods that move.":
    "**Une nouvelle série d'autocollants, Takis** : une caricature en costume sombre et cravate violette à pois, en 24 humeurs qui bougent.",
  "**Photos, files and voice messages with no relay**: when there is no relay between you and your contact and they read on Nostr, a voice message goes through Nostr like a text, a photo up to 3 MB in pieces, and a larger photo, a video or another file, up to 20 MB, to an encrypted file server (Blossom), all through Tor. See [Through Nostr](#nostr).":
    "**Photos, fichiers et messages vocaux sans relais** : quand il n’y a pas de relais entre toi et ton contact et qu’il lit sur Nostr, un message vocal passe par Nostr comme un texte, une photo jusqu’à 3 Mo en morceaux, et une photo plus grande, une vidéo ou un autre fichier, jusqu’à 20 Mo, vers un serveur de fichiers chiffré (Blossom), le tout via Tor. Voir [Par Nostr](#nostr).",
  "**More battery saved in the background, if you choose**: under Settings → Notifications → In the background, Only the waste stays the default; And nearby phones also turns off the radios for phones nearby while Erevos is in the background; And sleep also lets the phone sleep, so Erevos looks at your relay about once a minute and a message or a call can be a minute or two late. Android only. See [Chat through a relay](#relay).":
    "**Plus de batterie économisée en arrière-plan, si tu le choisis** : dans Réglages → Notifications → En arrière-plan, Seulement le gaspillage reste le choix par défaut ; Et les téléphones proches éteint aussi les radios pour téléphones proches tant qu’Erevos est en arrière-plan ; Et le sommeil laisse aussi dormir le téléphone, si bien qu’Erevos regarde ton relais environ une fois par minute et qu’un message ou un appel peut avoir une ou deux minutes de retard. Android seulement. Voir [Discuter par un relais](#relay).",
  "**A contact you delete no longer comes back from an old ask**: in a group, a member you asked for their contact link, or who asked for yours, and whom you then deleted as a contact before Erevos looked at the relay again, could be added again by that old ask. Deleting them now lets go of it at once. See [Group chats](#groups).":
    "**Un contact supprimé ne revient plus d’une ancienne demande** : dans un groupe, un membre dont tu avais demandé le lien de contact, ou qui avait demandé le tien, et que tu supprimais ensuite comme contact avant qu’Erevos regarde de nouveau le relais, pouvait être ajouté de nouveau par cette ancienne demande. La suppression la lâche maintenant aussitôt. Voir [Discussions de groupe](#groups).",
  "**Every message says which way it went**: hold a message and its menu says whether it went or came through the relay, through Nostr, to a phone nearby or over LoRa. Messages from before say nothing. See [Through Nostr](#nostr).":
    "**Chaque message dit par où il est passé** : appuie longuement sur un message et son menu dit s’il est parti ou arrivé par le relais, par Nostr, par un téléphone proche ou par LoRa. Les messages d’avant ne disent rien. Voir [Par Nostr](#nostr).",
  "**The spam filter reads words as they look**: a scam text that swaps a letter for a look-alike of another alphabet, or hides a mark that shows nothing inside a word, no longer gets past it. See [SMS](#sms).":
    "**Le filtre de spam lit les mots comme ils se voient** : un SMS d’arnaque qui remplace une lettre par une autre, semblable, d’un autre alphabet, ou cache dans un mot une marque qu’on ne voit pas, ne le trompe plus. Voir [SMS](#sms).",
  "**Media, links and files in groups too**: in a group's details, a list of its photos, videos, voice messages, music, files and links, each kind apart under its months, with a calendar, as in a contact's chat. A tap opens or plays; held, each goes to its message. See [Group chats](#groups).":
    "**Médias, liens et fichiers aussi dans les groupes** : dans les détails d’un groupe, une liste de ses photos, vidéos, messages vocaux, musiques, fichiers et liens, chaque sorte à part sous ses mois, avec un calendrier, comme dans la discussion d’un contact. Un appui ouvre ou lit ; maintenu, chacun mène à son message. Voir [Discussions de groupe](#groups).",
  "**A relay restart no longer brings a false notice**: after your relay restarted, a hidden chat or a closed space said New message once more for messages it had told of already. Your relay needs an update for it. See [Hidden chats](#hidden).":
    "**Un redémarrage du relais n’apporte plus de fausse notification** : après le redémarrage de ton relais, une discussion masquée ou un espace fermé disait de nouveau Nouveau message pour des messages qu’il avait déjà signalés. Ton relais doit être mis à jour pour cela. Voir [Discussions masquées](#hidden).",
  "**Backups to your server through Tor**: on Android, automatic backups sent to your own server now follow the space's choice under Settings → Relay and networks → Tor, as Matrix does, so with Tor the server no longer sees where you are. To a server too says when they go through Tor. See [Backups](#backup).":
    "**Des sauvegardes vers ton serveur par Tor** : sur Android, les sauvegardes automatiques envoyées à ton propre serveur suivent maintenant le choix de l’espace sous Réglages → Relais et réseaux → Tor, comme Matrix, donc avec Tor le serveur ne voit plus où tu es. Aussi vers un serveur dit quand elles passent par Tor. Voir [Sauvegardes](#backup).",
  "**Restore a backup straight from your server**: Restore from a server, under Backups, lists the backups on your server, newest first, and opens the one you choose with its password, with no download by hand, on a new phone too. See [Backups](#backup).":
    "**Restaurer une sauvegarde directement depuis ton serveur** : Restaurer depuis un serveur, dans Sauvegardes, montre les sauvegardes de ton serveur, les plus récentes d’abord, et ouvre celle que tu choisis avec son mot de passe, sans téléchargement à la main, sur un nouveau téléphone aussi. Voir [Sauvegardes](#backup).",
  "**Backups to your server from a computer and the web app too**: in the desktop app, automatic backups go to your WebDAV server as on Android; in the web app, Send a backup now sends one there, with a server that lets the web app in. Both can restore from it. Not through Tor. See [Backups](#backup).":
    "**Des sauvegardes vers ton serveur depuis un ordinateur et l’app web aussi** : dans l’app de bureau, les sauvegardes automatiques vont vers ton serveur WebDAV comme sur Android ; dans l’app web, Envoyer une sauvegarde maintenant en envoie une là-bas, avec un serveur qui laisse entrer l’app web. Les deux peuvent restaurer depuis lui. Pas par Tor. Voir [Sauvegardes](#backup).",
  "**Check a contact in person with QR codes**: under Safety number in a chat's details, each phone shows a code; take a photo of the code on the other phone, and they of yours. When it matches, the contact is marked Checked in person. Nothing is sent. See [Chat through a relay](#relay).": "**Vérifier un contact en personne avec des codes QR** : sous Numéro de sécurité, dans les détails d’une discussion, chaque téléphone montre un code ; photographiez le code de l’autre téléphone, et lui le vôtre. Quand ça correspond, le contact est marqué Vérifié en personne. Rien n’est envoyé. Voir [Discuter par un relais](#relay).",
  "**Up to three home relays**: under Settings → Relay and networks → Home relay, Add another home relay gives a space up to two more, each with a queue of its own. Your contact link and your messages name them in order, and contacts try each while the ones before cannot be reached. See [Home relay](#home-relay).": "**Jusqu’à trois relais d’attache** : sous Réglages → Relais et réseaux → Relais d’attache, Ajouter un autre relais d’attache donne à un espace jusqu’à deux de plus, chacun avec sa propre file. Votre lien de contact et vos messages les nomment dans l’ordre, et vos contacts essaient chacun tant que les précédents sont injoignables. Voir [Relais d’attache](#home-relay).",
  "**Introduce two of your contacts**: in a contact's chat details, Introduce to a contact asks them and another contact of yours, each in your chat with them. Only if both say yes do they become contacts, and neither learns whether the other said no. See [Chat through a relay](#relay).": "**Présentez deux de vos contacts** : dans les détails de la discussion d’un contact, Présenter à un contact le sollicite, ainsi qu’un autre de vos contacts, chacun dans votre discussion avec lui. Ils ne deviennent contacts que si les deux disent oui, et aucun ne sait si l’autre a dit non. Voir [Discuter par un relais](#relay).",
  "**Bluetooth that cannot be followed**: the random number your phone sends out over Bluetooth for phones nearby to find it changed only when Erevos started again; it now changes every nine to twelve minutes, so someone listening cannot follow your phone from place to place by it. Older Erevos phones still find yours. See [Chat with a nearby phone](#nearby).": "**Un Bluetooth qu’on ne peut pas suivre** : le nombre aléatoire que votre téléphone émet en Bluetooth pour que les téléphones proches le trouvent ne changeait qu’au redémarrage d’Erevos ; il change maintenant toutes les neuf à douze minutes, si bien que personne à l’écoute ne peut suivre votre téléphone d’un endroit à l’autre grâce à lui. Les téléphones avec un Erevos plus ancien trouvent toujours le vôtre. Voir [Discuter avec un téléphone à proximité](#nearby).",
  "**Hidden chats show at once**: as the PIN opens them, their chats and contacts show at once, to read, while what they were receiving in the background ends; before, that could hold them back a long while, as it may go through Tor. See [Hidden chats](#hidden).": "**Les discussions masquées s’affichent aussitôt** : dès que le code PIN les ouvre, leurs discussions et leurs contacts s’affichent aussitôt, pour les lire, pendant que prend fin ce qu’elles recevaient en arrière-plan ; avant, cela pouvait les retenir longtemps, car cette réception peut passer par Tor. Voir [Discussions masquées](#hidden).",
  "**Your backup password in pieces with friends**: under Settings → Data and devices → Backup pieces, give pieces of it to 3 to 5 contacts; any 2 or 3 of them give it back, one alone shows nothing. Each goes inside the encryption of your chat with them and only their Erevos keeps it; your phone keeps none. See [Backup pieces with friends](#backup-pieces).": "**Le mot de passe de vos sauvegardes en morceaux chez des amis** : dans Réglages → Données et appareils → Morceaux de sauvegarde, donnez-en des morceaux à 3 à 5 contacts ; 2 ou 3 d’entre eux, n’importe lesquels, le redonnent, un seul ne montre rien. Chacun passe dans le chiffrement de votre conversation avec eux et seul leur Erevos le garde ; votre téléphone n’en garde aucun. Voir [Morceaux de sauvegarde chez des amis](#backup-pieces).",
  "**Panic button**: under Settings → Privacy and security → Panic button, wipe everything Erevos keeps here with one tap, on Android and in the web app. On Android, a panic app such as Ripple can do it too, but only the one you say yes to, checked by its signature. See [Panic button](#panic).": "**Bouton de panique** : dans Réglages → Confidentialité et sécurité → Bouton de panique, effacez d’un toucher tout ce qu’Erevos garde ici, sur Android et dans l’app web. Sur Android, une app de panique comme Ripple peut aussi le faire, mais seulement celle à laquelle vous dites oui, vérifiée par sa signature. Voir [Bouton de panique](#panic).",
  "**Erevos to a phone nearby, with no internet**: under Settings → General → Give Erevos to a phone nearby, this phone serves its Erevos over the same Wi-Fi or its hotspot for ten minutes, with a QR code. A phone without Erevos downloads it in the browser; one with an older Erevos takes it under Updates → From a phone nearby, which installs it only when it is Erevos, signed as that one is. See [Erevos to a phone nearby](#give-app).": "**Erevos vers un téléphone proche, sans internet** : dans Réglages → Général → Donner Erevos à un téléphone proche, ce téléphone sert son Erevos sur le même Wi-Fi ou son point d’accès pendant dix minutes, avec un code QR. Un téléphone sans Erevos le télécharge dans le navigateur ; un téléphone avec un Erevos plus ancien le prend dans Mises à jour → Depuis un téléphone proche, qui ne l’installe que si c’est Erevos, signé comme celui-là. Voir [Erevos vers un téléphone proche](#give-app).",
  "**Hidden chats with phones nearby**: while hidden chats are open, or receive while closed, they reach a contact's phone nearby over Bluetooth, Wi-Fi Aware, Wi-Fi Direct or the same Wi-Fi, with no internet, as your other chats do. The space never learns that a hidden contact is near, and nothing on the air tells their messages from the space's; other phones never carry them, and they never go over LoRa or by SMS. See [Hidden chats](#hidden).":
    "**Discussions masquées avec les téléphones à proximité**: tant que les discussions masquées sont ouvertes, ou reçoivent fermées, elles atteignent le téléphone d’un contact à proximité par Bluetooth, Wi-Fi Aware, Wi-Fi Direct ou sur le même Wi-Fi, sans internet, comme vos autres discussions. L’espace n’apprend jamais qu’un contact masqué est à proximité, et rien dans l’air ne distingue leurs messages de ceux de l’espace ; d’autres téléphones ne les portent jamais, et elles ne passent jamais par LoRa ni par SMS. Voir [Discussions masquées](#hidden).",
  "**The same Wi-Fi on Sailfish OS**: Erevos on Sailfish OS finds Erevos phones and computers on the same Wi-Fi or a phone's hotspot and talks with them with no internet, as on a computer. See [On Sailfish OS](#sailfish).":
    "**Le même Wi-Fi sur Sailfish OS**: Erevos sur Sailfish OS trouve les téléphones et ordinateurs avec Erevos sur le même Wi-Fi ou le partage de connexion d’un téléphone et leur parle sans internet, comme sur un ordinateur. Voir [Sur Sailfish OS](#sailfish).",
  "**Downloads stop at 100 MB**: a file, a backup from a server or any other download is read as it comes and stopped as soon as it passes 100 MB, or less where the network's files are smaller, such as 20 MB for Nostr files, so a file server a contact names can no longer fill the phone's memory with an answer without end. A backup on a server comes back up to 100 MB; download a larger one and open it with Restore a backup. See [Backups](#backup).":
    "**Les téléchargements s’arrêtent à 100 Mo** : un fichier, une sauvegarde depuis un serveur ou tout autre téléchargement est lu à mesure qu’il arrive et arrêté dès qu’il dépasse 100 Mo, ou moins là où les fichiers du réseau sont plus petits, comme 20 Mo pour les fichiers Nostr, si bien qu’un serveur de fichiers qu’un contact désigne ne peut plus remplir la mémoire du téléphone d’une réponse sans fin. Une sauvegarde sur un serveur revient jusqu’à 100 Mo ; téléchargez-en une plus grande et ouvrez-la avec Restaurer une sauvegarde. Voir [Sauvegardes](#backup).",
  "**Profile pictures on Matrix and XMPP**: contacts and Matrix rooms show their picture in the chat list, and you can set your own on the Matrix and XMPP screens (Choose a photo). Pictures are not encrypted on either network: the server sees them. See [Matrix](#matrix) and [XMPP](#xmpp).":
    "**Photos de profil sur Matrix et XMPP** : les contacts et les salons Matrix montrent leur photo dans la liste des discussions, et tu peux mettre la tienne sur les écrans Matrix et XMPP (Choisir une photo). Les photos ne sont chiffrées sur aucun des deux réseaux : le serveur les voit. Voir [Matrix](#matrix) et [XMPP](#xmpp).",
  "**Run an XMPP group**: a group's admins can set its subject and take people out or bar them, its owner can rename it and make admins, and in a channel the admin sees who is in it and can put them out. See [XMPP](#xmpp).":
    "**Gérer un groupe XMPP** : les admins d’un groupe mettent son sujet et retirent ou bannissent des gens, le propriétaire le renomme et nomme des admins, et dans un canal l’admin voit qui s’y trouve et peut le mettre dehors. Voir [XMPP](#xmpp).",
  "**Check a Matrix device by QR code**: once both sides accept a check, Erevos shows a code for Element (or another Erevos) to photograph, or photographs theirs, as Element does; comparing emoji stays one tap away. See [Matrix](#matrix).":
    "**Vérifier un appareil Matrix par QR code** : une fois la vérification acceptée des deux côtés, Erevos montre un code qu’Element (ou un autre Erevos) photographie, ou photographie le leur, comme Element ; comparer des emoji reste à un toucher. Voir [Matrix](#matrix).",
  "**Sign in to Matrix with single sign-on** (Android): when your Matrix server signs people in on its own page, as matrix.org does, Sign in with single sign-on opens it in the browser and comes back to Erevos. See [Matrix](#matrix).":
    "**Se connecter à Matrix par authentification unique** (Android) : quand ton serveur Matrix connecte les gens sur sa propre page, comme matrix.org, « Se connecter par authentification unique (SSO) » l’ouvre dans le navigateur et revient à Erevos. Voir [Matrix](#matrix).",
  "**A closed space tells of XMPP messages**: on Android, Say a message came under While this space is closed, on the XMPP screen, has a closed space say \"New message\" when something comes on XMPP while another space is open, never what, from whom or in which chat. Off until you choose it. It needs a relay updated for it and an XMPP server that sends notices to apps that are away; the XMPP server then learns the relay's name, and the relay when messages come. See [XMPP](#xmpp).":
    "**Un espace fermé signale les messages XMPP** : sur Android, « Signaler les nouveaux messages » sous « Tant que cet espace est fermé », sur l’écran XMPP, laisse un espace fermé dire « New message » quand quelque chose arrive sur XMPP pendant qu’un autre espace est ouvert, jamais quoi, de qui ni dans quelle discussion. Désactivé tant que vous ne le choisissez pas. Il faut un relais mis à jour pour cela et un serveur XMPP qui envoie des notifications aux applis inactives ; le serveur XMPP apprend alors le nom du relais, et le relais quand des messages arrivent. Voir [XMPP](#xmpp).",
  "**Linking a computer is clearer**: on a computer, Settings → Data and devices → Linked devices now starts with Link to my phone, with LPHL's relay filled in and Sign in with LPHL under the token, so no token has to be copied from the phone; and it says that the QR code shows once Link to my phone is tapped. See [Linked devices](#devices).":
    "**Associer un ordinateur est plus clair** : sur un ordinateur, Réglages → Données et appareils → Appareils associés commence désormais par « Associer à mon téléphone », avec le relais de LPHL déjà rempli et « Se connecter avec LPHL » sous le jeton, si bien qu’aucun jeton n’a à être copié depuis le téléphone ; et il dit que le code QR s’affiche dès qu’on touche « Associer à mon téléphone ». Voir [Appareils associés](#devices).",
  "**Delete me from everywhere**: Settings → Privacy and security → Delete me from everywhere deletes what the servers keep for the open space (its queues on the relays with the messages in them, what a relay holds for you to send later, files waiting there, invites nobody used), asks the Nostr relays through Tor to forget the keys your chats read on, and stops the space until you tap Start again. Your phone keeps everything. You can also sign out of Matrix and XMPP and delete the Nostr account made here. See [Delete me from everywhere](#forget).": "**Me supprimer partout** : Réglages → Confidentialité et sécurité → Me supprimer partout supprime ce que les serveurs gardent pour l'espace ouvert (ses files sur les relais avec les messages dedans, ce qu'un relais garde pour l'envoyer plus tard, les fichiers qui y attendent, les invitations que personne n'a utilisées), demande via Tor aux relais Nostr d'oublier les clés sur lesquelles vos conversations lisent, et arrête l'espace jusqu'à ce que vous touchiez Relancer. Votre téléphone garde tout. Vous pouvez aussi vous déconnecter de Matrix et XMPP et supprimer le compte Nostr créé ici. Voir [Me supprimer partout](#forget).",
  "**Every relay queue on one list**: the queues a space keeps on the relays are gathered in one place, and the checks fail if a new kind of queue is made without being added there, so Delete me from everywhere cannot leave one behind.": "**Toutes les files de relais sur une liste** : les files qu'un espace garde sur les relais sont réunies à un seul endroit, et les vérifications échouent si un nouveau type de file est créé sans y être ajouté, pour que Me supprimer partout n'en laisse aucune.",
  "**Matrix, XMPP and Nostr on a linked computer**: linking a computer can bring this space's Matrix and XMPP accounts and the key of its Nostr chats over too, each signed in there as a new device of its own; for a computer linked already, tap Send the accounts under it on the phone. A Matrix server seldom lets the phone sign the computer in: the computer then asks for the Matrix password once, and the account's keys come from the phone, so no Security Key or check by emoji is needed. See [Linked devices](#devices).":
    "**Matrix, XMPP et Nostr sur un ordinateur associé** : associer un ordinateur peut aussi y amener les comptes Matrix et XMPP de cet espace et la clé de ses discussions Nostr, chacun connecté là-bas comme un nouvel appareil à lui ; pour un ordinateur déjà associé, touche « Envoyer les comptes » sous lui, sur le téléphone. Un serveur Matrix laisse rarement le téléphone connecter l’ordinateur : l’ordinateur demande alors une fois le mot de passe Matrix, et les clés du compte viennent du téléphone, donc ni clé de sécurité ni vérification par emoji ne sont nécessaires. Voir [Appareils associés](#devices).",
  "**Only the SMS**: with Erevos locked, the SMS icon, the widget's SMS button and the notice of a new SMS ask for the password, then open only the SMS. Anything else, and the orange padlock **Unlock everything**, asks for it again, then opens all of Erevos. See [Password lock](#lock).":
    "**Seulement les SMS** : quand Erevos est verrouillé, l’icône SMS, le bouton SMS du widget et la notification d’un nouveau SMS demandent le mot de passe, puis n’ouvrent que les SMS. Tout le reste, y compris le cadenas orange **Tout déverrouiller**, le redemande, puis ouvre tout Erevos. Voir [Verrou par mot de passe](#lock).",
  "**Nostr chats with a key brought from another app get their messages again**: Erevos reads where that app said your messages arrive, as that app does, instead of its own three relays, fetches the messages kept there and in older lists of the key, and reads a relay again when it stops sending. Before, such a key could show its chats with no past messages and get no new ones. See [Chats with other Nostr apps](#nostr-chats).":
    "**Les discussions Nostr avec une clé venue d’une autre appli retrouvent leurs messages** : Erevos lit là où cette appli a dit que tes messages arrivent, comme le fait cette appli, au lieu de ses trois relais propres, récupère les messages gardés là et dans les anciennes listes de la clé, et relit un relais quand il cesse d’envoyer. Avant, une telle clé pouvait montrer ses discussions sans messages passés et n’en recevoir aucun de nouveau. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Backups keep what closed chats need**: a backup now also holds what lets hidden chats ring a call and say a message came while they are closed, and a closed space say one came. So after a restore, on another phone too, **Ring calls when closed**, **Say when a message comes** and **Also while another space is open** go on as they were. See [Backups](#backup).":
    "**Les sauvegardes gardent ce dont les discussions fermées ont besoin** : une sauvegarde garde maintenant aussi ce qui permet aux discussions masquées de faire sonner un appel et de prévenir qu’un message est arrivé pendant qu’elles sont fermées, et à un espace fermé de prévenir qu’un message est arrivé. Ainsi, après une restauration, sur un autre téléphone aussi, **Faire sonner les appels quand elles sont fermées**, **Prévenir quand un message arrive** et **Aussi quand un autre espace est ouvert** continuent comme avant. Voir [Sauvegardes](#backup).",
  "**Open another space from the search**: type another space's password in **Search chats** on the home screen and press Enter: the open space closes, nothing of it stays, and the other opens, as with **Lock now** and its password. It takes as long whatever is typed, and a wrong password, or the open space's own, is just a search. See [Second password](#second).":
    "**Ouvrir un autre espace depuis la recherche** : tape le mot de passe d’un autre espace dans **Rechercher dans les discussions** de l’écran d’accueil et appuie sur Entrée : l’espace ouvert se ferme, sans que rien n’en reste, et l’autre s’ouvre, comme avec **Verrouiller maintenant** et son mot de passe. Cela prend le même temps quoi que tu tapes, et un mauvais mot de passe, ou celui de l’espace ouvert, n’est qu’une recherche. Voir [Second mot de passe](#second).",
  "**A dot for unread messages elsewhere, if you want it**: hidden chats with **Receive while closed** can show a small dot on the magnifier of **Search chats** while they have a message unread (their switch **Dot for unread messages**), and a space set to say a message came while another is open can show one on the padlock at the top of the other spaces' chats (**Dot in the other spaces**). Never how many, nor where; off unless you turn it on. See [Hidden chats](#hidden).":
    "**Un point pour les non-lus ailleurs, si tu le veux** : les discussions masquées avec **Recevoir une fois fermées** peuvent afficher un petit point sur la loupe de **Rechercher dans les discussions** tant qu’elles ont un message non lu (leur interrupteur **Point pour les non-lus**), et un espace qui signale qu’un message est arrivé pendant qu’un autre est ouvert peut en afficher un sur le cadenas au-dessus des discussions des autres espaces (**Point dans les autres espaces**). Jamais combien, ni où ; éteint sauf si tu l’allumes. Voir [Discussions masquées](#hidden).",
  "**Joining takes only the invite**: on a phone with no relay yet, **New chat** shows one way in, **I have an invite**. Signing in with LPHL, **Start without a relay** and the relay's settings are under **For advanced users**, for whoever looks for them. And an invite to your relay gives the relay only a name of random letters and digits for the phone it lets in: the name you type stays on your phone, where your list of invites shows it. See [Chat through a relay](#relay).":
    "**Pour entrer, l’invitation suffit** : sur un téléphone qui n’a pas encore de relais, **Nouvelle discussion** affiche une façon d’entrer, **J’ai une invitation**. La connexion avec LPHL, **Commencer sans relais** et les réglages du relais sont dans **Pour les utilisateurs avancés**, pour qui les cherche. Et une invitation à ton relais ne donne au relais qu’un nom de lettres et de chiffres au hasard pour le téléphone qu’elle laisse entrer : le nom que tu tapes reste sur ton téléphone, où ta liste d’invitations le montre. Voir [Discuter par un relais](#relay).",
  "**Invited phones stay**: on a relay of this version, a phone you invited keeps its access even once yours goes, and so do the phones it invited; taking back an invite cuts off that one phone alone. See [Chat through a relay](#relay).":
    "**Les téléphones invités restent** : sur un relais de cette version, un téléphone que tu as invité garde son accès même quand le tien disparaît, et de même les téléphones qu’il a invités ; reprendre une invitation coupe ce seul téléphone. Voir [Discuter par un relais](#relay).",
  "**Backups bring the phone back as it was**: a backup now holds the photos, files and voice messages too, in files of their own beside it, each sealed and bound to its backup; and the panic password, the settings that go with you, the Phone's quick replies and the calls it turns away, the SMS for later and automatic backups with their server, but not their folder. An SMS for later whose time passed before the restore waits for you to send it or delete it. What stays with each phone, as the fingerprint, the folders and what Android allows, never comes back: after a restore, Android's permissions open for the modules that are on. See [Backups](#backup).":
    "**Les sauvegardes ramènent le téléphone tel qu’il était** : une sauvegarde contient maintenant aussi les photos, les fichiers et les messages vocaux, dans des fichiers à part à côté d’elle, chacun scellé et lié à sa sauvegarde ; et le mot de passe de panique, les réglages qui te suivent, les réponses rapides du Téléphone et les appels qu’il refuse, les SMS pour plus tard et les sauvegardes automatiques avec leur serveur, mais pas leur dossier. Un SMS pour plus tard dont l’heure est passée avant la restauration attend que tu l’envoies ou le supprimes. Ce qui reste propre à chaque téléphone, comme l’empreinte, les dossiers et ce qu’Android permet, ne revient jamais : après une restauration, les autorisations d’Android s’ouvrent pour les modules activés. Voir [Sauvegardes](#backup).",
  "**A newer backup asks for a newer Erevos**: a backup made by a newer Erevos than yours is refused, with nothing changed, and Erevos asks you to update to the latest version first. An Erevos from before 6.0.0 does not open backups from 6.0.0 on: update it, then restore. See [Backups](#backup).":
    "**Une sauvegarde plus récente demande un Erevos plus récent** : une sauvegarde faite par un Erevos plus récent que le tien est refusée, sans rien changer, et Erevos te demande de le mettre d’abord à jour vers la dernière version. Un Erevos d’avant la 6.0.0 n’ouvre pas les sauvegardes de la 6.0.0 ou plus récentes : mets-le à jour, puis restaure. Voir [Sauvegardes](#backup).",
  "**Shared into the Collection with no plain copy**: a photo or file another app shares with Erevos is encrypted as it comes in, before **Send to** opens, so on its way into the Collection it never lies unencrypted on the phone. It can be up to 4 GB there, and a large one shows how far it is encrypted, with **Cancel**; a chat still takes 100 MB at most. See [Collection](#collection).": "**Partager dans la Collection sans copie en clair** : une photo ou un fichier qu'une autre app partage avec Erevos est chiffré dès son arrivée, avant que **Envoyer à** s'ouvre, et ne se trouve donc jamais non chiffré sur le téléphone en chemin vers la Collection. Là, il peut faire jusqu’à 4 Go ; une discussion prend toujours 100 Mo au plus. Pour un gros fichier, on voit où en est le chiffrement, avec **Annuler**. Voir [Collection](#collection).",
  "**See a file come from the WebDAV server**: a file of the Collection that is not on this device, as after a backup restored on a new phone, shows how much of it has come from the server, and **Cancel** stops it; what came stays, and the next time only the rest comes. Music, videos, PDFs and **Open with another app** fetch it first too, instead of failing. See [Collection](#collection).": "**Voir un fichier arriver du serveur WebDAV** : un fichier de la Collection qui n'est pas sur cet appareil, comme après une sauvegarde restaurée sur un nouveau téléphone, montre combien en est déjà arrivé du serveur, et **Annuler** l'arrête ; ce qui est arrivé reste, et la fois suivante seul le reste vient. La musique, les vidéos, les PDF et **Ouvrir avec une autre app** le récupèrent aussi d'abord, au lieu d'échouer. Voir [Collection](#collection).",
  "**Backups skip what is on the WebDAV server after a restart too**: that a Collection's copies on its server are complete is kept with it, so a backup made after Erevos starts again still leaves its pieces out, as long as no file was added or deleted since. **The connection works.** now shows in the colour of success, not of a warning. See [Collection](#collection).": "**Les sauvegardes laissent de côté ce qui est sur le serveur WebDAV, même après un redémarrage** : le fait que les copies d'une Collection sur son serveur sont complètes est gardé avec elle, si bien qu'une sauvegarde faite après le redémarrage d'Erevos laisse encore ses morceaux de côté, tant qu'aucun fichier n'a été ajouté ni supprimé depuis. **La connexion fonctionne.** s'affiche désormais dans la couleur du succès, pas d'un avertissement. Voir [Collection](#collection).",
  "**Notes from another app**: an app on the phone, as Fasouli for a payment that is coming, can ask to keep a note with its reminder in Chat with myself. Erevos asks you first, in the space you open. See [Getting started](#start).":
    "**Notes depuis une autre appli** : une appli du téléphone, comme Fasouli pour un paiement à venir, peut demander de garder une note avec son rappel dans Discussion avec moi-même. Erevos te demande d’abord, dans l’espace que tu ouvres. Voir [Premiers pas](#start).",
  "**Payment requests**: another app, as Fasouli, can ask Erevos to send one to a contact: an amount and what it is for, as a card. They tap **Paid** once they paid, and **Mark in Fasouli** then marks it collected there. Erevos moves no money. See [Chat through a relay](#relay).":
    "**Demandes de paiement** : une autre appli, comme Fasouli, peut demander à Erevos d’en envoyer une à un contact : un montant et pour quoi, en carte. Le contact touche **Payé** une fois payé, et **Noter dans Fasouli** la marque encaissée là-bas. Erevos ne déplace pas d’argent. Voir [Discuter par un relais](#relay).",
  "**Panic tells Fasouli too**: on Android, under Settings → Privacy and security → Panic button → **Tell other apps**, choose the apps Erevos tells as it wipes, as a panic app does: Fasouli then locks itself. Each asks you first. See [Panic button](#panic).":
    "**La panique prévient aussi Fasouli** : sur Android, dans Réglages → Confidentialité et sécurité → Bouton de panique → **Prévenir d’autres applis**, choisis les applis qu’Erevos prévient quand il efface, comme une appli de panique : Fasouli se verrouille alors. Chacune te demande d’abord. Voir [Bouton de panique](#panic).",
  "**The Collection in the browser and on Sailfish OS**: the web app, on an iPhone's home screen too, and Erevos on Sailfish OS have the Collection now. A file is encrypted a piece at a time as it is read, and if the browser runs out of room nothing of it is kept. Photos, text, music and videos up to 256 MB open in memory only; a PDF is saved to be read elsewhere. See [Collection](#collection).":
    "**La Collection dans le navigateur et sur Sailfish OS** : l’app web, sur l’écran d’accueil d’un iPhone aussi, et Erevos sur Sailfish OS ont maintenant la Collection. Un fichier est chiffré morceau par morceau pendant sa lecture, et si le navigateur manque de place, rien n’en est gardé. Photos, textes, musique et vidéos jusqu’à 256 Mo s’ouvrent seulement en mémoire ; un PDF s’enregistre pour être lu ailleurs. Voir [Collection](#collection).",
  "**Large files saved from the Collection on Sailfish OS**: **Save to phone** writes a file of any size to Downloads a piece at a time, as the desktop app now does too, and when the disk has no room left Erevos says so and leaves nothing half-written. See [Collection](#collection).":
    "**De gros fichiers enregistrés depuis la Collection sur Sailfish OS** : **Enregistrer sur le téléphone** écrit dans Téléchargements un fichier de toute taille morceau par morceau, comme le fait maintenant aussi l’app de bureau, et quand le disque n’a plus de place, Erevos le dit et ne laisse rien d’écrit à moitié. Voir [Collection](#collection).",
  "**Sign in with Nextcloud**: a Collection's server and the backups' server can now be your Nextcloud, as LPHL's, the one Fasouli syncs with, without typing a password: tap **Sign in with Nextcloud**, sign in in the browser and grant access. Erevos gets an app password of its own and its own folder there, Erevos/Collection or Erevos/Backups. See [Collection](#collection).":
    "**Se connecter avec Nextcloud** : le serveur d’une Collection et celui des sauvegardes peuvent maintenant être ton Nextcloud, comme celui de LPHL, celui avec lequel Fasouli se synchronise, sans taper de mot de passe : touche **Se connecter avec Nextcloud**, connecte-toi dans le navigateur et accorde l’accès. Erevos reçoit son propre mot de passe d’application et son propre dossier là-bas, Erevos/Collection ou Erevos/Backups. Voir [Collection](#collection).",
  "**Web app and Sailfish OS fixes from the review**: in the web app, each space that turns notifications on gets a push address of its own, from a service worker of its own, so a relay is never given another space's address and it never ties two spaces together; the browser's settings then list one service worker for each such space. A check for a new release that was slow to answer no longer brings back the release just replaced. On Sailfish OS, another app on the phone can no longer make Erevos hold on to memory, nor give orders to the helper that waits at the relay while Erevos is out of sight. See [On an iPhone](#iphone).":
    "**Corrections de la revue dans l’app web et sur Sailfish OS** : dans l’app web, chaque espace qui active les notifications reçoit sa propre adresse push, de son propre service worker, donc un relais ne reçoit jamais l’adresse d’un autre espace et elle ne relie jamais deux espaces ; les réglages du navigateur listent alors un service worker par espace de ce genre. Une recherche de nouvelle version lente à répondre ne ramène plus la version tout juste remplacée. Sur Sailfish OS, une autre app du téléphone ne peut plus faire garder de la mémoire à Erevos, ni donner d’ordres à l’assistant qui attend au relais tant qu’Erevos n’est pas à l’écran. Voir [Sur un iPhone](#iphone).",
  "**Photos of the Collection one after the other**: in a photo, the arrows (on a phone too, while the bars show) or a swipe go to the next or the one before, and **Slideshow** shows them by themselves, one every 4 seconds, till a tap. On a computer, in a browser and on Sailfish OS a photo opens again instead of staying at **Opening the photo…**. See [Collection](#collection).": "**Les photos de la Collection l’une après l’autre** : dans une photo, les flèches (sur le téléphone aussi, tant que les barres sont visibles) ou un glissement mènent à la suivante ou à la précédente, et **Diaporama** les montre toutes seules, une toutes les 4 secondes, jusqu’à un toucher. Sur l’ordinateur, dans un navigateur et sur Sailfish OS, une photo s’ouvre de nouveau au lieu de rester sur **Ouverture de la photo…**. Voir [Collection](#collection).",
  "**Reminders that come again**: a note Fasouli keeps for a scheduled payment now reminds you each time it is due, every month or as the payment repeats, and shows how often. Once you see it, it moves to its next time. See [Getting started](#start).":
    "**Des rappels qui reviennent** : une note que Fasouli garde pour un paiement planifié te le rappelle maintenant à chaque échéance, chaque mois ou selon la répétition du paiement, et indique à quelle fréquence. Dès que tu l’as vue, elle passe à sa prochaine fois. Voir [Getting started](#start).",
  "**Who is online on Matrix and XMPP**: under a contact's name it says, as their server does, **Online**, **Away** or **Do not disturb**, with the words they set, or when they were last online, and their picture in the chat list has a green dot. On Matrix, Erevos no longer says you are online unless you turn on **Say when I am online** on the Matrix screen. See [Matrix](#matrix).":
    "**Qui est en ligne sur Matrix et XMPP** : sous le nom d’un contact s’affiche, comme le dit son serveur, **En ligne**, **Absent** ou **Ne pas déranger**, avec les mots qu’il a mis, ou quand il était en ligne pour la dernière fois, et sa photo dans la liste des discussions a un point vert. Sur Matrix, Erevos ne dit plus que tu es en ligne, sauf si tu actives **Dire quand je suis en ligne** sur l’écran Matrix. Voir [Matrix](#matrix).",
  "**Link a computer with one tap**: on the computer, **Linked devices** now shows a small code at once. Scan it with the phone and tap **Link**: the phone gives the computer what it needs through Nostr, end-to-end encrypted, and nothing has to be typed or compared. If Nostr cannot be reached, **Link another way** keeps the old way. See [Linked devices](#devices).":
    "**Associer un ordinateur d’un seul appui** : sur l’ordinateur, **Appareils associés** affiche désormais aussitôt un petit code. Scanne-le avec le téléphone et appuie sur **Associer** : le téléphone donne à l’ordinateur ce qu’il lui faut via Nostr, chiffré de bout en bout, et il n’y a rien à saisir ni à comparer. Si Nostr est injoignable, **Associer autrement** garde l’ancienne façon. Voir [Appareils associés](#devices).",
  '**Choose the name others see**: under Settings → Privacy and security → **My name**, give this space a name that your contacts and your private groups see instead of a code, always encrypted. Hidden chats have a name of their own, in their settings, empty at first. See [Chat through a relay](#relay).':
    '**Choisissez le nom que les autres voient** : dans Réglages → Confidentialité et sécurité → **Mon nom**, donnez à cet espace un nom que vos contacts et vos groupes privés voient à la place d’un code, toujours chiffré. Les discussions masquées ont un nom à elles, dans leurs réglages, vide au début. Voir [Discuter par un relais](#relay).',
  "**Folders in Chat with myself**: notes, photos, files and voice messages can now go in folders. The folder button at the top makes one; its tab above the notes then shows only what is in it, and what you write while it is chosen goes into it. Holding a note offers **Move to a folder**; holding a folder's tab renames or deletes it, its notes staying. The folders go to your linked devices with the notes. See [Getting started](#start).":
    "**Des dossiers dans Discussion avec moi-même** : les notes, photos, fichiers et messages vocaux peuvent désormais aller dans des dossiers. Le bouton de dossier en haut en crée un ; son onglet au-dessus des notes n’affiche alors que ce qu’il contient, et ce que vous écrivez pendant qu’il est choisi y va. Un appui long sur une note propose **Déplacer dans un dossier** ; un appui long sur l’onglet d’un dossier le renomme ou le supprime, ses notes restant. Les dossiers vont sur vos appareils associés avec les notes. Voir [Premiers pas](#start).",
  "**The battery mode And sleep spares more**: each time it wakes the phone to look, about once a minute, the phone now sleeps again within a second or two when nothing came, not after 25 seconds.":
    "**Le mode de batterie « Et le sommeil » économise davantage** : chaque fois qu’il réveille le téléphone pour regarder, environ une fois par minute, le téléphone se rendort maintenant en une ou deux secondes quand rien n’est arrivé, et non après 25 secondes.",
  "**Messages come at once while Erevos shows**: Erevos now waits at your relay with the connection open also while it is on the screen, so a message or a call comes the moment it is sent, not at the next look every 3 seconds, and the phone's radio rests in between.":
    "**Les messages arrivent aussitôt pendant qu’Erevos est affiché** : Erevos attend maintenant à ton relais avec la connexion ouverte aussi quand il est à l’écran, si bien qu’un message ou un appel arrive au moment où il est envoyé, et non au prochain regard toutes les 3 secondes, et la radio du téléphone se repose entre-temps.",
  "**A new battery mode, And light sleep**: under Settings → Notifications → In the background. The phone may sleep, and what comes to your relay wakes it, so messages and calls still come at once where the network and Android allow it. It is new: if messages come late with it, choose another.":
    "**Un nouveau mode de batterie, « Et le sommeil léger »** : dans Réglages → Notifications → En arrière-plan. Le téléphone peut dormir, et ce qui arrive à ton relais le réveille, si bien que les messages et les appels arrivent toujours aussitôt là où le réseau et Android le permettent. Il est nouveau : si les messages arrivent en retard avec lui, choisis-en un autre.",
  "**Chats are saved faster**: a message that comes, is read or is deleted is saved by looking only at its own chat, which shows most with many chats or after a large import. The chat screen is no longer drawn again every 5 seconds.":
    "**Les discussions s’enregistrent plus vite** : un message qui arrive, est lu ou est supprimé est enregistré en ne regardant que sa propre discussion, ce qui se voit surtout avec beaucoup de discussions ou après un gros import. L’écran de discussion n’est plus redessiné toutes les 5 secondes.",
  "**Large imports write less**: the note of the files an import is still writing is kept in small parts, not written whole for every file.":
    "**Les gros imports écrivent moins** : la note des fichiers qu’un import est encore en train d’écrire est gardée en petites parties, et non écrite en entier pour chaque fichier.",
  "**A text no longer waits for slow Nostr relays**: with Nostr on, a text waited for a Nostr relay to say it took it, up to 20 seconds when none answered, before it went through the relay. Now, when none says so within 4 seconds, it goes through the relay as well at once.":
    "**Un message n’attend plus les relais Nostr lents** : avec Nostr activé, un message attendait qu’un relais Nostr dise l’avoir pris, jusqu’à 20 secondes quand aucun ne répondait, avant de passer par le relais. Désormais, si aucun ne le dit en 4 secondes, il passe aussitôt aussi par le relais.",
  "**Voice messages in Opus**: on Android 10 and later, in the web app and on a computer, voice messages are recorded as Ogg/Opus, as Telegram and Element send them: as clear as before at half the size, about 240 KB a minute. Every Erevos plays them, Safari on an older iPhone too. See [Chat through a relay](#relay).":
    "**Messages vocaux en Opus** : sur Android 10 et plus récent, dans l’appli web et sur un ordinateur, les messages vocaux sont enregistrés en Ogg/Opus, comme les envoient Telegram et Element : aussi clairs qu’avant pour moitié moins de taille, environ 240 Ko par minute. Tout Erevos les lit, Safari sur un iPhone plus ancien aussi. Voir [Discuter par un relais](#relay).",
  "**Mark all as read**: the ⋮ menu of the chats has it for the part of the list you are on, all messages, SMS, Erevos, Matrix, XMPP or Nostr, and the Matrix, XMPP and Nostr screens have it for their chats. It asks first, then reads each chat as opening it would: those who wrote are told as then. See [Getting started](#start).":
    "**Tout marquer comme lu** : le menu ⋮ des discussions l’a pour la partie de la liste où tu es, tous les messages, SMS, Erevos, Matrix, XMPP ou Nostr, et les écrans Matrix, XMPP et Nostr l’ont pour leurs discussions. Il demande d’abord, puis lit chaque discussion comme l’ouvrir le ferait : ceux qui ont écrit en sont informés comme alors. Voir [Premiers pas](#start).",
  "**Answer with video, or voice only**: an incoming call, Erevos, group, XMPP or Matrix, now offers both. You can add video to an Erevos voice call while it goes on, and Flip on a computer moves to your next camera. See [Chat through a relay](#relay).":
    "**Répondre en vidéo ou en voix seulement** : un appel entrant, Erevos, de groupe, XMPP ou Matrix, propose maintenant les deux. Tu peux ajouter la vidéo à un appel vocal d’Erevos pendant qu’il dure, et Retourner sur un ordinateur passe à ta caméra suivante. Voir [Discuter par un relais](#relay).",
  "**Voice messages, places, contact cards and pins in SMS**: in an SMS conversation, hold the microphone to send a voice message by MMS. **+** also sends where you are, as an SMS with a map link any phone opens, and a contact from your phone as a contact card. Voice messages, contact cards and map links you receive show as such, to play, save or open. Hold a message down to **Pin for me**, kept only on this phone, or **Select** several to copy, forward or delete them together. See [SMS](#sms).":
    "**Messages vocaux, lieux, cartes de contact et épingles dans les SMS** : dans une conversation SMS, maintiens le micro pour envoyer un message vocal par MMS. **+** envoie aussi où tu es, en SMS avec un lien de carte que n’importe quel téléphone ouvre, et un contact de ton téléphone comme carte de contact. Les messages vocaux, cartes de contact et liens de carte que tu reçois s’affichent comme tels, à lire, enregistrer ou ouvrir. Maintiens un message pour **Épingler pour moi**, gardé sur ce téléphone seulement, ou **Sélectionner** plusieurs messages à copier, transférer ou supprimer ensemble. Voir [SMS](#sms).",
  "**More in XMPP chats**: voice messages from other XMPP apps now play in the chat and show how long they are; **Sticker** sends your own photo stickers as photos, encrypted as the chat is; groups show who is **owner** or **admin**, and the owner can set the group's **Description**; **Forward** sends one or several messages to another XMPP chat; tapping a quoted reply goes to the message; **Pin for me** keeps a message at the top on this phone only; and **Select** chooses several messages to copy, forward or delete. See [XMPP](#xmpp).":
    "**Plus dans les discussions XMPP** : les messages vocaux d’autres applis XMPP se lisent maintenant dans la discussion et montrent leur durée ; **Sticker** envoie tes propres stickers faits à partir de photos comme des photos, chiffrées comme la discussion ; les groupes montrent qui est **propriétaire** ou **admin**, et le propriétaire peut fixer la **Description** du groupe ; **Transférer** envoie un ou plusieurs messages dans une autre discussion XMPP ; appuyer sur une réponse citée va au message ; **Épingler pour moi** garde un message en haut sur ce téléphone seulement ; et **Sélectionner** choisit plusieurs messages à copier, transférer ou supprimer. Voir [XMPP](#xmpp).",
  "**More in Nostr chats**: tap a reaction to add it or take yours back, pin messages for yourself, select several to copy, forward or delete, send your own photo stickers, and see, vote on and make polls in the Public feed. See [Chats with other Nostr apps](#nostr-chats).":
    "**Plus dans les discussions Nostr** : appuie sur une réaction pour l’ajouter ou retirer la tienne, épingle des messages pour toi, choisis-en plusieurs à copier, transférer ou supprimer, envoie tes propres stickers faits à partir de photos, et vois, vote et crée des sondages dans le fil public. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Matrix groups and stickers**: in a Matrix group, **Members** shows who is in it and who is an admin or moderator, and lets admins rename it, set its subject, make admins, and take people out or bar them. Stickers sent from Element and other Matrix apps now show, and your own stickers made from photos can be sent. **New chat** can find people by name, and **Select** in a message's menu chooses several messages to copy, forward or delete. See [Matrix](#matrix).":
    "**Groupes et stickers sur Matrix** : dans un groupe Matrix, **Membres** montre qui en fait partie et qui est admin ou modérateur, et laisse les admins le renommer, fixer son sujet, nommer des admins, et retirer ou bannir des gens. Les stickers envoyés depuis Element et d’autres applis Matrix s’affichent maintenant, et tes propres stickers faits à partir de photos peuvent être envoyés. **Nouvelle discussion** peut trouver des gens par leur nom, et **Sélectionner** dans le menu d’un message choisit plusieurs messages à copier, transférer ou supprimer. Voir [Matrix](#matrix).",
  "**More in your chats and groups**: choose several messages to copy, forward or delete at once; end your polls; reply in threads in groups; give a group a description; and send a contact from your phone as a card. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Plus dans tes discussions et tes groupes** : choisis plusieurs messages à copier, transférer ou supprimer d’un coup ; termine tes sondages ; réponds dans des fils dans les groupes ; donne une description à un groupe ; et envoie un contact de ton téléphone comme carte. Voir [Discuter par un relais](#relay) et [Discussions de groupe](#groups).",
  "**Ticks**: a text the other phone had, and read, before it showed as sent here (through a slow Nostr relay) now shows as read, not with one tick. Ticks from a contact on another relay no longer stop, and a text that reaches a phone while Erevos is in the background there gets its second tick at that phone's next check.":
    "**Coches** : un texte que l’autre téléphone avait déjà et avait lu avant qu’il s’affiche ici comme envoyé (par un relais Nostr lent) s’affiche maintenant comme lu, et non avec une seule coche. Les coches d’un contact sur un autre relais ne s’arrêtent plus, et un texte qui arrive sur un téléphone pendant qu’Erevos y est en arrière-plan reçoit sa deuxième coche à la prochaine vérification de ce téléphone.",
  "**Stickers on other networks**: a built-in sticker sent on Matrix, XMPP, Nostr or by MMS arrives as its picture, made on your device, its words in your language. See [Chat through a relay](#relay).":
    "**Des stickers sur d’autres réseaux** : un sticker intégré envoyé sur Matrix, XMPP, Nostr ou par MMS arrive comme son image, faite sur ton appareil, ses mots dans ta langue. Voir [Discuter par un relais](#relay).",
  "**One button for all your services**: under the search on the home screen, one button says which service shows, with the messages not read and any service not connected now. Tap it for a window with every service as a card, each with its own number and a dot for its connection; **Add** turns more on, and holding a card moves it or hides it. With no search, the chats with messages not read come first, under **Unread**, then the rest under **Recent**. See [Getting started](#start).":
    "**Un bouton pour tous tes services** : sous la recherche de l’écran d’accueil, un bouton dit quel service s’affiche, avec les messages non lus et tout service qui n’est pas connecté en ce moment. Appuie dessus pour une fenêtre avec chaque service en carte, chacune avec son nombre et un point pour sa connexion ; **Ajouter** en active d’autres, et maintenir une carte appuyée la déplace ou la masque. Sans recherche, les conversations avec des messages non lus viennent d’abord, sous **Non lus**, puis les autres sous **Récents**. Voir [Premiers pas](#start).",
  "**Share an imported chat with the other person**: a Telegram, WhatsApp or Viber chat that goes on with an Erevos contact can now go to them too, from the chat's **Details** or **Settings** → **Data and devices** → **Imported chats**: every message, photo, video, voice message and file, end-to-end encrypted, to them alone, whatever its size. Their Erevos keeps the messages at once and shows them ahead of the new messages, the sides swapped; the files follow in rounds through your relay while both phones run Erevos, each up to 4 GB, as large as an import now keeps. See [Imported chats](#import).":
    "**Partage une discussion importée avec l’autre personne** : une discussion Telegram, WhatsApp ou Viber qui continue avec un contact Erevos peut désormais lui aller aussi, depuis les **Détails** de la discussion ou depuis **Réglages** → **Données et appareils** → **Discussions importées** : chaque message, photo, vidéo, message vocal et fichier, chiffré de bout en bout, à lui seul, quelle que soit sa taille. Son Erevos garde aussitôt les messages et les montre avant les nouveaux messages, les côtés inversés ; les fichiers suivent par tours via ton relais tant qu’Erevos tourne sur les deux téléphones, chacun jusqu’à 4 Go, aussi gros qu’une importation en garde désormais. Voir [Discussions importées](#import).",
  "**Tor for your XMPP account, and per chat**: on Android, the XMPP screen, and the one before signing in, chooses **Off** (the default), **As the space** or **Always through Tor** for the account: its connection, the look for its server and its files, never straight when it must not. **Through Tor** under any XMPP chat or group, off by default, sends the whole account only through Tor while on, as one connection carries all its chats. Calls do not go through Tor. Before you send while the account does not go through Tor, before a call and before a file from another server, Erevos says once that your internet address can be seen, and how not to. See [XMPP](#xmpp).":
    "**Tor pour ton compte XMPP, et par discussion** : sur Android, l’écran XMPP, et celui d’avant la connexion, choisit pour le compte **Désactivé** (par défaut), **Comme l’espace** ou **Toujours par Tor** : sa connexion, la recherche de son serveur et ses fichiers, jamais en direct quand il ne doit pas. **Par Tor** sous toute discussion ou tout groupe XMPP, désactivé par défaut, fait passer tout le compte seulement par Tor tant qu’il est activé, car une connexion porte toutes ses discussions. Les appels ne passent pas par Tor. Avant que tu envoies tant que le compte ne passe pas par Tor, avant un appel et avant un fichier d’un autre serveur, Erevos dit une fois que ton adresse internet peut être vue, et comment l’éviter. Voir [XMPP](#xmpp).",
  "**Tor for Messenger and Signal, and per chat**: in Erevos+, the Messenger and Signal screens, and the ones before signing in, choose **Off** (the default), **As the space** or **Always through Tor** for the account. With it, everything of the account goes through Tor, its pictures and files too, and Messenger's sign-in page and Signal's registering, captcha and linking as well: never straight when it must not. **Through Tor** under any of their chats, off by default, sends the whole account only through Tor while on, as each has one connection. Calls do not go through Tor.":
    "**Tor pour Messenger et Signal, et par discussion** : dans Erevos+, les écrans de Messenger et de Signal, aussi avant la connexion, choisissent pour le compte **Désactivé** (par défaut), **Comme l’espace** ou **Toujours par Tor**. Avec cela, tout le compte passe par Tor, ses images et fichiers aussi, ainsi que la page de connexion de Messenger et l’inscription, le captcha et l’association de Signal : jamais en direct quand il ne le doit pas. **Par Tor** sous chacune de leurs discussions, désactivé par défaut, fait passer tout le compte uniquement par Tor tant qu’il est activé, car chacun a une seule connexion. Les appels ne passent pas par Tor.",
  "**Telegram: Tor as every account, and per chat**: on Android, **Tor for this Telegram account**, in Telegram's settings and before signing in, has **Off** (the default), **As the space** and **Always through Tor**, as every account of another network. With Always, or while the space sends Everything through Tor, Telegram is reached only through Tor, signing in too, and never straight, not even when Tor cannot connect. **Through Tor** in a Telegram chat's info sends that chat only through Tor, and with it the whole account, which has one connection. Calls do not go through Tor. See [Telegram (ErevosGram)](#telegram).":
    "**Telegram : Tor comme pour tout compte, et par discussion** : sur Android, **Tor pour ce compte Telegram**, dans les réglages Telegram et avant la connexion, propose **Désactivé** (au départ), **Comme l’espace** et **Toujours par Tor**, comme tout compte d'un autre réseau. Avec Toujours, ou tant que l'espace fait tout passer par Tor, Telegram n'est joint que par Tor, à la connexion aussi, et jamais en direct, même quand Tor ne peut pas se connecter. **Par Tor** dans les infos d'une discussion Telegram fait passer cette discussion uniquement par Tor, et avec elle tout le compte, qui n'a qu'une connexion. Les appels ne passent pas par Tor. Voir [Telegram (ErevosGram)](#telegram).",
  "**Nostr: Tor as every account, and per chat**: on Android, the **Nostr chats** screen, before a key is made or brought too, has **Off** (the default, also for keys from before), **As the space** and **Always through Tor** for the account: its relays, look-ups and file servers, never straight when it must not (Always, or the space's Everything). **Through Tor** at the foot of a Nostr chat, off by default, sends that chat alone only through Tor, on circuits of its own, whatever the account says; what comes to you follows the account. See [Chats with other Nostr apps](#nostr-chats).":
    "**Nostr : Tor comme pour chaque compte, et par discussion** : sur Android, l’écran **Discussions Nostr**, aussi avant qu’une clé soit faite ou apportée, a **Désactivé** (par défaut, aussi pour les clés d’avant), **Comme l’espace** et **Toujours par Tor** pour le compte : ses relais, recherches et serveurs de fichiers, jamais en direct quand il ne le doit pas (Toujours, ou le Tout de l’espace). **Via Tor** au bas d’une discussion Nostr, désactivé par défaut, envoie cette seule discussion uniquement par Tor, sur des circuits à elle, quoi que dise le compte ; ce qui t’arrive suit le compte. Voir [Discussions avec d’autres applis Nostr](#nostr-chats).",
  "**Telegram warns before your internet address can be seen**: once in each Telegram chat, before the first message, file, sticker, voice message, poll or forward while the account does not go through Tor, with **Through Tor** for that chat to fix it, **Guide** or **Go on**; before every Telegram call, made or answered, as calls never go through Tor; and before joining a group or channel by its link. See [Who sees your internet address](#ip).":
    "**Telegram prévient avant que ton adresse internet puisse être vue** : une fois dans chaque discussion Telegram, avant le premier message, fichier, sticker, message vocal, sondage ou transfert tant que le compte ne passe pas par Tor, avec **Par Tor** pour cette discussion pour y remédier, **Guide** ou **Continuer** ; avant chaque appel Telegram, passé ou reçu, car les appels ne passent jamais par Tor ; et avant de rejoindre un groupe ou une chaîne par son lien. Voir [Qui voit ton adresse internet](#ip).",
  "**Erevos or Erevos+, and betas, in Updates**: on Android, **Updates** now chooses the next update: **Erevos** or **Erevos+**, moving from one to the other with everything kept, and **Beta versions**, to join the betas, which come out first for trying, or leave them. See [Erevos or Erevos+, and betas](#updates).": "**Erevos ou Erevos+, et bêtas, dans Mises à jour** : sur Android, **Mises à jour** choisit maintenant la prochaine mise à jour : **Erevos** ou **Erevos+**, en passant de l’un à l’autre sans rien perdre, et **Versions bêta**, pour rejoindre les bêtas, qui sortent d’abord pour essayer, ou les quitter. Voir [Erevos ou Erevos+, et bêtas](#updates).",
  "**Matrix, XMPP and Nostr chats are in Erevos+**: Erevos now has its own chats, the Phone, SMS and the Collection, and Erevos+ has Matrix, XMPP and the chats with other Nostr apps besides. An account you had on them stays on the phone, encrypted, and Erevos says so once; choose **Erevos+** in **Updates** to have it again. Erevos's own messages still go through Nostr relays when no relay of yours takes them. See [Erevos or Erevos+, and betas](#updates).": "**Les discussions Matrix, XMPP et Nostr sont dans Erevos+** : Erevos a maintenant ses propres discussions, le Téléphone, les SMS et la Collection, et Erevos+ a en plus Matrix, XMPP et les discussions avec d’autres applications Nostr. Un compte que vous y aviez reste sur le téléphone, chiffré, et Erevos le dit une fois ; choisissez **Erevos+** dans **Mises à jour** pour le retrouver. Les messages propres à Erevos passent toujours par des relais Nostr quand aucun de vos relais ne les prend. Voir [Erevos ou Erevos+, et bêtas](#updates).",
  "**Radio and TV through Tor**: the Collection's settings on Android have **Play through Tor**, off unless you turn it on. On, stations and channels play only through Tor, so they do not see your IP address; TV may stall for a moment. Off, Erevos says before the first one plays that its server sees your IP address, with a button that turns it on. Before, they always played straight. See [Collection](#collection).": "**Radio et TV par Tor** : les réglages de la Collection sur Android ont **Lire par Tor**, désactivé tant que vous ne l’activez pas. Activé, les stations et les chaînes sont lues uniquement par Tor, donc elles ne voient pas votre adresse IP ; la TV peut se figer un instant. Désactivé, Erevos dit avant la première lecture que son serveur voit votre adresse IP, avec un bouton qui l’active. Avant, elles étaient toujours lues en direct. Voir [Collection](#collection).",
  "**A chat no longer freezes before a message sent for later shows**: a message your contact sends with **Send later** can come before its time, and shows only then. Until then its chat was marked read again and again without end, so it could stop answering: **⋮** opened nothing and **Back** did not leave it until Erevos was closed. Now such a message is read once it shows. See [Chat through a relay](#relay).": "**Une discussion ne se fige plus avant qu'un message envoyé pour plus tard apparaisse** : un message que ton contact envoie avec **Envoyer plus tard** peut arriver avant son heure, et n'apparaît qu'alors. Jusque-là, sa discussion était marquée comme lue encore et encore, sans fin, si bien qu'elle pouvait cesser de répondre : **⋮** n'ouvrait rien et **Retour** n'en sortait pas tant qu'Erevos n'était pas fermé. Désormais, un tel message est lu dès qu'il apparaît. Voir [Discuter par un relais](#relay).",
  "**Choose the part Erevos opens on**: under **All services**, hold any card, **All messages** too, and choose **Opens first**. Erevos's icon in the launcher, and Erevos started with nothing else to open, then open on it; with none chosen, or the chosen one hidden, on **All messages**. Before, the icon always opened the Erevos chats. The widget's buttons still open their own. See [Getting started](#start).": "**Choisis où Erevos s’ouvre** : dans **Tous les services**, maintiens appuyée n’importe quelle carte, **Tous** aussi, et choisis **S’ouvre en premier**. L’icône d’Erevos dans le lanceur, et Erevos lancé sans rien d’autre à ouvrir, s’ouvrent alors là ; sans choix, ou si celle choisie est masquée, sur **Tous**. Avant, l’icône ouvrait toujours les discussions Erevos. Les boutons du widget ouvrent toujours les leurs. Voir [Premiers pas](#start).",
  "**Asked before strangers reach this phone**: an Erevos invite that comes by SMS is answered by itself only from a number in your contacts or one you have written to; from any other, Erevos asks first, as the sender of an SMS can be made up. A contact's invite to a place on their relay now says first that their relay sees your IP address, and is taken only if you go on. See [Who sees your internet address](#ip).": "**On demande avant que des inconnus atteignent ce téléphone** : une invitation Erevos qui arrive par SMS n’obtient de réponse automatique que d’un numéro de tes contacts ou d’un numéro auquel tu as écrit ; pour tout autre, Erevos demande d’abord, car l’expéditeur d’un SMS peut être inventé. L’invitation d’un contact à une place sur son relais dit maintenant d’abord que son relais voit ton adresse IP, et n’est prise que si tu continues. Voir [Qui voit ton adresse internet](#ip).",
  "**Notices in your language**: Android's own notices and screens, new versions, reminders, birthdays, calls, SMS codes and the contact picker, now speak German, Spanish, French, Italian, Portuguese and Serbo-Croatian too, not only Greek and English. Older Greek subtitles, not saved as UTF-8, now show as Greek on the computer. See [Collection](#collection).": "**Des notifications dans ta langue** : les notifications et les écrans propres d’Android, les nouvelles versions, les rappels, les anniversaires, les appels, les codes SMS et le sélecteur de contacts parlent maintenant aussi allemand, espagnol, français, italien, portugais et serbo-croate, et plus seulement grec et anglais. Les anciens sous-titres grecs, non enregistrés en UTF-8, s’affichent maintenant en grec sur l’ordinateur. Voir [Collection](#collection).",
  "**Video calls on the computer, and the calculator after a wipe**: a video call started or answered on the computer now opens its camera. With the calculator in place of Erevos's icon, once Erevos is wiped by the panic password or **Clear storage**, the calculator opens Erevos as new and gives Erevos's icon back, where before no code opened it any more. See [Appearance](#appearance).": "**Appels vidéo sur l’ordinateur, et la calculatrice après un effacement** : un appel vidéo lancé ou décroché sur l’ordinateur ouvre maintenant sa caméra. Avec la calculatrice à la place de l’icône d’Erevos, une fois Erevos effacé par le mot de passe de panique ou par **Vider le stockage**, la calculatrice ouvre Erevos comme neuf et rend l’icône d’Erevos, alors qu’avant aucun code ne l’ouvrait plus. Voir [Apparence](#appearance).",
  "**Last seen starts off**: in a new space, **Last seen** is now off until you turn it on, so no contact sees when you last had Erevos open, and you see no one's either. A space you already have keeps it as it was. See [Chat through a relay](#relay).": "**Vu pour la dernière fois commence désactivé** : dans un nouvel espace, **Vu pour la dernière fois** est maintenant désactivé jusqu’à ce que tu l’actives, donc aucun contact ne voit quand tu as eu Erevos ouvert pour la dernière fois, et tu ne vois celle de personne. Un espace que tu as déjà le garde comme il était. Voir [Discuter par un relais](#relay).",
  "**A chat with a big file no longer closes Erevos**: on Android, opening a chat that held a large file, or one shared in many pieces, could close Erevos at once. Now it opens. See [Chat through a relay](#relay).": "**Une discussion avec un gros fichier ne ferme plus Erevos** : sur Android, ouvrir une discussion contenant un gros fichier, ou un fichier partagé en de nombreux morceaux, pouvait fermer Erevos aussitôt. Désormais elle s'ouvre. Voir [Discuter par un relais](#relay).",
  "**A hidden service stays quiet**: a service you hide in the **Services** window, Messenger, Matrix, SMS or any other, no longer sends notifications or counts on Erevos's icon, as a muted chat. It stays connected and tells again once you show it. Telegram, whose folders can stand on home of their own, keeps telling. See [Getting started](#start).": "**Un service masqué reste silencieux** : un service que tu masques dans la fenêtre **Services**, Messenger, Matrix, SMS ou un autre, n’envoie plus de notifications et ne compte plus dans le nombre sur l’icône d’Erevos, comme une discussion en sourdine. Il reste connecté et prévient de nouveau dès que tu l’affiches. Telegram, dont les dossiers peuvent figurer à l’accueil comme services à part, continue de prévenir. Voir [Getting started](#start).",
  "**Screenshots in hidden chats too, if you want**: hidden chats now follow **Screenshots** in **Privacy and security**: on, as it starts, they stay out of screenshots and the recent apps; turned off, screenshots work in them as in the other chats. Before, hidden chats always kept them out. See [Hidden chats](#hidden).": "**Des captures dans les discussions masquées aussi, si tu veux** : les discussions masquées suivent désormais **Captures d’écran** dans **Confidentialité et sécurité** : activé, comme au départ, elles restent hors des captures et des applis récentes ; désactivé, les captures y fonctionnent comme dans les autres discussions. Avant, les discussions masquées les bloquaient toujours. Voir [Discussions masquées](#hidden).",
  "**Messenger signs in on facebook.com, and opens Facebook**: in Erevos+, Messenger now signs in on Facebook's own page. **Open Facebook** on the Messenger screen shows Facebook itself with the same sign-in: its Messenger links come back to Erevos's chats, and other links open in your browser without Facebook's tracking marks and never through Tor, so the site sees your internet address. An account signed in on messenger.com before signs out and in again once to open Facebook.":
    "**Messenger se connecte sur facebook.com et ouvre Facebook** : dans Erevos+, Messenger se connecte désormais sur la page même de Facebook. **Ouvrir Facebook** sur l’écran de Messenger montre Facebook lui-même avec la même connexion : ses liens Messenger reviennent aux discussions d’Erevos, et les autres liens s’ouvrent dans ton navigateur sans les marques de pistage de Facebook et jamais par Tor, si bien que le site voit ton adresse internet. Un compte connecté auparavant sur messenger.com se déconnecte et se reconnecte une fois pour ouvrir Facebook.",
  "**Messenger, Signal and Session chats send more, and stay read**: in Erevos+, **+** in their chats sends a photo from your photos or the camera, a file or a sticker, and the microphone records a voice message. Your own messages show their words, where before some came empty; tapping a person with no Messenger chat yet opens a new one; and chats you mark read no longer come back unread.":
    "**Les discussions Messenger, Signal et Session envoient plus et restent lues** : dans Erevos+, **+** dans leurs discussions envoie une photo de tes photos ou de l’appareil photo, un fichier ou un autocollant, et le micro enregistre un message vocal. Tes propres messages montrent leurs mots, là où certains arrivaient vides ; toucher une personne sans discussion Messenger en ouvre une nouvelle ; et les discussions marquées comme lues ne redeviennent plus non lues.",
  "**Every copy carries its licences**: the Android app, the computer and Sailfish apps and the web app now carry the file NOTICES.txt, with Erevos's licence, AUTHORS.md and every package Erevos is built from, each with its licence text. See [Licence](#licence).": "**Chaque copie porte ses licences** : l’app Android, les apps pour ordinateur et Sailfish et l’app web contiennent désormais le fichier NOTICES.txt, avec la licence d’Erevos, AUTHORS.md et chaque paquet dont Erevos est fait, chacun avec le texte de sa licence. Voir [Licence](#licence).",
  "**A ready list of radio stations**: **Add a station** in the Collection's Radio now adds a country's most listened stations from Radio Browser at once, up to 100, with **Add the stations of this country**; the country is the phone's, and **Change** picks another. See [Collection](#collection).": "**Une liste toute prête de stations de radio**: **Ajouter une station** dans la Radio de la Collection ajoute maintenant d’un coup les stations les plus écoutées d’un pays depuis Radio Browser, jusqu’à 100, avec **Ajouter les stations de ce pays** ; le pays est celui du téléphone, et **Changer** en choisit un autre. Voir [Collection](#collection).",
  "**A new look to start with**: Erevos, newly installed, starts in Glass (Panes), Modernist, System, My color in sky blue, the phone's letters and square messages. A look you chose before stays as it was. See [Appearance](#appearance).": "**Un nouvel aspect pour commencer**: Erevos, tout juste installé, commence en Glass (Vitres), Modernist, Système, Ma couleur en bleu ciel, la police du téléphone et des messages carrés. Un aspect choisi avant reste tel qu’il était. Voir [Apparence](#appearance).",
  "**Modules names only what Erevos has**: under **Settings** → **General**, **Modules** no longer lists Nostr, Matrix and XMPP, which are in Erevos+.": "**Modules ne nomme que ce qu’Erevos a**: dans **Réglages** → **Général**, **Modules** ne nomme plus Nostr, Matrix et XMPP, qui sont dans Erevos+.",
  "**The guide tells only of what Erevos has**: in Erevos, the user guide no longer speaks of Matrix, XMPP and the chats with other Nostr apps, which are in Erevos+. See [Erevos or Erevos+, and betas](#updates).": "**Le guide ne parle que de ce qu’Erevos a**: dans Erevos, le guide ne parle plus de Matrix, d’XMPP ni des discussions avec d’autres applis Nostr, qui sont dans Erevos+. Voir [Erevos ou Erevos+, et bêtas](#updates).",
  "**Meeting someone in one tap**: **New chat** now starts with two big buttons, **Scan their QR code** and **Show your QR code**; one of you scanning the other is enough, and the rest is under them. See [Chat through a relay](#relay).": "**Rencontrer quelqu’un d’un toucher** : **Nouvelle discussion** commence maintenant par deux grands boutons, **Scanner son code QR** et **Montrer ton code QR** ; il suffit que l’un de vous scanne l’autre, et le reste est en dessous. Voir [Discuter par un relais](#relay).",
  "**The panic button, found at once**: it is first, in red, in the **⋯** menu of the home screen, and holding down the lock at the top of the home screen opens it. See [Panic button](#panic).": "**Le bouton de panique, trouvé tout de suite** : il est le premier, en rouge, dans le menu **⋯** de l’écran d’accueil, et maintenir appuyé le cadenas en haut de l’écran d’accueil l’ouvre. Voir [Bouton de panique](#panic).",
  "**New chat looks the same every time**: the two big buttons are always at the top; **How you connect now** shows only while something is missing, and says it in plain words; **Your contact link** and **Invite someone** are rows, with no second QR code button. See [Chat through a relay](#relay).": "**La nouvelle discussion a toujours le même aspect** : les deux grands boutons sont toujours en haut ; **Comment tu te connectes maintenant** n’apparaît que tant qu’il manque quelque chose, et le dit avec des mots simples ; **Ton lien de contact** et **Inviter quelqu’un** sont des lignes, sans second bouton de code QR. Voir [Discuter par un relais](#relay).",
  "**One scan is all**: where your relay lets your phone invite, **Show your QR code** shows an invite for one person, so a phone new to Erevos joins your relay by itself as it scans it, typing nothing, and you are contacts at once; for someone else, tap **New QR code**. And with a relay, its queue is made by itself: **Create my relay queue** is there only to try again, should that fail. See [Chat through a relay](#relay).": "**Un seul scan suffit** : là où ton relais laisse ton téléphone inviter, **Montrer ton code QR** montre une invitation pour une personne, si bien qu’un téléphone nouveau sur Erevos rejoint seul ton relais en la scannant, sans rien taper, et vous êtes contacts aussitôt ; pour quelqu’un d’autre, touche **Nouveau code QR**. Et avec un relais, sa file d’attente se crée toute seule : **Créer ma file d’attente sur le relais** ne sert plus qu’à réessayer, si cela échoue. Voir [Discuter par un relais](#relay).",
  "**Video calls take about half the data**: a video call over the internet goes through the call relay, so that neither side sees the other's address; its picture is now held to 1 Mbps, which on a phone looks much the same. A call on the same network is not held back.": "**Les appels vidéo consomment environ moitié moins de données** : un appel vidéo par internet passe par le relais d’appels, pour qu’aucun des deux ne voie l’adresse de l’autre ; son image est maintenant limitée à 1 Mbit/s, ce qui sur un téléphone paraît presque pareil. Un appel sur le même réseau n’est pas bridé.",
  "**A stranger's message shows only its words**: a message request, from someone who has only your contact link, shows only what it says until you accept it. Its photos and files wait, not taken, and its links show no preview. See [Chat through a relay](#relay).": "**Le message d’un inconnu ne montre que ses mots** : une demande de message, de quelqu’un qui n’a que ton lien de contact, ne montre que ce qu’elle dit tant que tu ne l’acceptes pas. Ses photos et fichiers attendent sans être téléchargés, et ses liens n’ont pas d’aperçu. Voir [Discuter par un relais](#relay).",
  "**Photos sent as files say nothing of where they were taken**: a photo sent with **File** (JPEG, PNG, GIF or WebP) goes without where and when it was taken and the phone, as a photo does; a GIF sent as a photo keeps moving, now without its hidden notes.": "**Les photos envoyées comme fichiers ne disent pas où elles ont été prises** : une photo envoyée avec **Fichier** (JPEG, PNG, GIF ou WebP) part sans le lieu, l’heure ni le téléphone, comme une photo ; un GIF envoyé comme photo bouge toujours, désormais sans ses notes cachées.",
  "**A word of care over a stranger's first messages**: if a message request asks for a code, a PIN, a password or money, promises easy money, or its name looks like one of your contacts', **Be careful** says so above it. Erevos looks for this on your phone only, and blocks nothing. See [Chat through a relay](#relay).": "**Un mot de prudence sur les premiers messages d’un inconnu** : si une demande de message demande un code, un PIN, un mot de passe ou de l’argent, promet de l’argent facile, ou si son nom ressemble à celui d’un de tes contacts, **Attention** le dit au-dessus. Erevos le cherche sur ton téléphone seulement, et ne bloque rien. Voir [Discuter par un relais](#relay).",
  "**Tor finds its own way through**: under **Bridges**, **Automatic** tries Tor straight, then the obfs4 bridges, then Snowflake, then your own, until one connects, and remembers for 30 days the one that worked on Wi-Fi and on mobile data. **My network is watched** makes it never try straight, and **Check my connection** says whether Tor connects, and how, never your address. See [Through Tor](#tor).": "**Tor trouve son chemin tout seul** : dans **Ponts**, **Automatique** essaie Tor en direct, puis les ponts obfs4, puis Snowflake, puis les tiens, jusqu’à ce que l’un se connecte, et retient pendant 30 jours celui qui a marché en Wi-Fi et en données mobiles. **Mon réseau est surveillé** l’empêche d’essayer en direct, et **Vérifier ma connexion** dit si Tor se connecte, et comment, jamais ton adresse. Voir [Par Tor](#tor).",
  "**The bar at the top stays**: on the home screen, the bar with Erevos and its buttons no longer scrolls away with the list, and in SMS chats, as in those of the other networks, the name of the chat, its calls and who is online stay at the top while the messages scroll, as in Erevos's own chats.": "**La barre du haut reste en place** : sur l’écran d’accueil, la barre avec Erevos et ses boutons ne défile plus avec la liste, et dans les chats SMS, comme dans ceux des autres réseaux, le nom du chat, ses appels et qui est en ligne restent en haut pendant que les messages défilent, comme dans les chats propres à Erevos.",
  "**A simpler field in Matrix and XMPP chats**: under it there is only **+**, for photos, files and the rest, and the microphone; the chat's settings are under **⋯** at the top.": "**Un champ plus simple dans les chats Matrix et XMPP** : dessous, il n’y a plus que **+**, pour les photos, les fichiers et le reste, et le micro ; les réglages du chat sont en haut, sous **⋯**.",
  "**Adding a contact with 8 digits**: **Pair with a code** on **New chat** lets one phone show a code of 8 digits and the other type it, said aloud or read off the screen, and you are each other's contacts, with no QR code or link to pass. The code never leaves the phones, and whoever guesses gets 3 tries. See [Chat through a relay](#relay).": "**Ajouter un contact avec 8 chiffres** : **Associer avec un code** dans **Nouvelle discussion** permet à un téléphone de montrer un code de 8 chiffres et à l’autre de le taper, dit à voix haute ou lu sur l’écran, et vous êtes contacts l’un de l’autre, sans code QR ni lien à passer. Le code ne quitte jamais les téléphones, et qui devine a 3 essais. Voir [Discuter par un relais](#relay).",
  "**A voice not your own**: in a contact's chat details, **Change my voice** sends your voice messages in that chat **Deeper** or **Higher**, as long as you spoke. The change is made on your phone before the message goes, so your own voice never leaves it. On Android 10 and later, and in browsers that make Opus themselves. See [Chat through a relay](#relay).": "**Une voix qui n’est pas la tienne** : dans les détails de la discussion avec un contact, **Changer ma voix** envoie tes messages vocaux de cette discussion **Plus grave** ou **Plus aiguë**, de la même durée. Le changement se fait sur ton téléphone avant que le message parte, ta propre voix ne le quitte donc jamais. Sur Android 10 et plus récent, et dans les navigateurs qui font eux-mêmes de l’Opus. Voir [Discuter par un relais](#relay).",
  "**A word of care under a short password**: setting the password of a space or the PIN of hidden chats, Erevos now says when it is short: someone who breaks into the phone's own security could guess it on computers of their own. A phrase of 4 or 5 words is far safer. It still takes a short one. See [Password lock](#lock).": "**Un mot de prudence sous un mot de passe court** : en définissant le mot de passe d’un espace ou le code des discussions masquées, Erevos dit maintenant quand il est court : quelqu’un qui casse la sécurité du téléphone lui-même pourrait le deviner sur ses propres ordinateurs. Une phrase de 4 ou 5 mots est bien plus sûre. Il accepte quand même un mot de passe court. Voir [Verrou par mot de passe](#lock).",
  "**Groups that end**: a public group can now be a burner group, for one event. Under **It ends**, choose after a day, 3 days or 7 days, and when its time is up every member's Erevos deletes it, with its messages, photos and files, and its link stops working. See [public groups](#public-groups).": "**Des groupes qui prennent fin** : un groupe public peut désormais être jetable, pour une occasion. Sous **Fin**, choisissez après un jour, 3 jours ou 7 jours, et quand son temps est écoulé l’Erevos de chaque membre le supprime, avec ses messages, photos et fichiers, et son lien ne fonctionne plus. Voir [Groupes publics](#public-groups).",
  "**A photo to see once**: under **+** in a chat or a group, **Photo to see once** sends a photo that never shows in the chat, and **Camera, to see once** one you take then. They see it once, on its own, kept out of screenshots where the phone allows, and as it closes it is deleted from their phone. It cannot be forwarded or saved. See [Chat through a relay](#relay).": "**Une photo à voir une fois** : sous **+** dans une discussion ou un groupe, **Photo à voir une fois** envoie une photo qui n’apparaît jamais dans la discussion, et **Appareil photo, à voir une fois** une que tu prends sur le moment. Ils la voient une fois, seule, sans captures d’écran là où le téléphone le permet, et à la fermeture elle est supprimée de leur téléphone. Elle ne peut être ni transférée ni enregistrée. Voir [Discuter par un relais](#relay).",
  "**Threads in a contact's chat too**: hold a message and choose **Reply in thread**, as in a group. The thread shows alone and what you send there answers it; **n answers in the thread** under a message opens it. See [Chat through a relay](#relay).": "**Des fils aussi dans la discussion avec un contact** : maintenez un message et choisissez **Répondre dans le fil**, comme dans un groupe. Le fil s’affiche seul et ce que vous y envoyez y répond ; **n réponses dans le fil** sous un message l’ouvre. Voir [Discuter par un relais](#relay).",
  "**A voice message in words**: hold a voice message and choose **In words**, and your phone writes out what was said, in about a hundred languages, Greek among them. The first time it downloads a speech model of 268 MB, once you say so; then everything is done on your phone, and neither the sound nor its words leave it. On Android. See [Chat through a relay](#relay).": "**Un message vocal en mots** : maintiens un message vocal et choisis **En mots**, et ton téléphone écrit ce qui a été dit, dans une centaine de langues, dont le grec. La première fois, il télécharge un modèle vocal de 268 Mo, quand tu le dis ; ensuite tout se fait sur ton téléphone, et ni le son ni ses mots ne le quittent. Sur Android. Voir [Discuter par un relais](#relay).",
  "**Translate a message**: hold a message and choose **Translate**, and your phone translates it into your language, between Greek, English, German, Spanish, French and Italian. The first time for a language it downloads its translation models, of 60 to 95 MB each, once you say so; then everything is done on your phone, and neither the message nor its translation leave it. On Android. See [Chat through a relay](#relay).": "**Traduire un message** : reste appuyé sur un message et choisis **Traduire**, et ton téléphone le traduit dans ta langue, entre le grec, l’anglais, l’allemand, l’espagnol, le français et l’italien. La première fois pour une langue, il télécharge ses modèles de traduction, de 60 à 95 Mo chacun, quand tu le dis ; ensuite tout se fait sur ton téléphone, et ni le message ni sa traduction ne le quittent. Sur Android. Vois [Discuter par un relais](#relay).",
  "**Phones nearby carry for each other from the start**: **Carry messages for others**, under **Nearby, with no internet** on **New chat**, is now on until you turn it off, so a message that cannot reach its relay finds more phones to take it there. What this phone carries is sealed: it cannot read it, nor tell who it is from or for. See [Chat with a nearby phone](#nearby).": "**Les téléphones à proximité transportent les uns pour les autres dès le départ** : **Transporter des messages pour d’autres**, sous **À proximité, sans internet** dans **Nouvelle discussion**, est désormais activé jusqu’à ce que tu le désactives, pour qu’un message qui n’atteint pas son relais trouve plus de téléphones pour l’y porter. Ce que ce téléphone transporte est chiffré : il ne peut ni le lire, ni savoir de qui il vient ni pour qui il est. Voir [Discuter avec un téléphone à proximité](#nearby).",
  "**Last seen is when they closed Erevos**: with **Say when I open and close Erevos** on, closing Erevos, or its hidden chats, now tells those you told while it was open when it closed, so their **last seen** is that time, not when they last heard from you. And you show online only while the chats they talk to you in are open: not while your hidden chats are open instead. See [Chat through a relay](#relay).": "**Vu pour la dernière fois, c’est quand Erevos a été fermé** : avec **Dire quand j’ouvre et ferme Erevos** activé, fermer Erevos, ou ses discussions cachées, dit désormais à ceux qui ont été prévenus pendant qu’il était ouvert quand il s’est fermé, donc leur **Vu pour la dernière fois** est cette heure-là, pas la dernière fois qu’ils ont eu de tes nouvelles. Et tu n’apparais en ligne que tant que les discussions où ils te parlent sont ouvertes : pas pendant que tes discussions cachées le sont à leur place. Voir [Discuter par un relais](#relay).",
  "**Sign in at another relay**: under **Sign in with LPHL** on New chat, **Sign in at another relay…** takes another relay's address, and the card signs in there with the accounts that relay takes; one that takes none says so, and its operator can give you an invite. See [Chat through a relay](#relay).": "**Se connecter à un autre relais** : sous **Se connecter avec LPHL** dans Nouvelle discussion, **Se connecter à un autre relais…** prend l’adresse d’un autre relais, et la carte s’y connecte avec les comptes que ce relais accepte ; un relais qui n’en accepte aucun le dit, et son responsable peut te donner une invitation. Voir [Discuter par un relais](#relay).",
  "**Post-quantum, all the way**: between two phones on this Erevos, every message of a chat is now also locked with a fresh ML-KEM key, a new one every few dozen messages, not only at the start. So someone who records your messages today and has a quantum computer one day still cannot read them. By itself, with nothing to turn on; not in groups.": "**Post-quantique de bout en bout** : entre deux téléphones avec cet Erevos, chaque message d’une discussion est désormais aussi chiffré avec une nouvelle clé ML-KEM, renouvelée toutes les quelques dizaines de messages, pas seulement au début. Ainsi, qui enregistre tes messages aujourd’hui et aura un jour un ordinateur quantique ne pourra toujours pas les lire. Tout seul, rien à activer ; pas dans les groupes.",
  "**The Collection asks for your password**: where the space has a password, the Collection asks for it each time it opens, and again after Erevos was away more than 30 seconds; a fingerprint or face works too. See [Collection](#collection).": "**La Collection demande ton mot de passe** : là où l’espace a un mot de passe, la Collection le demande chaque fois qu’elle s’ouvre, et de nouveau quand Erevos a été quitté plus de 30 secondes ; l’empreinte ou le visage marchent aussi. Voir [Collection](#collection).",
  "**Messenger in its case**: in Erevos+, Messenger can now be used in its case instead of by Erevos: Meta's own Messenger page, as on a computer, closed in by Erevos with the same sign-in. Only Meta's sites load in it, links out open in your browser without Facebook's tracking marks, nothing of the sign-in stays in it once closed, and calls work in it. Choose it on the Messenger screen under **How Messenger is used here**; its chats are then not in Erevos's lists and Erevos does not notify of them. Through Tor, if Messenger goes through Tor, and then without calls.":
    "**Messenger dans son étui** : dans Erevos+, Messenger peut maintenant être utilisé dans son étui au lieu de par Erevos : la page Messenger de Meta elle-même, comme sur un ordinateur, enfermée par Erevos avec la même connexion. Seuls les sites de Meta s'y chargent, les liens vers l'extérieur s'ouvrent dans ton navigateur sans les marques de suivi de Facebook, rien de la connexion n'y reste une fois fermée, et les appels y fonctionnent. Choisis-le sur l'écran Messenger sous **Comment Messenger est utilisé ici** ; ses discussions ne sont alors pas dans les listes d'Erevos et Erevos ne t'en avertit pas. Via Tor, si Messenger passe par Tor, et alors sans appels.",
  "**Messenger chats you read stay read**: a Messenger chat you marked read right after Erevos+ started, while Messenger was still connecting, no longer comes back as unread; a chat whose last message is yours, sent from Messenger's own app or the web, is read; and encrypted chats you read in Messenger's app or on the web are read here too.":
    "**Les discussions Messenger lues restent lues** : une discussion Messenger marquée comme lue juste après le démarrage d'Erevos+, pendant que Messenger se connectait encore, ne redevient plus non lue ; une discussion dont le dernier message est le tien, envoyé depuis l'application Messenger ou le web, est lue ; et les discussions chiffrées lues dans l'application Messenger ou sur le web sont lues ici aussi.",
  "**Messenger in its case fits the phone, and Facebook's feed is a tap away**: in Erevos+, Messenger in its case is now laid out at the phone's width, so it reads without zooming in, and shows under Erevos's own bar, in its colours, with **←** back to Erevos and **Facebook** to see Facebook's feed in the same page. Facebook also has a card of its own in the **Services** window, beside Messenger. See [Messenger](#messenger).":
    "**Messenger dans son étui tient sur le téléphone, et le fil de Facebook est à un geste**: dans Erevos+, Messenger dans son étui est maintenant mis à la largeur du téléphone, pour se lire sans zoomer, et s’affiche sous la barre d’Erevos, à ses couleurs, avec **←** pour revenir à Erevos et **Facebook** pour voir le fil de Facebook dans la même page. Facebook a aussi sa propre carte dans la fenêtre **Services**, à côté de Messenger. Voir [Messenger](#messenger).",
  "**Messenger in its case asks for the PIN once**: in Erevos+, what Meta's page keeps now stays in the case between openings, apart from every other page, so Meta knows your phone again and no longer asks for the PIN of your encrypted chats each time you open it. It goes when you sign out of Messenger, or when another account opens the case. See [Messenger](#messenger).":
    "**Messenger dans son étui ne demande le code PIN qu’une fois** : dans Erevos+, ce que garde la page de Meta reste désormais dans l’étui d’une ouverture à l’autre, à part de toute autre page, si bien que Meta reconnaît ton téléphone et ne demande plus le code PIN de tes discussions chiffrées à chaque ouverture. Cela s’efface quand tu te déconnectes de Messenger ou qu’un autre compte ouvre l’étui. Voir [Messenger](#messenger).",
  "**Messenger in its case wears your whole look**: in Erevos+, Meta's own Messenger page in its case now takes your look: its colours, dark or light as Erevos is, the shape of your bubbles (round, square or a line), your text size, your style's letters, and what lies behind your screens (a wallpaper, Neon's grid, Paper's lines and the others), and it changes with your look even while it is open. A photo of your own stays in Erevos: there the page shows a soft gradient instead. Where Meta changes its page, parts of it may keep Meta's look. See [Messenger](#messenger).":
    "**Messenger dans son étui porte toute ton apparence** : dans Erevos+, la page Messenger de Meta dans son étui prend maintenant ton apparence : ses couleurs, sombre ou claire comme Erevos, la forme de tes bulles (rondes, carrées ou une ligne), ta taille de texte, les lettres de ton style et ce qui se trouve derrière tes écrans (un fond d’écran, la grille de Neon, les lignes de Paper et les autres), et elle change avec ton apparence même lorsqu’elle est ouverte. Une photo à toi reste dans Erevos : la page montre alors un dégradé doux à la place. Là où Meta change sa page, certaines parties peuvent garder l’apparence de Meta. Voir [Messenger](#messenger).",
  "**Messenger in its case tells you of new messages**: in Erevos+, when you use Messenger in its case, Erevos now tells you of its new messages as it does of other chats, even if you never opened the case. A chat with messages not read shows on home until it is read, and tapping it opens it in the case; while the case is open, Erevos tells of nothing, as the page shows it. See [Messenger](#messenger).":
    "**Messenger dans son étui t’avertit des nouveaux messages** : dans Erevos+, quand tu utilises Messenger dans son étui, Erevos t’avertit maintenant de ses nouveaux messages comme des autres discussions, même si tu n’as jamais ouvert l’étui. Une discussion avec des messages non lus apparaît sur l’accueil jusqu’à sa lecture, et un appui l’ouvre dans l’étui ; tant que l’étui est ouvert, Erevos n’avertit de rien, puisque la page le montre. Voir [Messenger](#messenger).",
};
